from heapq import heappush, heappop 

class Solution: 
	def shortestPath(self, n, m, edges, src): 
		def dijsktra(adj): 
			q = [] 
			heappush(q, (0,src))
			dis = [99999]*(n) 
			dis[src]=0
			while len(q)!=0: 
				disu,w = heappop(q) 
				if disu<dis[w]: 
					dis[w]=disu 
					for u in adj[w]: 
						if dis[w]+1<dis[u[0]]: 
							heappush(q,(dis[w]+1, u[0])) 
							dis[u[0]]=dis[w]+1
			return dis 

		adj = dict()
		for i in range(n): 
			adj[i]=[] 

		for i in range(m): 
			adj[edges[i][0]].append([edges[i][1],1]) 
			adj[edges[i][1]].append([edges[i][0],1]) 

		t = dijsktra(adj) 
		res=[] 
		for i in t: 
			if i==99999: 
				res.append(-1) 
			else: 
				res.append(i) 

		return res 
