def padovanSequence(N):
    MOD = 10 ** 9 + 7
    if N <= 2:
        return 1

    p0, p1, p2 = 1, 1, 1

    for i in range(3, N + 1):
        p_next = (p0 + p1) % MOD
        p0, p1, p2 = p1, p2, p_next

    return p2

