class MultiThread(object):
    def __init__(self, min_jobs = 1, max_jobs = 3):
        """
            Parameters:
                min_jobs: The minimum number of threads to be used.
                          Note that besides this minimum, a thread is created for each job whenever no thread is idle.
                max_jobs: The maximum number of threads to be used.
        """
        if min_jobs < 1:
            print("Provide at least on thread")
            sys.exit(1)
        if max_jobs < min_jobs:
            print("Provide MAX number of thread greater or equal than MIN")
            sys.exit(1)

        self.MUTEX = threading.Lock()
        self.CONDITION = threading.Condition(self.MUTEX)
        self.IDLE_THREADS = min_jobs

        self.THREADS = [threading.Thread(target = self.__thread, args = ()) for _ in range(min_jobs)]
        self.JOBS = queue.Queue()
        self.SHOULD_SHUTDOWN = False

        for t in self.THREADS:
            t.start()

        self.MAX_JOBS = max_jobs

        self.COUNT_THREADS = min_jobs

    def __thread(self):
        while self.THREADS is not None:
            self.CONDITION.acquire()
            while self.JOBS.empty() and not self.SHOULD_SHUTDOWN:
                self.IDLE_THREADS -= 1

