class Solution:

	def commonElements(self, A, B, C, n1, n2, n3):
		p1 = 0
		p2 = 0
		p3 = 0
		ans = []
		curr_min = 9999
		while p1 < n1 and p2 < n2 and (p3 < n3):
			curr_min = min(min(A[p1], B[p2]), C[p3])
			if A[p1] == B[p2] == C[p3]:
				if len(ans) != 0 and ans[len(ans) - 1] != A[p1]:
					ans.append(A[p1])
				if len(ans) == 0:
					ans.append(A[p1])
				p1 += 1
				p2 += 1
				p3 += 1
			elif A[p1] == curr_min:
				p1 += 1
			elif B[p2] == curr_min:
				p2 += 1
			else:
				p3 += 1
		return ans

class Solution:

	def minSteps(self, N):

		def fun(n):
			if n == 1:
				return 0
			if dp[n] != -1:
				return dp[n]
			res = 0
			res = fun(n - 1)
			if n % 2 == 0:
				res = min(res, fun(n // 2))
			if n % 3 == 0:
				res = min(res, fun(n // 3))
			dp[n] = 1 + res
			return dp[n]
		dp = [-1] * (N + 1)
		return fun(N)

