from datetime import datetime, timedelta

def parse_time(time_str):
    return datetime.strptime(time_str, "%H:%M:%S")

def min_vehicles(departures, arrivals):
    events = []
    for d, a in zip(departures, arrivals):
        departure_time = parse_time(d)
        arrival_time = parse_time(a)
        events.append((departure_time, 1))  # train departs, increment vehicle count
        events.append((arrival_time, -1))   # train arrives, decrement vehicle count

    events.sort()

    min_trains = 0
    current_trains = 0

    for _, change in events:
        current_trains += change
        if current_trains > min_trains:
            min_trains = current_trains

    return min_trains

def main():
    import sys
    input = sys.stdin.read
    data = input().split('\n')

    i = 0
    results = []
    while i < len(data):
        n = int(data[i])
        if n == 0:
            break

        departures, arrivals = [], []
        for j in range(i + 1, i + 1 + n):
            d, a = data[j].split()
            departures.append(d)
            arrivals.append(a)

        results.append(min_vehicles(departures, arrivals))
        i += n + 1

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

