def super_acting(H, K):
	arr = [0 for _ in range(H)]
	arr[0] = H
	op = 1
	temp = H
	end = H
	i = 1
	while(i < K):
		i += 1
		if(i == 1):
			arr[i] = min(arr[i], temp - K +  1)
			for j in range(end-K, end-1):
				op += 1
				arr[i] = min(arr[i], arr[j]%H + 1)
		elif(i == K):
			for j in range(1, temp - K + 1):
				arr[i] = min(arr[i], arr[j], H + 1)
				for e in range(1, K+1):
					arr[i] = min(arr[i], arr[j+e]%H+1)
		else:
			if(i >= temp + K):
				end = i - 1
				temp = end
			if(temp - (i-1) >= H-K):
				op += 1
				temp -= K
			for j in range(end+1-K, end):
				arr[i] = min(arr[i], arr[j])
			for j in range(1, K+1):
				arr[i] = min(arr[i], arr[j])

	for i in range(1, H+1):
		arr[i] %= H + 1

	for i in range(1, H+1):
		arr[i] = int(arr[i])
		print(arr[i], end = " ")

	print()
	print(op, end = "\n")


