def find_dominant_piranha(n, a):
    # Check if the first piranha can be dominant
    if a[0] > a[1]:
        for i in range(1, n - 1):
            if a[i] > a[0]:
                break
        else:
            return 1

    # Check if the last piranha can be dominant
    if a[-1] > a[-2]:
        for i in range(n - 2, 0, -1):
            if a[i] > a[-1]:
                break
        else:
            return n

    # Check for any middle piranha that can be dominant
    for i in range(1, n - 1):
        if a[i] > a[i - 1] and a[i] > a[i + 1]:
            left = a[i - 1]
            right = a[i + 1]
            while left < a[i]:
                left += 1
                a[i] += 1
            while right < a[i]:
                right += 1
                a[i] += 1
            if left < a[i] and right < a[i]:
                return i + 1

    return -1

