def findK(self, A, N, M, K): 
		# code here
		l,r,u,d = 0,M-1,0,N-1
		count = 1
		# global numbered in the matrix array
		# returns the K^{th} element
		number = count
		while l < r and u < d:
			for i in range(l, r+1):
				count += 1
				if count == K:
					return A[u][i]
				number += 1

			for i in range(u + 1, d+1):
				count += 1
				if count == K:
					return A[i][r]
				number += 1

			for i in range(r, l, -1):
				count += 1
				if count == K:
					return A[d][i]
				number += 1


			for i in range(d-1, u, -1):
				count += 1
				if count == K:
					return A[i][l]
				number += 1
			# add them together
			# l{i for i in range(l, r+1)}
			# r+1 - l = block_ending - block_starting

			# increase the subarrays down by 1.
			d -= 1
			l += 1
			u += 1
			r -= 1

