class Solution:

	def merge(self, S1, S2):
		s = ''
		min_len = min(len(S1), len(S2))
		for i in range(min_len):
			s = s + (S1[i] + S2[i])
		if len(S1) < len(S2):
			return s + S2[min_len:]
		else:
			return s + S1[min_len:]

