def task_on_the_board(s, m, b):
	cha = [0 for i in range(26)]
	for c in s:
		cha[ord(c) - ord('a')] += 1
	k = 25
	res = [' ' for i in range(m)]
	cnt = 0
	prea = []
	while cnt != m:
		cura = []
		for i in range(len(b)):
			if res[i] == ' ' and b[i] == cal(prea, i):
				cura.append(i)
		while cha[k] < len(cura):
			k -= 1
		for i in cura:
			prea.append(i)
			res[i] = chr(97 + k)
		cnt += len(cura)
		k -= 1
	return res

def cal(prea, i):
	r = 0
	for p in prea:
		r += abs(p - i)
	return r
