public:
    int numberOfSubsequences(string text, string pattern) {
        int i = 0, j = 0;
        int n = text.size(), m = pattern.size();

        while(i < n && j < m) {
            if(text[i] == pattern[j]) {
                ++j;
            }
            ++i;
        }
        while(j < m) {
            if(pattern[j++] == 'a') ++j;
        }
        i = 0, j = 0;
        while(i < n && j < m) {
            if(text[i] == pattern[j]) {
                ++j;
            }
            ++i;
        }
        while(j < m) {
            if(pattern[j++] == 'b') ++j;
        }

        return i - m;
    }
};
