bool helper(TreeNode* root, vector<int>& res) {
    if(!root) return true;
    if(!root->left && !root->right) return false;

    if(helper(root->left, res) && helper(root->right, res)) {
        int curl = 0, curr = 0;

        if(root->left) curl = root->left->val;
        if(root->right) curr = root->right->val;
        res[curl] += res[curr] + 1;
    }
    return false;
}

int countPairs(TreeNode* root, int distance) {
    vector<int> res(distance + 1, 0);

    return helper(root, res);
}
