	for(int i = cnt - 1; i >= 0; i -- ) 

	{

		int p = (i + 1) * (i + 1) % mod * 2;

		p = p * qmi(n * (n - 1), mod - 2) % mod; 

		dp[i] = dp[i + 1] + qmi(p, mod - 2) % mod, dp[i] %= mod;

