class Solution
{
    public long beautifulSubstrings(String s, int k)
    {
        Set<Character> vSet = Set.of('a','e','i','o','u');
        long count = 0L;
        Map<Integer, Integer> pfs = getPFs(k);
        int hfK = 1;
        for (int pf : pfs.keySet())
        {
            int c = pfs.get(pf);
            int hfC = (c + 1) / 2;
            while (hfC > 0)
            {
                hfC--;
                hfK *= pf;
            }
        }
        int vs = 0;
        int cs = 0;
        Map<Integer, Map<Integer, Integer>> map = new HashMap<>();
        map.put(0, new HashMap<>());
        map.get(0).put(0, 1);
        for (int i = 0; i < s.length(); i++)
        {
            char ch = s.charAt(i);
            if (vSet.contains(ch))
            {
                vs++;
            }
            else
            {
                cs++;
            }
            int diff = vs - cs;
            Map<Integer, Integer> innerMap = map.getOrDefault(diff, new HashMap<>());
            int rem = vs % hfK;
            int prevRemCount = innerMap.getOrDefault(rem, 0);
            count += prevRemCount;
            innerMap.put(rem, prevRemCount + 1);
            map.put(diff, innerMap);
        }
        return count;
    }

    private Map<Integer, Integer> getPFs(int n)
    {
        Map<Integer, Integer> map = new HashMap<>();
        while (n % 2 == 0)
        {
            map.put(2, map.getOrDefault(2, 0) + 1);
            n /= 2;
        }
        for (int i = 3; i <= Math.sqrt(n); i += 2)
        {
            while (n % i == 0)
            {
                map.put(i, map.getOrDefault(i, 0) + 1);
                n /= i;
            }
        }
        if (n > 2)
        {
            map.put(n, map.getOrDefault(n, 0) + 1);
        }
        return map;
    }
}

