def get_fun_values(n):
    fun_values = set()
    for k in range(1, n + 1):
        visited = set()
        current = 1
        total = 0
        while current not in visited:
            visited.add(current)
            total += current
            current = (current + k - 1) % n + 1
        fun_values.add(total)
    return sorted(list(fun_values))

