def filter_db(database, given, word_length):
	ret_arr = []
	for word in database:
		test = True
		slot = -1
		while slot < word_length - 1:
			slot += 1
			if given[slot] == '*':
				if word[slot] in given:
					test = False
					break
				else:
					continue
			elif word[slot] == given[slot]:
				continue
			else:
				test = False
				break
		if test:
			ret_arr.append(word)
	return ret_arr

def find_correct_guesses(database, charset, given):
	ret_arr = []
	for char in charset:
		test = True
		for word in database:
			if char in word:
				continue
			test = False
		if test and char not in given:
			ret_arr.append(char)
	return ret_arr
