class Solution {
public:
    int furthestBuilding(vector<int>& heights, int bricks, int ladders) {
        priority_queue<pair<int, int>, vector<pair<int, int>>, less<pair<int, int>>> q;
        int i = 1;
        while (i < heights.size()) {
            if (heights[i] <= heights[i-1]) {
                ++i;
                continue;
            }
            int h = heights[i] - heights[i-1];
            if (h > bricks) {
                break;
            }
            bricks -= h;
            q.push({h, i});
            ++i;
        }
        printf("%d, %d \n", i, bricks);
        if (i == heights.size() || ladders == 0) {
            return i - 1;
        } 
        while (i < heights.size()) {
            if (heights[i] <= heights[i-1]) {
                ++i;
                continue;
            }
            int h = heights[i] - heights[i-1];
            bricks -= h;
            q.push({h, i});
            while (bricks < 0 && ladders > 0) {
                bricks += q.top().first;
                q.pop();
                --ladders;
            }
            printf("%d, %d, %d\n", i, bricks, ladders);
            if (bricks >= 0) {
                ++i;
            } else {
                break;
            }
        }
        return i - 1;
    }
};

