def sb(num):
	binary = bin(num)
	setBits = [ones for ones in binary[2:] if ones == '1']
	return len(setBits)

def doIt(x, y):
	if x == y:
		return 0
	if y == 0:
		return -1
	if y == 1:
		if x == 0:
			return 1
		return -1
	kachra = sb(y - 1) - sb(x) + 1
	if kachra > 0:
		return kachra
	else:
		return 2

