class Solution {
public:
    int numberOfArrays(std::vector<int>& differences, int lower, int upper) {
        long long prefix_sum = 0;
        long long min_prefix_sum = 0;
        long long max_prefix_sum = 0;

        for (int diff : differences) {
            prefix_sum += diff;
            min_prefix_sum = std::min(min_prefix_sum, prefix_sum);
            max_prefix_sum = std::max(max_prefix_sum, prefix_sum);
        }

        long long range = upper - lower + 1;
        long long required_range = max_prefix_sum - min_prefix_sum + 1;

        if (required_range > range) {
            return 0;
        }

        long long start_range = lower - min_prefix_sum;
        long long end_range = upper - max_prefix_sum;

        return std::max(0LL, end_range - start_range + 1);
    }
};

