def max_color_changes(s):
    H, W = len(s), len(s[0])
    if H == 0 or W == 0:
        return -1

    def is_valid_square(i, j):
        return 0 <= i < H and 0 <= j < W and s[i][j] == '.'

    def is_surrounded_by_white(i, j):
        return (
            is_valid_square(i - 1, j)
            and is_valid_square(i + 1, j)
            and is_valid_square(i, j - 1)
            and is_valid_square(i, j + 1)
        )

    def dfs(i, j, changes):
        if i == H - 1 and j == W - 1 and is_surrounded_by_white(i, j):
            return changes
        if not is_valid_square(i, j):
            return -1

        # Try moving up and change the color
        res_up = dfs(i - 1, j, changes + 1)
        if res_up != -1:
            return res_up

        # Try moving down and change the color
        res_down = dfs(i + 1, j, changes + 1)
        if res_down != -1:
            return res_down

        # Try moving left and change the color
        res_left = dfs(i, j - 1, changes + 1)
        if res_left != -1:
            return res_left

        # Try moving right and change the color
        res_right = dfs(i, j + 1, changes + 1)
        if res_right != -1:
            return res_right

        return -1

    # Start the DFS from (0, 0) with initial changes count as 0
    return dfs(0, 0, 0)

# Example usage:
print(max_color_changes(["..", "##"]))  # Output: 1
print(max_color_changes(["..", "##"]))  # Output: -1

