ll fast(ll a, ll b, ll mod) {
    a %= mod;
    if(b < 0)a = inverse(a, mod), b = -b;
    ll ans = 1;
    while(b) {
        if(b & 1)ans = ans * a % mod;
        a = a * a % mod;
        b /= 2;
    }
    return ans % mod;
}


class TextEditor {
public:
    list<char> l;
    list<char>::iterator it;

    TextEditor() {
        l.clear();
        it = l.end();
    }

    void de() {
        return;
        for(auto i: l) {
            cout << i;
        }
        cout << endl;
        auto itt = it;
        while(itt != l.end()) {
            cout << *itt;
            itt++;
        }
        cout << endl;
    }

    void addText(string text) {
        for(auto i: text) {
            l.insert(it, i);
        }
        de();
    }

    int deleteText(int k) {
        int a = 0;
        while(k--) {
            if(it == l.begin())break;
            a++;
            l.erase(prev(it));
        }
        de();

        return a;
    }

    void move(int k) {
        while(k--) {
            if(it == l.begin())break;
            it--;
        }
    }

    void mover(int k) {
        while(k--) {
            if(it == l.end())break;
            it++;
        }
    }

    string cursorLeft(int k) {
        this->move(k);
        string a;
        auto tp = it;
        k = 10;

        while(k--) {
            if(tp == l.begin())break;
            tp--;
            a.push_back(*tp);
        }
        reverse(all(a));
        de();

        return a;
    }

    string cursorRight(int k) {
        this->mover(k);
        string a;
        auto tp = it;
        k = 10;
        while(k--) {
            if(tp == l.begin())break;
            tp--;
            a.push_back(*tp);
        }
        reverse(all(a));
        de();

        return a;
    }
};

