public:
    VI diff(const string &s) {
	VI ret;
	REP (i, (int)s.size()-1) {
	    ret.push_back((int)s[i+1] - s[i]);
	}
	return ret;
    }
    string oddString(vector<string>& words) {
	VI D = diff(words[0]);
	VI guess;

	for (int i=1; i<(int)words.size(); i++) {
	    if (D != diff(words[i])) guess.push_back(i);
	}


	if (guess.size() == 1u) return words[guess[0]];
	return words[0];
    }
};

