def func():
    n, m = map(int, input().split())
    mat = [input()[:m] for _ in range(n)]
    if m == 1:
        for i in range(n):
            if 'B' in mat[i]:
                return i + 1, 1
    elif n == 1:
        for i in range(m):
            if 'B' in mat[i]:
                return 1, i + 1
    else :
        for i in range(n):
            for j in range(m):
                max_d = 0
                now = (i, j)
                while i + max_d< n and j + max_d< m:
                    if max_d % 2 == 0:
                        now = (i + max_d, j + max_d)
                    else:
                        now = (i + max_d, j + max_d - 1)
                    if not all(mat[now[0] - s][now[1] - s] == "B" for s in range(max_d + 1)):
                        break
                    max_d += 1
                if max_d % 2 == 0:
                    return (i + max_d) // 2 + 1, (j + max_d) // 2 + 1
    return 0

