def find_good_permutation(n):
    if n == 1:
        return -1
    if n == 2:
        return [2, 1]
    if n % 4 == 2 or n % 4 == 3:
        return -1
    perm = list(range(1, n + 1))
    if n % 4 == 0:
        # Swap pairs (1, 2), (3, 4), ..., (n-1, n)
        for i in range(0, n, 4):
            perm[i], perm[i + 1] = perm[i + 1], perm[i]
            perm[i + 2], perm[i + 3] = perm[i + 3], perm[i + 2]
    else:
        # Swap pairs (1, 2), (3, 4), ..., (n-4, n-3)
        for i in range(0, n - 4, 4):
            perm[i], perm[i + 1] = perm[i + 1], perm[i]
            perm[i + 2], perm[i + 3] = perm[i + 3], perm[i + 2]
        # Special handling for the last 4 elements
        perm[n - 4], perm[n - 1] = perm[n - 1], perm[n - 4]
        perm[n - 3], perm[n - 2] = perm[n - 2], perm[n - 3]
    return perm

