import math

def can_pair_numbers(l, r):
    count = (r - l + 1) // 2
    if count != (r - l + 1) % 2:
        return False

    numbers = list(range(l, r + 1))
    paired = [False] * len(numbers)

    def find_next_gcd(used, start, count, current_gcd):
        if count == 0:
            return True
        next_gcd = math.gcd(current_gcd, numbers[start])
        for i in range(start + 1, len(numbers)):
            if not used[i] and math.gcd(next_gcd, numbers[i]) == 1:
                used[start] = used[i] = True
                if find_next_gcd(used, i, count - 1, next_gcd):
                    return True
        return False

    def backtrack(used, count):
        if count == 0:
            return [[]]
        result = []
        for i in range(len(numbers)):
            if not used[i]:
                used[i] = True
                for pair in backtrack(used, count - 1):
                    result.append([numbers[i]] + pair)
                used[i] = False
        return result

    used = [False] * len(numbers)
    if find_next_gcd(used, 0, count, 0):
        return backtrack(used, count)
    else:
        return None

