class Solution:

	def maxLen(self, n, lst):
		curr_sum = 0
		max_l = 0
		d = {}
		for i in range(0, len(lst)):
			curr_sum = curr_sum + lst[i]
			if curr_sum == 0:
				max_l = i + 1
			elif curr_sum in d.keys():
				max_l = max(max_l, i - d[curr_sum])
			else:
				d[curr_sum] = i
		return max_l

