from collections import deque

def topological_sort(graph):
    n = len(graph)
    indegree = [0] * n
    for node in graph:
        for adj in graph[node]:
            indegree[adj] += 1
    q = deque([node for node in range(n) if indegree[node] == 0])
    res = []
    while q:
        node = q.popleft()
        res.append(node)
        for adj in graph[node]:
            indegree[adj] -= 1
            if indegree[adj] == 0:
                q.append(adj)
    return res

