def waiting_time(time_since_start, p, a, b, c):
    n = p
    r = n % b
    n = n // b
    l = max(n + 1, 0)
    flag = n - l * b
    x = flag * a    
    if flag == 0 and r < c:
        return x + (c - r)
    elif flag == 0 and r >= c:
        return l * a + (c - r)
    return (-1)

