def determine_winner(n, rounds):
    mishka_wins = 0
    chris_wins = 0
    for m, c in rounds:
        if m > c:
            mishka_wins += 1
        elif c > m:
            chris_wins += 1
    if mishka_wins > chris_wins:
        return "Mishka"
    elif chris_wins > mishka_wins:
        return "Chris"
    else:
        return "Friendship is magic!^^"

