class Solution:

	def longestConsecutive(self, root):
		if root == None:
			return -1
		ans = [0]

		def getMax(root, ans):
			if root == None:
				return 0
			if root.left == None and root.right == None:
				return 1
			left = getMax(root.left, ans)
			right = getMax(root.right, ans)
			leftcur = 1
			rightcur = 1
			if root.left and root.left.data - root.data == 1:
				leftcur += left
			if root.right and root.right.data - root.data == 1:
				rightcur += right
			ans[0] = max(ans[0], leftcur, rightcur)
			return max(leftcur, rightcur)
		getMax(root, ans)
		return ans[0] if ans[0] > 1 else -1

