def solve(n,m):
    lower = [1]*n; val=n
    while val<m:
        if val+9<=m:
            lower.append(9); val+=9
        else:
            lower.append(m-val); val=m
    upper = lower[:]; val=sum(upper)
    for i in range(len(upper)-1,-1,-1):
        d = min(upper[i],9-upper[i]%2)
        upper[i]-=d; val-=d
        if val<=n: break
    lower = "".join(map(str,lower)); upper = "".join(map(str,upper))
    return lower if len(lower)<=2230 else 0, upper if len(upper)<=2230 else 0

