public int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int MOD = 1000000007;

        int[] left = new int[n]; 
        int[] right = new int[n]; 
        int[] sum = new int[n]; 

        Stack<Integer> stack = new Stack<>(); 

        for (int i = 0; i < n; i++) {

           while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) {
                stack.pop();
            }

            left[i] = stack.isEmpty() ? -1 : stack.peek();

            stack.push(i); 
        }

        stack = new Stack<>();  // clear the stack for processing right subarrays

        for (int i = n - 1; i >= 0; i--) {

           while (!stack.isEmpty() && arr[stack.peek()] > arr[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();

            stack.push(i);
        }

        int result = 0;

        for (int i = 0; i < n; i++) {


            result = (result + arr[i] * (i - left[i]) * (right[i] - i)) % MOD;
        }

        return result;
    }
}

