def quick_sort(array):
	left = []
	equal = []
	right = []
	if len(array) > 1:
		pivot = array[0]
		for x in array:
			if x < pivot:
				left.append(x)
			elif x == pivot:
				equal.append(x)
			else:
				right.append(x)
		return quick_sort(left) + equal + quick_sort(right)
	else:
		return array

