#include <stdio.h>

int max_mex(int n, int m)
{
int f[n<<2];
f[0] = 1;
static int h[32] = {n<<9};
for (--m; m; --m)
if (f[n] & (1<<m))
h[n] = 0;
for (n << 9; n; n ^= h[n])
if (--m)
f[n] = 0; else break;
return n<<4;
}

int main(void)
{
static int q, p = 1,n=2;
do putchar((q = max_mex(++n, --q)-q)<<4); while(n < 15) ++p; n -= 15;
return 0;
}

