class Solution:

	def diagonal(self, root):
		l = []
		queue = [root]
		while len(queue) > 0:
			s = len(queue)
			while s > 0:
				node = queue.pop(0)
				while node != None:
					l.append(node.data)
					if node.left:
						queue.append(node.left)
					node = node.right
				s -= 1
		return l

