from typing import List
from itertools import islice
from operator import add
ORD_A = ord('a')

def ctoi(c):
	return ord(c) - ORD_A

def itoc(i):
	return chr(i + ORD_A)

class Solution:
	segments = None
	arr = None

	def build_segments(self):
		self._build_segments(0, 0, len(self.arr) - 1)

	def _build_segments(self, idx, left, right):
		segment = self.segments[idx]
		if left == right:
			segment[self.arr[left]] = 1
		if left >= right:
			return segment
		child_idx = 2 * idx
		mid = left + (right - left) // 2
		child_segment_left = self._build_segments(child_idx + 1, left, mid)
		child_segment_right = self._build_segments(child_idx + 2, mid + 1, right)
		for i in range(26):
			segment[i] = child_segment_left[i] + child_segment_right[i]
		return segment

	def update_segments(self, arr_i, new_c_ord):
		self._update_segments(0, 0, len(self.arr) - 1, arr_i, self.arr[arr_i], new_c_ord)
		self.arr[arr_i] = new_c_ord

	def _update_segments(self, idx, left, right, arr_i, old_c_ord, new_c_ord):
		if left <= arr_i <= right:
			segment = self.segments[idx]
			segment[old_c_ord] -= 1
			segment[new_c_ord] += 1
			if left < right:
				child_idx = 2 * idx
				mid = left + (right - left) // 2
				self._update_segments(child_idx + 1, left, mid, arr_i, old_c_ord, new_c_ord)
				self._update_segments(child_idx + 2, mid + 1, right, arr_i, old_c_ord, new_c_ord)

	def query_segments(self, start, end):
		acc = [0] * 26
		return self._query_segments(0, 0, len(self.arr) - 1, start, end, acc)

	def _query_segments(self, idx, left, right, start, end, acc):
		if end < left or right < start:
			return acc
		if start <= left and right <= end:
			segment = self.segments[idx]
			for i in range(26):
				acc[i] += segment[i]
			return acc
		if left < right:
			child_idx = 2 * idx
			mid = left + (right - left) // 2
			acc = self._query_segments(child_idx + 1, left, mid, start, end, acc)
			acc = self._query_segments(child_idx + 2, mid + 1, right, start, end, acc)
		return acc

	def easyTask(self, s_length, s, q_count, queries) -> List[int]:
		self.segments = [[0] * 26 for _ in range(4 * s_length)]
		self.arr = [ctoi(c) for c in s]
		self.build_segments()
		q_type2_results = []
		for q in queries:
			if q[0] == '1':
				(arr_i, new_c_ord) = (int(q[1]), ctoi(q[2]))
				self.update_segments(arr_i, new_c_ord)
			else:
				(q_type, start, end, k) = map(int, q)
				segment = self.query_segments(start, end)
				count = 0
				for i in reversed(range(26)):
					count += segment[i]
					if count >= k:
						q_type2_results.append(itoc(i))
						break
		return q_type2_results

