class Solution:

	def permutation(self, s):
		ans = []
		n = len(s)
		ds = [False for i in range(n)]
		s = sorted(s)

		def helper(cs, ds, s):
			if len(cs) == n:
				ans.append(cs)
				return
			for i in range(0, n):
				if not ds[i]:
					ds[i] = True
					helper(cs + s[i], ds, s)
					ds[i] = False
		for i in range(0, n):
			ds[i] = True
			helper(s[i], ds, s)
			ds[i] = False
		return ans

class Solution:

	def maxSumIS(self, nums, n):
		n = len(nums)
		dp = [0 for i in range(n)]
		dp[0] = nums[0]
		ans = nums[0]
		for i in range(1, n):
			mx = 0
			for j in range(i):
				x = nums[i] - nums[j]
				if x > 0:
					mx = max(mx, dp[j])
			dp[i] = nums[i] + mx
			ans = max(ans, dp[i])
		return ans

