from collections import deque

def func(lst, st, po, n, m):
	dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
	x = st[0] if st[0] != po else st[1]
	(curr, se, cnt) = (deque([x]), [[0] * m for _ in range(n)], 0)
	while len(curr):
		y = curr.popleft()
		for i in dirs:
			z = (y[0] + i[0], y[1] + i[1])
			if 0 <= z[0] < n and 0 <= z[1] < m and (lst[z[0]][z[1]] == '#') and (not se[z[0]][z[1]]):
				curr.append(z)
				se[z[0]][z[1]] = 1
				cnt += 1
	return cnt != len(st) - 1

