class Solution {
    public int maxNumOfMarkedIndices(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int i = 0, j = n / 2;
        int res = 0;
        while (i < n / 2 && j < n) {
            while (j < n && nums[j] < 2 * nums[i]) {
                j++;
            }
            // System.out.println(i + ", " + j + ", " + nums[i] + ", " + nums[j] + ", " + n);
            if (j < n) {
                res += 2;
                i++;
                j++;
            }
        }
        return res;
    }
}

