def min_distance(n,a):
    c = [0]*(n+1)
    for i in a:
        c[i] = 1
        c[n+i] = 1
    result = n
    for i in a:
        result = min(result, i)
    for i in range(1,n+1):
        tmp_cnt = i
        for j in str(c[i]):
            if tmp_cnt!=0:
                tmp_cnt -= 1
            else:
                tmp_cnt = n - i
        result = min(result, tmp_cnt + n - i)
    return result
