def mc_sort(a):
    N = len(a)
    index = {}
    for i in range(N):
        if a[i] not in index:
            index[a[i]] = i

    left, right = 0, N-1
    while left < right:
        if a[left] == left+1:
            left += 1
        elif a[right] == N-right:
            right -= 1
        else:
            a[index[a[left]]], a[left] = a[left], a[index[a[right]]]
            left, right = left+1, right-1
    return a == list(range(1, N+1))

