class SegmentTree {
    class Node {
        int l, r;
        int max;
        Node(int _l, int _r) {
            l = _l;
            r = _r;
        }
        int mid() {
            return (l + r) >> 1;
        }
    }
    Node[] tree;
    SegmentTree(int n, int[] a) {
        tree = new Node[(n + 5) << 2];
        build(1, 1, n, a);
    }
    void pushup(int p) {
        tree[p].max = Math.max(tree[p << 1].max, tree[p << 1 | 1].max);
    }
    void build(int p, int l, int r, int[] a) {
        tree[p] = new Node(l, r);
        if (l == r) {
            tree[p].max = a[l - 1];
            return;
        }
        int mid = (l + r) >> 1;
        build(p << 1, l, mid, a);
        build(p << 1 | 1, mid + 1, r, a);
        pushup(p);
    }
    int query(int p, int l, int r) {
        if (l <= tree[p].l && tree[p].r <= r) {
            return tree[p].max;
        }
        int max = Integer.MIN_VALUE;
        if (l <= tree[p].mid()) {
            max = Math.max(max, query(p << 1, l, r));
        }
        if (tree[p].mid() + 1 <= r) {
            max = Math.max(max, query(p << 1 | 1, l, r));
        }
        return max;
    }
}

class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        SegmentTree T = new SegmentTree(n, nums);
        int[] ans = new int[n];
        ans[n - 1] = -1;
        for (int i = 1; i < n; ++i) {
            int l = i + 1, r = n, res = -1;
            while (l <= r) {
                int mid = (l + r) >> 1;
                if (T.query(1, i + 1, mid) > nums[i - 1]) {
                    r = mid - 1;
                    res = mid;
                } else {
                    l = mid + 1;
                }
            }
            System.out.println(i + " " + res);
            if (res == -1) {
                ans[i - 1] = -1;
            } else {
                int L = res + 1;
                l = res + 1;
                r = n;
                res = -1;
                while (l <= r) {
                    int mid = (l + r) >> 1;
                    if (T.query(1, L, mid) > nums[i - 1]) {
                        r = mid - 1;
                        res = mid;
                    } else {
                        l = mid + 1;
                    }
                }
                if (res == -1) {
                    ans[i - 1] = -1;
                } else {
                    ans[i - 1] = nums[res - 1];
                }
            }
        }
        return ans;
    }
}

