def min_operations_to_form_triangle(n, lengths):
    lengths.sort()
    min_ops = float('inf')

    # Check all possible combinations of 3 sticks
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                side_length = lengths[k] - lengths[j] + lengths[i]

                # Check if it's possible to form an equilateral triangle
                if side_length > 0 and side_length % 3 == 0:
                    operations = 0

                    # Calculate operations needed for each stick
                    for stick in range(n):
                        if stick == i or stick == j or stick == k:
                            opposite = (stick + 2) % n
                            while lengths[opposite] > side_length:
                                lengths[opposite] -= 1
                                operations += 1
                            while lengths[opposite] < side_length:
                                lengths[opposite] += 1
                                operations += 1

                    # Update minimum operations
                    min_ops = min(min_ops, operations)

    return min_ops

