def vasya_said_hello(word):
    """
    Function to check if Vasya managed to say hello
    """
    target_word = 'hello'
    if len(word) != len(target_word):
        return 'NO'
    word_dict = {}
    target_word_dict = {}
    for ch in target_word:
        if ch not in target_word_dict:
            target_word_dict[ch] = 1
        else:
            target_word_dict[ch] += 1
    for ch in word:
        if ch in word_dict:
            word_dict[ch] += 1
        else:
            word_dict[ch] = 1
        if ch not in target_word_dict or word_dict[ch] > target_word_dict[ch]:
            return 'NO'
    return 'YES'

