class Solution {
public:
    int countSubmatrices(vector<vector<int>>& grid, int k) {
        int res = 0;
        int n = grid.size(), m = grid[0].size();
        long long  preSum[m];
        memset(preSum, 0, sizeof preSum);
        // i 表示列 j 表示行 从 (0,0) 开始往右下
        for(int j = 0; j < m; j++){
            preSum[j] = grid[0][j] + (j > 0 ? preSum[j - 1] : 0);
        }
        for(int i = 1; i < n; i++){
            for(int j = 0; j < m; j++){
                int cur = preSum[j];
                // 已经存在求和<=k的左边了，可能也最多是这个个数。但是可能是小于k的，所以这里要减1
                cur = cur + (j > 0 ? preSum[j - 1] : 0) - (i > 0? preSum[i - 1] : 0);
                if(cur <= k){
                    res++;
                }
            }
        }
        return res;
    }
};

