import sys

def is_overlucky(num):
    if num % 4 == 0 or num % 7 == 0:
        return True
    while num > 0:
        if num % 10 != 4 and num % 10 != 7:
            return False
        num //= 10
    return True

def solve(n):
    divs = 0
    for i in range(1, n + 1):
        if n % i == 0:
            if is_overlucky(i):
                divs += 1
    return divs

if __name__ == '__main__':
    t = int(input())
    for _ in range(t):
        n = int(input())
        print(solve(n))
