from typing import List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def constructTree(postorder: List[int]) -> TreeNode:
    def helper(postorder, start, end):
        if start > end:
            return None
        root = TreeNode(postorder[end])
        i = end - 1
        while i >= start and postorder[i] > root.val:
            i -= 1
        root.right = helper(postorder, i + 1, end - 1)
        root.left = helper(postorder, start, i)
        return root

    return helper(postorder, 0, len(postorder) - 1)

def inorderTraversal(root: TreeNode) -> List[int]:
    if not root:
        return []
    return inorderTraversal(root.left) + [root.val] + inorderTraversal(root.right)

# Example usage
postorder = [1, 7, 5, 50, 40, 10]
root = constructTree(postorder)
print(inorderTraversal(root))

def insert(root, k):
	if root == None:
		temp = Node(k)
		return temp
	if root.data > k:
		root.left = insert(root.left, k)
	elif root.data < k:
		root.right = insert(root.right, k)
	return root

def constructBst(arr, n):
	root = Node(arr[0])
	for i in range(1, n):
		insert(root, arr[i])
	return root

