public class Solution {
    private int res = Integer.MAX_VALUE;
    private int[] buckets;

    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        buckets = new int[n];
        // sort in reverse order
        Integer[] task_i = new Integer[n];
        for (int i = 0; i < n; ++i)
            task_i[i] = tasks[i];
        Arrays.sort(task_i, Collections.reverseOrder());

        /* copy sort task to tasks */
        for (int i = 0; i < n; ++i)
            tasks[i] = task_i[i];

        backtracking(tasks, sessionTime, 0, 0);
        return res;
    }

    private void backtracking(int[] tasks, int sessionTime, int start, int session) {
        // pruning
        if (session >= res)
            return;
        // end condition
        if (start == tasks.length) {
            res = session;
            return;
        }

        boolean found = false;
        for (int j = 0; j < session; ++j) {
            // if this bucket has enough space
            if (buckets[j] + tasks[start] <= sessionTime) {
                buckets[j] += tasks[start];
                backtracking(tasks, sessionTime, start + 1, session);
                buckets[j] -= tasks[start];
                found = true;
            }
            // if this is the last bucket, we need to open a new one
            if (buckets[j] == 0)
                break;
        }
        // if no bucket has enough space, open a new one
        if (!found) {
            buckets[session] += tasks[start];
            backtracking(tasks, sessionTime, start + 1, session + 1);
            buckets[session] -= tasks[start];
        }

    }
}

