def solve(n, k, box):
    if any(d > 8 for d in box):
        return -1
    total = sum(box)
    if total < k:
        return -1
    days = n * 8
    for i in range(n):
        days -= box[i]
        if i + 1 >= k:
            return i + 1
    return -1

