def solve(n, a):
    d = {}
    ans = []
    flag = False
    for i in range(n):
        if a[i] not in d:
            d[a[i]] = (i, i)
        else:
            d[a[i]] = (min(d[a[i]][0], i), max(d[a[i]][1], i))
    for i in range(n):
        if d[a[i]][1] - d[a[i]][0] >= 1:
            flag = True
            ans.append((d[a[i]][0]+1, d[a[i]][1]+1))
            d[a[i]] = (n+1, n+1)
    if not flag:
        return -1
    return len(ans), sorted(ans)
