public class Solution {
    Map<String, String> dp = new HashMap<>();

    public String encode(String s) {
        if (s == null) return s;

        return build(s);
    }


    String build(String s) {
        if (dp.containsKey(s)) return dp.get(s);
        int f = 0, t = s.length();
        String res = s;
        char[] cs = s.toCharArray();
        int len = s.length();
        if (len <= 4) return res;
        for (int w = 1; w <= len; w ++) {
            if (len % w != 0) continue;
            boolean ok = true;
            for (int i = f; i < f + w && ok; i ++) {
                if (i + w > t) break;
                for (int j = i + w; j < t; j += w) {
                    if (cs[j - w] != cs[j]) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) {
                StringBuilder sb = new StringBuilder();

                String inner = s.substring(0, w);
                String ires = inner;
                for (int i = 1; i < w; i ++) {
                    String s1 = build(inner.substring(0, i));
                    String s2 = build(inner.substring(i, w));
                    if (s1.length() + s2.length() < ires.length()) {
                        ires = s1 + s2;
                    }
                }

                if (len / w > 1) {
                    sb.append(len / w);
                    sb.append('[');
                    sb.append(ires);
                    sb.append(']');
                } else {
                    sb.append(ires);
                }

                String one = sb.toString();
                if (one.length() < res.length()) res = one;
            }
        }
        dp.put(s, res);
        return res;
    }
}

