from itertools import product

def get_days(n, p):
    # construction of adjacency list
    adjacency_list = dict(zip(range(1, n+1), p))
    # function to check colorability
    def is_colorable(graph, colors, vertex, color):
        for neighbour in graph[vertex]:
            if colors[neighbour] == color:
                return False
        return True
    for i in range(1, n+1):
        graph = [adjacency_list[x] for x in adjacency_list if x <= i]
        colors = [-1] * (n + 1)
        colors[i] = 0
        result = [0] * (n + 1)
        result[i] = 1
        for _ in range(1, len(graph)+1):
            for color in range(1, _):
                for path in product(range(1, _), repeat=_):
                    if all(colors[adjacency_list[x]]!=color for x in graph):
                        result = [color if x else -colors[adjacency_list[graph[x-1]]] for x in range(1, n+1)]
                        break
            colors = result
        if result[i]>0:
            return result

