class Solution {
public:
    int minSteps(int n) {
        int x = n;
        int res = 0;
        while(x > 1){
            for(int i = 2; i <= n; i++) {
                if(x%i == 0){
                    x = x/i;
                    res += i;
                    break;
                }
            }
        }
        return res;
    }
