class Solution:

	def splitList(self, head, head1, head2):
		if head.next.next == None:
			node1 = head
			node2 = head.next
			node1.next = node1
			node2.next = node2
		slow = head
		fast = head
		while fast.next != head and fast.next.next != head:
			slow = slow.next
			fast = fast.next.next
		head1 = head
		head2 = slow.next
		slow.next = head
		temp = head2
		while temp.next != head:
			temp = temp.next
		temp.next = head2
		return (head1, head2)

