def lc(string):
	ans = 1000000000
	real = {}
	fake = {}
	i = 0
	for x in string:
		if x not in fake:
			fake[x] = i
			real[x] = max(real.get(x, 0), i + 1)
		else:
			val = i - fake.get(x, 0)
			fake[x] = i
			real[x] = max(real.get(x, 0), val)
		i += 1
	for x in real:
		val = len(string) - fake.get(x, 0)
		fake[x] = i
		real[x] = max(real.get(x, 0), val)
	for x in real:
		ans = min(ans, real[x])
	else:
		return ans
