def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(num):
    return str(num) == str(num)[::-1]

def prime_count(n):
    count = 0
    for i in range(2, n + 1):
        if is_prime(i):
            count += 1
    return count

def palindrome_count(n):
    count = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            count += 1
    return count

def find_n_for_ratio(p, q):
    A = p / q
    for n in range(1, int(1e7) + 1):  # Adjust the upper limit as needed
        if prime_count(n) * q <= A * palindrome_count(n):
            return n
    return "Palindromic tree is better than splay tree"

