from collections import defaultdict

class Solution:

	def findSubArraySum(self, arr, N, k):
		c = 0
		d = defaultdict(int)
		cur_sum = 0
		for i in arr:
			cur_sum += i
			if cur_sum == k:
				c += 1
			z = cur_sum - k
			if z in d:
				c += d[z]
			d[cur_sum] += 1
		return c

