def count_subrectangles(n, m, k, a, b):
    c = [[a[i]*b[j] for j in range(m)] for i in range(n)]
    cnt = 0
    for x1 in range(1, n+1):
        for y1 in range(1, m+1):
            for x2 in range(x1, n+1):
                for y2 in range(y1, m+1):
                    if (x2-x1+1)*(y2-y1+1) == k and all(c[i][j] for i in range(x1-1, x2) for j in range(y1-1, y2)):
                        cnt += 1
    return cnt

