def operations(a, b):
    diff = b - a
    if diff < 0 or diff & (diff - 1) != 0:
        return -1
    count = 0
    while a != b:
        if a % 2 == 1 or b % 2 == 1:
            a = min(a, b)
            b ^= a
            a ^= a
        else:
            shift = 0
            while a % 2 == 0 and b % 2 == 0 and a != b and shift <= 120:
                a /= 2
                b /= 2
                shift += 1
            if a == b or shift > 120:
               return -1
            a, b = min(a * 2, b * 2), max(a * 2, b * 2)
        count += 1
    return count

