public:
    int returnIdx(vector<int>& nums) {
        int n = nums.size(), ans = n, rcnt = 0, lcnt = 0;
        for (int i = n - 1; i >= 0; --i) {
            if (nums[i] > 0 && lcnt > 0 || nums[i] < 0 && rcnt > 0) { 
                ans = i; // [-2,3], [2,3,0]
            }
            if (nums[i] < 0) lcnt += 1;
            else rcnt += 1;
        }
        return ans;
    }

    bool go(vector<int>& nums, int idx) {
        while (idx < nums.size() && nums[idx] != 0) {
            if (nums[idx] < 0) idx -= nums[idx];
            else idx += nums[idx];
        }
        return idx >= 0;
    }

    int returnBoundaryProblem(vector<int>& nums) {
        int L = returnIdx(nums), R = L - 1, ans = 0;
        for (int i = L; i <= R; i += 2) {
            if (!go(nums, R) || !go(nums, L)) break;
            else {
                ans += 1;
            }
        }
        return ans;
    }
};

