class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        base = 1000000007
        for i in range(n-1, -1, -1):
            mask = 1 << i
            if a < b: a, b = b, a
            if ((mask & a) == (mask & b)): 
                a |= mask
                b |= mask
            else:
                a &= ~mask
                b |= mask
        return a % base * b % base;

