class Solution:
    def removeValuesFromList(self, the_list, val):
        return [value for value in the_list if value != val]
    def maxLen(self, tree):
        ##生成一个mysum的数组
        count = 0
        tree = self.removeValuesFromList(tree,0)
        mysum  = [0]
        for value in iter(tree):
            count +=value
            mysum.append(count)
        mymap = defaultdict(list)
        for index,value in enumerate(iter(mysum)):
            mymap[value].append(index)
        ##记录下每一个basket的长度
        res = []
        for key in iter(mymap):
            basket = mymap[key]
            for i in range(len(basket)-1):
                res.append(basket[i+1] -basket[i] + 1)


        return mysum,res

    def maxLenNo0No2(self, tree):

        mysum, basket = self.maxLen(tree)
        if(len(basket)<=2):
            return max(mysum)


        mums = []
        n = len(mysum)
        for i in range(n-1,-1,-1):
            k = n-i-1
            ##计算
            mums.append((mysum[-1]-(mysum[i+1]))+(mysum[k]-mysum[i])+mysum[i])


        return max(mums)

