class Solution:

	def toposort(self, s, node, graph, vis):
		vis[node] = True
		for nbr in graph[node]:
			if not vis[nbr[0]]:
				self.toposort(s, nbr[0], graph, vis)
		s.append(node)

	def maximumDistance(self, v: int, e: int, src: int, edges: List[List[int]]) -> List[int]:
		s = []
		graph = defaultdict(list)
		vis = [False] * v
		for i in edges:
			graph[i[0]].append([i[1], i[2]])
		for i in range(v):
			if not vis[i]:
				self.toposort(s, i, graph, vis)
		dist = [-1000000000.0] * v
		dist[src] = 0
		while s:
			node = s.pop()
			if dist[node] != -1000000000.0:
				for nbr in graph[node]:
					u = nbr[0]
					w = nbr[1]
					if dist[u] < dist[node] + w:
						dist[u] = dist[node] + w
		for i in range(len(dist)):
			if dist[i] == -1000000000.0:
				dist[i] = 'INF'
		return dist

