import sys

def find_subsegment(n, permutation):
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            subsegment = permutation[i:i + length]
            min_val = min(subsegment)
            max_val = max(subsegment)
            if subsegment[0]!= min_val and subsegment[0]!= max_val and subsegment[-1]!= min_val and subsegment[-1]!= max_val:
                return i + 1, i + length
    return -1

def main():
    input_lines = sys.stdin.readlines()
    input_index = 0
    def next_int():
        nonlocal input_index
        res = int(input_lines[input_index].strip())
        input_index += 1
        return res
    def next_ints():
        nonlocal input_index
        res = list(map(int, input_lines[input_index].strip().split()))
        input_index += 1
        return res

    t = next_int()
    for _ in range(t):
        n = next_int()
        permutation = next_ints()
        result = find_subsegment(n, permutation)
        if result == -1:
            print(-1)
        else:
            print(*result)

