class Solution:

	def skipMdeleteN(self, head, M, N):
		cn = 1
		curr = head
		while curr:
			if cn == M:
				k = 0
				curr1 = curr
				while curr1 and k <= N:
					curr1 = curr1.next
					k += 1
				cn = 0
				curr.next = curr1
			curr = curr.next
			cn += 1
		return head

import math
import sys

class Solution:

	def smallestDivisor(self, nums, K):
		s = 1
		e = max(nums)
		ans = sys.maxsize
		while s <= e:
			count = 0
			m = (s + e) // 2
			for i in nums:
				count += math.ceil(i / m)
			if count == K:
				ans = min(ans, m)
				e = m - 1
			elif count < K:
				ans = min(ans, m)
				e = m - 1
			else:
				s = m + 1
		return ans

