import collections
class FreqStack:

    def __init__(self):
        self.counter = collections.Counter()
        self.group = collections.defaultdict(list)
        self.maxfreq = 0

    def push(self, x: int) -> None:
        self.counter[x] += 1
        if self.counter[x] > self.maxfreq:
            self.maxfreq = self.counter[x]
        self.group[self.counter[x]].append(x)

    def pop(self) -> int:
        x = self.group[self.maxfreq].pop()
        self.counter[x] -= 1
        if not self.group[self.maxfreq]:
            self.maxfreq -= 1
        return x

