class Pyramid:
    def __init__(self):
        self.completed_pyramids = 0

    def construct_pyramid(self, n):
        height = 1
        while n >= height * (height + 1) // 2:
            n -= height * (height + 1) // 2
            height += 1
        self.completed_pyramids += height - 1
        return n >= height

def main():
    T = int(input())
    for _ in range(T):
        n = int(input())
        p = Pyramid() 
        while p.construct_pyramid(n):
            pass
        print(p.completed_pyramids)

