from typing import List

class Solution:

	def arrayOperations(self, n: int, arr: List[int]) -> int:
		start = 0
		end = 0
		cnt = 0
		zero = 0
		for e in arr:
			if e == 0:
				start += 1
				zero = 1
			else:
				break
		for e in arr[::-1]:
			if e == 0:
				end += 1
				zero = 1
			else:
				break
		i = start
		while i < len(arr) - end:
			flag = 1
			while arr[i] == 0:
				if flag:
					cnt += 1
					flag = 0
				i += 1
			else:
				i += 1
		if cnt:
			return cnt + 1
		elif len(arr) - end <= start:
			return 0
		elif zero:
			return 1
		return -1

