def max_team_height(n, h1, h2):
    dp = [[0, 0] for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = max(dp[i-1][1] + h1[i-1], dp[i-1][0])
        dp[i][1] = max(dp[i-1][0] + h2[i-1], dp[i-1][1])

    return max(dp[n][0], dp[n][1])

