def find_regular_subsequence(n, k, s):
    stack = []
    pairs = []
    result = []

    # Identify pairs of matching brackets
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                pairs.append((stack.pop(), i))

    # Sort pairs by their starting index
    pairs.sort(key=lambda x: x[0])

    # Select the first k/2 pairs to form the subsequence
    for i in range(k // 2):
        result.append(s[pairs[i][0]])
        result.append(s[pairs[i][1]])

    return ''.join(result)

