def countTriplets(n, arr, L, R):
    arr.sort()
    count = 0
    for i in range(n):
        left = 0
        right = n-1
        while left < right:
            if left == i:
                left += 1
            elif right == i:
                right -= 1
            else:
                sum = arr[left] + arr[right]
                if sum >= L and sum <= R:
                    count += 1
                    left += 1
                    right -= 1
                elif sum < L:
                    left += 1
                else:
                    right -= 1
    return count

