def checkSpendings(n):
    if n <= 2020:
        return False
    if n % 2020 == 0 or n % 2021 == 0:
        return True
    for i in range(2020, int(n ** 0.5) + 1, 2020):
        if (n - i) % 2021 == 0:
            return True
    return False

