def calc_inverse_dict(inventory):
    dic = {}
    for key in inventory:
        if inventory[key] not in dic:
            dic[inventory[key]] = [key]
        else:
            dic[inventory[key]].append(key)
    return dic

def find_max_group(dic, x):
    max_group = []
    max_count = -1
    for key in sorted(dic.keys(), reverse=True):      
        if dic[key] and all(i>=x for i in dic[key]):
            if len(dic[key]) > max_count:
                max_group = [dic[key]]
                max_count = len(dic[key])
            elif len(dic[key]) == max_count:
                max_group.append(dic[key])
    return max_group

def solve(inventory, groups):
    inv_dic = calc_inverse_dict(inventory)
    result = []
    for x in sorted(groups, reverse=True):
        max_group = find_max_group(inv_dic, x)
        remaining_group = [i for i in inv_dic if i not in map(tuple, max_group)]
        result.append(max_group)
        for group in max_group:
            for item in group:
                inv_dic[item].remove(item)
        inv_dic = {i: inv_dic[i] for i in inv_dic if inv_dic[i]}
    return result

