def circumference(points: tuple) -> float:
    minCircumference = math.inf

    for p1 in range(len(points)):
        for p2 in range(p1 + 1, len(points)):
            x1, y1 = points[p1]
            x2, y2 = points[p2]
            distance = math.hypot(x2 - x1, y2 - y1)
            circumference = distance / 2.0
            perpendicularY = (y1 + y2) / 2.0
            pXgcd = math.gcd(abs(x2 - x1), abs(y2 - y1))
            if pXgcd:
                for offset in range(-pXgcd, pXgcd + 1):
                    midY = perpendicularY + offset * (y2 - y1) / (x2 - x1)

                    minRadius = math.inf
                    contains = True

                    for (x, y) in points:
                       if not isContained(midX, midY, x, y, radius):
                            contains = False

                   if contains:
                        minRadius = min(minRadius, radius)

                        if minRadius <= circumference and minRadius < minCircumference:
                            minCircumference = minRadius

    return minCircumference


def isContained(x0, y0, x, y, r):
    hypot = pow(x - x0, 2) + pow(y - y0, 2)
    return hypot <= r * r

