class Solution {
    public int getMaximumGenerated(int n) {
        // Create an array to store the generated nums values
        int[] nums = new int[n + 1];

        // Initialize base cases
        nums[0] = 0;
        nums[1] = 1;

        // Generate the nums values using recursion or iteration based on the given rules
        for (int i = 2; i <= n; i++) {
            // If i is even, set nums[i] = nums[i / 2]
            if (i % 2 == 0)
                nums[i] = nums[i / 2];
            // If i is odd, set nums[i] = nums[i / 2] + nums[(i / 2) + 1]
            else
                nums[i] = nums[i / 2] + nums[(i / 2) + 1];
        }

        // Find the maximum integer in the nums array
        int max = nums[0];
        for (int i = 1; i <= n; i++)
            if (nums[i] > max)
                max = nums[i];

        // Return the maximum integer
        return max;
    }
}

class Solution:

	def maxInstance(self, s: str) -> int:
		li = []
		if 'b' in s and 'a' in s and ('l' in s) and ('o' in s) and ('n' in s):
			li.append(s.count('b') // 1)
			li.append(s.count('a') // 1)
			li.append(s.count('l') // 2)
			li.append(s.count('o') // 2)
			li.append(s.count('n') // 1)
			return min(li)
		else:
			return 0

