typedef pair<int, int> pii;

class Solution {
public:
  vector<int> smallestRange(vector<vector<int>>& nums) {
    n = 0;
    for (auto &a: nums) {
      a.erase(unique(a.begin(), a.end()), a.end());
      cnt[n++] = a.size();
    }
    memset(pt, 0, sizeof(pt));
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    priority_queue<pii, vector<pii>, greater<pii>> dq;

    int a1 = nums[0][0], a2 = nums[0][0];

    for (int i = 0; i < n; ++i) {
      dq.push(make_pair(nums[i][0], i));
      a1 = min(a1 , nums[i][0]);
      a2 = max(a2 , nums[i][0]);
    }
    int a3 = a1, a4 = a2;

//    cout <<a1 << a2 << a3 << a4 << endl;

    for (int i = 0; i < n; ++i) {
      if (cnt[i] > 1) {
        pq.push(make_pair(nums[i][1], i));
      }
    }

    while (!pq.empty()) {
      int val = pq.top().first;
      int id = pq.top().second;
      dq.push(pq.top());
      pq.pop();
      a4 = max(a4, val);

      ++pt[id];
      if (pt[id] + 1 < cnt[id]) {
        pq.push(make_pair(nums[id][pt[id] + 1], id));
      }

      while (!dq.empty()) {
        int i = dq.top().second;
        if (dq.top().first == nums[i][pt[i]]) break;
        dq.pop();
      }

      a3 = dq.top().first;
      if (a4 - a3 < a2 - a1) {
        a1 = a3;
        a2 = a4;
      }

//      cout <<a1 << a2 << " : " << a3 << a4 << endl;
    }

    return vector<int>{a1, a2};
  }

private:
  int n;
  int pt[3510];
  int cnt[3510];
};

