def minCoins(self, V, M, coins):


        dp = [1000001] * V

        for i in range(M):

            dp[0] = min(
                dp[0], dp[i] + 1
            )
            for j in range(1, coins[i]+1):

                temp = dp[ j-1 ] if dp[ j -1 ] < V+1 else 10 ** 5  
                temp = min( temp, dp[V-j] + 1)  
                dp[V] = min(dp[V], temp)
        return V if dp[V] != 1000001 else -1
