			ans = 1
		else:
			ans = l[x - 1] % 2
	elif l[x] == 0:
		if l[x + 1] == 0:
			ans == l[x - 1] % 2
		else:
			ans = 1
	else:
		ans = l[x - 1] % 2
	return ('Even', 'Odd')[ans]
