def combine(n1, n2, arr):
    # fill in the array
    # if n1 == 0 or n2 == 0 then
    #   arr is the next combination
    if n1 + n2 == 0:
        if len(arr) >= 2:
            k1 = k2 = 0
            for i in range(len(arr)-1):
                if arr[i] == 1:
                    k1 += 1
                else: k2 += 1
                if k1 > k:
                    return 0
                if k2 > k:
                    return 0
        mem.append(n1, n2, arr)
        return 1

    if mem.at(n1, n2, arr):
        return mem.count(n1,n2, arr)

    if n1 > 0:
        cx = combine(n1-1, n2, arr+[1])
        if cx > 0:
            mem.append(n1, n2, arr+[1])
            return cx

    if n2 > 0:
        cx = combine(n1, n2-1, arr+[2])
        if cx > 0:
            mem.append(n1, n2, arr+[2])
            return cx
    mem.append(n1, n2, arr)
    return 0

