int main() {
    int n, q;
    scanf("%d %d", &n, &q);

    Process processes[100000];
    for (int i = 0; i < n; i++) {
        scanf("%s %d", processes[i].name, &processes[i].time);
    }

    int currentTime = 0;
    int index = 0;

    while (index < n) {
        if (processes[index].time > 0) {
            if (processes[index].time > q) {
                currentTime += q;
                processes[index].time -= q;
            } else {
                currentTime += processes[index].time;
                printf("%s %d\n", processes[index].name, currentTime);
                processes[index].time = 0;
            }
        }
        index = (index + 1) % n;
    }

    return 0;
}

