from math import sqrt, floor

def sieve(n):
	primes = [True] * (n + 1)
	primes[0] = False
	primes[1] = False
	for i in range(2, n + 1):
		if i * i > n:
			break
		if primes[i] == False:
			continue
		for j in range(2 * i, n + 1, i):
			primes[j] = False
	return primes

