def solve_good_array(arr):
    n = len(arr)
    if n == 1:
        return 0

    # Find the first position where the array is not non-decreasing
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            break
    else:
        return 0  # The array is already non-decreasing

    # Check from the end to find the first position where the array is not non-increasing
    for j in range(n - 1, 0, -1):
        if arr[j] < arr[j - 1]:
            break

    # If the array is already non-increasing, no need to erase any prefix
    if i >= j:
        return 0

    # Check if the subarray from i to j can be made good by erasing the prefix
    for k in range(i, j):
        if arr[k] > arr[k + 1]:
            return k + 1

    return i + 1

