class Solution {
public:
    int minSwaps(vector<int>& nums) {
        int tot = accumulate(nums.begin(), nums.end(), (int)0);
        int cnt = 0;
        int idx = 0;
        int r = 0;
        int sr = 0;
        int res = tot;
        int n = nums.size();
        while (idx < n) {
            while (r < idx + tot) {
                cnt += nums[r % n];
                r ++;
            }
            res = min(res, (tot - cnt));
            cnt -= nums[idx];
            idx ++;
        }
        return res;
    }
};

