std::string find_nice_substring(const std::string& s) {
    std::string long_sub;
    bool found = false;
    int pos = 0;
    //std::end(s) -> sirreverse iterator, onde vogliamo unire a conseguire finale e iniziale ecc sessione.. per max 7 d 8 d'acca ma non visto
    auto it = std::end(s) - 1;
    while (found == false) {
        int count = 0;
        found = true;
        int after_it_count = 0;

        for (auto it2 = std::next(it); it2 >= std::begin(s); --it2) {
            if (std::toupper(*it) == *it2) {
                ++count;
            }
            else if (std::tolower(*it) == *it2) {
                ++after_it_count;
            }
            else {
                found = false;
                break;
            }
        }
        //da escritura dati parte fine non ho break per controllare se pote raggiungere rimane..
        if (after_it_count == 0 && found == true) {
            bool it_found = false;
            for (auto other = std::next(it); other < std::begin(s) && found == true ; other++) {
                if (std::toupper(*other) == *it) {
                    count += 1;
                    it_found = true;
                }
                else if (std::tolower(*other) == *it) {
                    found = false;
                    break;
                }
            }
            if (it_found == true) {
                count += 1;
            }
        }
        if (count >= 1) {
            long_sub = std::string(std::next(it), std::end(s));
            long_sub = std::string(long_sub.size() - count, '&') + long_sub;
            //std::cout << std::string(std::next(it), std::end(s)) << '\n';
        }
        it -= 1;
    }
    return long_sub;
}

