def min_power_sum(n):
    dp= [0]+ [-1] * n
    for i in range(1,n+1):
        j = 1
        while 3**j <= i and dp[i] == -1:
            dp[i] = max(dp[i], dp[i-3**j] +1 if i-3**j >=0 else -1)
            j += 1
    return dp[n] if dp[n] > 0 else min([i for i in dp if i >=0])

