int modpow(int a, int b) {
    int res = 1;
    for (; b; b >>= 1) {
        if (b & 1) res = 1LL * res * a % MOD;
        a = 1LL * a * a % MOD;
    }
    return res;
}

void precompute() {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = 1LL * fact[i - 1] * i % MOD;
    }
    ifact[n] = modpow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i) {
        ifact[i] = 1LL * ifact[i + 1] * (i + 1) % MOD;
    }
}

int comb(int n, int k) {
    if (k > n) return 0;
    return 1LL * fact[n] * ifact[k] % MOD * ifact[n - k] % MOD;
}

