import collections

def amaze(arr):
	lastSeen = collections.defaultdict(int)
	maxDists = collections.defaultdict(int)
	for i in range(len(arr)):
		if arr[i] in lastSeen:
			maxDists[arr[i]] = max(maxDists[arr[i]], i - lastSeen[arr[i]])
		else:
			maxDists[arr[i]] = i + 1
		lastSeen[arr[i]] = i
	for key in lastSeen:
		maxDists[key] = max(maxDists[key], len(arr) - lastSeen[key])
	if len(maxDists) == 1:
		return [arr[0]] * len(arr)
	ans = [float('inf')] * len(arr)
	for key in maxDists:
		ans[maxDists[key] - 1] = min(ans[maxDists[key] - 1], key)
	for i in range(1, len(ans)):
		ans[i] = min(ans[i - 1], ans[i])
	for i in range(len(ans)):
		if ans[i] == float('inf'):
			ans[i] = -1
	return ans
