class Solution:

	def reverse(self, s):
		s = list(s)
		end = len(s) - 1
		start = 0
		while start < end:
			if s[start].isalnum() and s[end].isalnum():
				(s[start], s[end]) = (s[end], s[start])
				start += 1
				end -= 1
			elif not s[start].isalnum():
				start += 1
			else:
				end -= 1
		return ''.join(s)

