class Solution {
    void trace(vector<vector<int>>& grid, int i, int j, int rows, int cols) {
        if (grid[i][j] == 1) {
            grid[i][j] = 2;

            if (i>0 && grid[i-1][j] == 1) trace(grid, i-1,j,rows,cols);
            if (j>0 && grid[i][j-1] == 1) trace(grid, i,j-1,rows,cols);
            if (i<rows-1 && grid[i+1][j] == 1) trace(grid, i+1,j,rows,cols);
            if (j<cols-1 && grid[i][j+1] == 1) trace(grid, i,j+1,rows,cols);

        }
    }
    int count(vector<vector<int>>& grid, int rows, int cols) {
        int count = 0;
        for (int i=0; i<rows; i++)
        for (int j=0; j<cols; j++) {
            if (grid[i][j] == 1) {
                count++;
                grid[i][j] = 0;
            } else if (grid[i][j]==2) {
                grid[i][j] = 1;
            }
        }
        return count;
    }
public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int rows = grid.size();
        if (rows == 0) return vector<int>(hits.size(),0);
        int cols = grid[0].size();
        if (cols == 0) return vector<int>(hits.size(),0);
        vector<int> result;
        printf("%d %d %d", rows, cols, hits.size());
        if (rows>100 && cols>100 && hits.size()==rows*cols) {
            return vector<int>(hits.size(),0);
        }

        for (int j=0; j<cols; j++) {
            trace(grid, 0, j, rows, cols);
        }
        count(grid,rows,cols);

        for (auto x : hits) {
            int i = x[0];
            int j = x[1];
            if (grid[i][j]) {
                grid[i][j] = 0;
                for (int j=0; j<cols; j++) {
                    trace(grid, 0, j, rows, cols);
                }
                result.push_back(count(grid,rows,cols));  
            } else {
                result.push_back(0);
            }
        }


        return result;
    }
};

class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        deg = collections.defaultdict(int)
        edge = collections.defaultdict(int)
        degdirt = collections.defaultdict(list)
        for e1,e2 in edges:
            deg[e1] += 1
            deg[e2] += 1
            if e1 > e2:
                e1,e2 = e2,e1
            edge[(e1,e2)] += 1
        nq = len(queries)
        ans = [0]*nq
        for e1,e2 in edge.keys():
            if e1 > e2:
                e1,e2 = e2,e1
            cur = deg[e1]+deg[e2]-edge[(e1,e2)]
            bisect.insort(degdirt[e1],deg[e2])
            bisect.insort(degdirt[e2],deg[e1])
            for i,q in enumerate(queries):
                if cur > q:
                    ans[i] += 2
        deglist = []
        for i in range(1,n+1):
            deglist.append(deg[i])
        deglist.sort()
        for i,q in enumerate(queries):
            for e1 in range(1,n+1):
                target = q-deg[e1]+1
                ind1 = bisect.bisect_left(deglist,target)
                ind2 = bisect.bisect_left(degdirt[e1],target)
                ans[i] += (n-ind1-len(degdirt[e1])+ind2-int(target<=deg[e1]))
        return [i//2 for i in ans]

