            dp[j] = max(dp[j], dp[j-vol]+val);
        }
    }

    int maxNumberOfApples(vector<int>& arr) {
        memset(dp, 0, sizeof(dp));
        for(int i = 0; i < arr.size(); i++){
            solve(1, arr[i]);
        }
        return dp[5000];
    }
};

public int twoSumLessThanK(int[] A, int K) {
int N = A.length;

Arrays.sort(A);

// Largest two elements, less than k
int[] L1 = new int[2];
for (int i = 1; i < N; ++i) {
for (int j = 0; j < 2; ++j) {
if (L1[j] < A[i]) break;
L1[j] = A[i];
}
}

int[] L2 = new int[2];
for (int j = 0; j < 2; ++j) {
L2[j] = A[N - 1] - L1[j];
}

int res = Math.min(L1[0] + L1[1], L2[0] + L2[1]);

// Contiguous sub-array less than k
for (int i = 1; i < N; ++i) {
int[] R1 = new int[2];
for (int j = 0; j < 2; ++j) {
R1[j] = A[i - 1] + L1[j];
}

int[] R2 = new int[2];
for (int j = 0; j < 2; ++j) {
R2[j] = A[i - 1] + L2[j];
}

for (int j = 0, v = 0; j < 2; ++j, ++v) {
while (v >= 0 && R1[j] + A[v] > K) {
v--;
}
if (v >= 0) {
res = Math.min(res, L1[j] + A[v]);
}
}

for (int j = 0, v = N - 1; j < 2; ++j, --v) {
while (v < N && R2[j] + A[v] > K) {
v++;
}
if (v < N) {
res = Math.min(res, L2[j] + A[v]);
}
}

}

return res >=

