print(check_duck("02364"))    # Output: False

class Solution {
public:
    int numSpecial(vector<vector<int>>& mat) {
        int c = 0;
        vector<int> cc(mat.size()), dd(mat[0].size());
        for (int i = 0; i < mat.size(); i++) {
            for (int j = 0; j < mat[0].size(); j++) {
                if (mat[i][j] == 1) {
                    cc[i]++;
                    dd[j]++;
                }
            }
        }
        for (int i = 0; i < mat.size(); i++) {
            for (int j = 0; j < mat[0].size(); j++) {
                if (mat[i][j] == 1 && cc[i] == 1 && dd[j] == 1) {
                    c++;
                }
            }
        }
        return c;
    }
};

