def has_love_triangle(n, preferences):
    """
    Checks if there is a love triangle in the given preferences.

    Args:
        n (int): The number of planes.
        preferences (list): A list of integers where the i-th plane likes the preferences[i]-th plane.

    Returns:
        bool: True if there is a love triangle, False otherwise.
    """
    for i in range(n):
        for j in range(n):
            if i!= j and preferences[i] - 1 == j and preferences[preferences[i] - 1] - 1 == i:
                return True
            if preferences[j] - 1 == i and preferences[preferences[j] - 1] - 1 == j and preferences[preferences[preferences[j] - 1] - 1] - 1 == preferences[j] - 1:
                return True

    # Also check for triangles where i, j, k are distinct
    for i in range(n):
        for j in range(n):
            if i!= j:
                k = preferences[j] - 1
                if i!= k and preferences[i] - 1 == j and preferences[k] - 1 == i:
                    return True

    return False


def main():
    n = int(input())
    preferences = list(map(int, input().split()))

    if has_love_triangle(n, preferences):
        print("YES")
    else:
        print("NO")


