def f(n):
    if n % 2 == 0:
        # For even n, the sum of first n natural numbers is n * (n + 1) / 2
        # And the alternating sum of first n natural numbers is n * (n + 1) / 2 - (n + 1) = - (n + 1)
        return - (n + 1)
    else:
        # For odd n, the sum of first n natural numbers is n * (n + 1) / 2
        # And the alternating sum of first n natural numbers is n * (n + 1) / 2 + (n + 1) = (n + 1)
        return (n + 1)

