class Node:
    def __init__(self):
        self.children = []
        self.parent = None
        self.depth = None

    def __str__(self):
        if len(self.children) == 0:
            node_type = 'leaf'
        elif self.parent is None:
            node_type = 'root'
        else:
            node_type = 'internal node'
        parent_id = self.parent.id if self.parent else -1
        children_ids = [child.id for child in self.children]
        return f'node {self.id}: parent = {parent_id}, depth = {self.depth}, {node_type}, {children_ids}'

class Tree:
    def __init__(self, n):
        self.nodes = [Node() for _ in range(n)]

    def build_tree(self, edges):
        for node_id, children_ids in edges:
            for child_id in children_ids:
                self.nodes[child_id].parent = self.nodes[node_id]
                self.nodes[node_id].children.append(self.nodes[child_id])

    def calculate_depth(self, node, depth):
        node.depth = depth
        for child in node.children:
            self.calculate_depth(child, depth + 1)

    def __str__(self):
        result = []
        for node in sorted(self.nodes, key=lambda x: x.id):
            result.append(str(node))
        return '\n'.join(result)

