class Solution:
    def relativeSortArray(self, arr1: List[int], arr2: List[int]) -> List[int]:
        cnt = collections.Counter(arr1)
        set_arr2 = set(arr2)
        ans = []

        for x in arr2:
            ans += [x] * cnt[x]

        ans += sorted(x for x in arr1 if x not in set_arr2)
        return ans

