class Solution:
    def solve(self, a, m):
        energy = m
        ans = 0
        sit = 0
        for i in range(len(a)):
            if energy > 0 and sit == 0:
                if a[i] > energy:
                    while a[i] > energy:
                        ans += 1
                        energy += 1
                        sit += 1
                energy -= a[i]
            elif energy > 0 and sit > 0:
                ans += 1
                sit -= 1
                energy -= a[i]
            else:
                energy = m + a[i]
                sits += 1
        if energy > 0 and sit > 0:
            return ans + sit
        else:
            return ans



