public int countSubarrays(final int[] nums, final int k) {
        //int result = 0;
        //int n = nums.length;
        //Map<Integer, Integer> map = new HashMap<>();
        //    for(int i = 0; i <= n; i++){
        //        for(int j = i; j < n; j++){
        //            int med = findMedian(nums, i, j);
        //            if(med == k){
        //                result++;
        //            }
        //        }
        //    }
        //return result;
        Stack<Integer> s = new Stack<>();
        //Store the indices where we observe k in the stack and keep moving right and adjusting the left indices to get substrings with k as median.
        //Then calc the length of substring, update result and query about next substring to classify.
        //Main point is -- k can be median if right border is larger than left border.
        int i = 0, result = 0;
        for (int j = 0; j < nums.length; ++j) {
            while (true) {
                if (!s.isEmpty() && nums[s.peek()] < k)
                    s.pop();
                else
                    break;
            }
            //Adjust i pointer with guarantee of K.
            while (true) {
                if (!s.isEmpty() && nums[s.peek()] >= k) break;
                //If we ever meet k, while loop ends and set i to following position.
                i = s.isEmpty() ? j : Math.min(i, s.peek());
                // Hereafter, positions are lower than i, we may found K.
                s.push(i);
                break;
            }

            if (s.peek() > j) break;// It is impossible to find K till the end from position j.
            //We need to count from next valid left border(K is at j), and calculate the window size.
            result += (j - i + 1)>>1;//We don't need to consider (1,j).
        }
        return result;
    }
    private int findMedian(final int[] nums, final int i, final int j) {
        int[] arr = new int[j - i + 1];
        for (int k = i; k <= j; k++)
            arr[k - i] = nums[k];
        Arrays.sort(arr);
        return arr[(j - i + 1) >> 1];
    }
}

