static int minOps(int a, int b) {
    int count = 0;
    boolean v = b > a;
    do {
        int temp = a | b;
        a = a > temp ? temp + 1 : a;
        b = b > temp ? temp + 1 : b;
        count++;
    } while (v ? b > a : a > b);
    return count;
} 

