def min_ops(a: int, b: int) -> int:
    if a < b:
        a, b = b, a
    if a == b:
        return 0
    if b == a ^ b:
        return 1
    min_ops = lambda a, b: 1 + min_ops(a, a | b)
    return min_ops(a ^ b, b)

class Solution:

	def nextPalin(self, N):
		a = []
		ans = ''
		f = 0
		for i in range(int(len(N) / 2) - 1, -1, -1):
			a.append(int(N[i]))
			if N[i] > N[i - 1]:
				f = 1
				break
		if f == 0:
			return -1
		i -= 1
		a.sort()
		for j in range(len(a)):
			ans += str(a[j])
		ans = N[i] + ans
		for j in range(1, len(ans)):
			if int(ans[0]) < int(ans[j]):
				ans = ans[j] + ans[1:j] + ans[0] + ans[j + 1:]
				break
		ans = N[:i] + ans
		if len(N) % 2 == 0:
			ans += ans[::-1]
		else:
			ans += N[int(len(N) / 2)] + ans[::-1]
		return ans

