import itertools

def Runs(a, key=lambda k: k):
	i = 0
	while i < len(a):
		j = i
		while j < len(a) and key(a[i]) == key(a[j]):
			j += 1
		if i != j - 1:
			yield (i, j - 1)
		i = j

def Intersection(x, y):
	result = []
	ai = 0
	bi = 0
	while ai < len(x) and bi < len(y):
		a = x[ai]
		b = y[bi]
		if a[1] < b[0]:
			ai += 1
		elif b[1] < a[0]:
			bi += 1
		elif a[0] <= b[0]:
			if a[1] <= b[1]:
				result.append((b[0], a[1]))
				ai += 1
			else:
				result.append((b[0], b[1]))
				bi += 1
		elif b[1] <= a[1]:
			result.append((a[0], b[1]))
			bi += 1
		else:
			result.append((a[0], a[1]))
			ai += 1
	return result
m1 = 998244353

def IsNonDecreasing(a):
	a = list(a)
	for i in range(len(a) - 1):
		if a[i] > a[i + 1]:
			return False
	return True

def Factorial(n):
	result = 1
	for i in range(n):
		result *= i + 1
		result = result % m1
	return result

def Solve(a):
	n = len(a)
	a = list(sorted(a))
	do = IsNonDecreasing((x[1] for x in a))
	r1 = 1
	x = list(Runs(a, lambda x: x[0]))
	for (i, j) in x:
		f = Factorial(j - i + 1)
		r1 *= f
		r1 = r1 % m1
	r2 = 1
	if not do:
		a = sorted(a, key=lambda x: x[1])
	y = list(Runs(a, lambda x: x[1]))
	for (i, j) in y:
		f = Factorial(j - i + 1)
		r2 *= f
		r2 = r2 % m1
	d1 = 0
	if do:
		d1 = 1
		z = Intersection(x, y)
		for (i, j) in z:
			f = Factorial(j - i + 1)
			d1 *= f
			d1 = d1 % m1
	return (Factorial(n) - r1 - r2 + d1) % m1

def Classify(a):
	bad1 = True
	bad2 = True
	for i in range(len(a) - 1):
		if a[i][0] > a[i + 1][0]:
			bad1 = False
		if a[i][1] > a[i + 1][1]:
			bad2 = False
	if bad1 or bad2:
		return ('BAD', bad1, bad2)
	else:
		return ('GOOD',)
import collections

def SolveBrute(a):
	count = collections.Counter()
	for x in itertools.permutations(a):
		c = Classify(x)
		count[c[0]] += 1
		if c[0] == 'BAD':
			if c[1]:
				count['b1'] += 1
			if c[2]:
				count['b2'] += 1
			if c[1] and c[2]:
				count['b12'] += 1
	return count['GOOD']
