def pow_mod(a, b, mod):
    if b == 0:
        return 1
    if b == 1:
        return a
    p = pow_mod(a, b // 2, mod)
    if b % 2 == 0:
        return (p * p) % mod
    else:
        return ((p * p) % mod * a) % mod

def add_mod(a, b, mod):
    return (a + b) % mod

def subtract_mod(a, b, mod):
    return (a - b + mod) % mod

def multiply_mod(a, b, mod):
    return (a * b) % mod

def divide_mod(a, b, mod):
    return multiply_mod(a, pow_mod(b, mod - 2, mod), mod)

