    }
    int ans = 0;
    for (int i = 0; i < 26; i++)
    {
        if (cnt[i] > 0)
        {
            ans++;
        }
    }
    if (ans == 1)
    {
        cout << s << endl;
        return 0;
    }
    int i = 0;
    while (k > 0 && i < n)
    {
        if (cnt[s[i] - 'a'] > 0)
        {
            cnt[s[i] - 'a']--;
            k--;
            ans--;
        }
        i++;
    }
    if (k > 0)
    {
        cout << "-1" << endl;
        return 0;
    }
    cout << s << endl;
    return 0;
