import heapq

def minCost(start, target, specialRoads):
    def manhattan(x1, y1, x2, y2):
        return abs(x2 - x1) + abs(y2 - y1)

    # Create a graph where each node is a position (x, y)
    graph = {}
    graph[(start[0], start[1])] = []
    graph[(target[0], target[1])] = []

    for x1, y1, x2, y2, cost in specialRoads:
        if (x1, y1) not in graph:
            graph[(x1, y1)] = []
        if (x2, y2) not in graph:
            graph[(x2, y2)] = []
        graph[(x1, y1)].append((x2, y2, cost))

    # Add direct edges from start to all other nodes
    for x, y in graph:
        if (x, y) != (start[0], start[1]):
            graph[(start[0], start[1])].append((x, y, manhattan(start[0], start[1], x, y)))

    # Add direct edges from all nodes to target
    for x, y in graph:
        if (x, y) != (target[0], target[1]):
            graph[(x, y)].append((target[0], target[1], manhattan(x, y, target[0], target[1])))

    # Dijkstra's algorithm to find the shortest path
    pq = [(0, start[0], start[1])]
    distances = {(start[0], start[1]): 0}

    while pq:
        dist, x, y = heapq.heappop(pq)

        if (x, y) == (target[0], target[1]):
            return dist

        if dist > distances.get((x, y), float('inf')):
            continue

        for nx, ny, cost in graph[(x, y)]:
            new_dist = dist + cost
            if new_dist < distances.get((nx, ny), float('inf')):
                distances[(nx, ny)] = new_dist
                heapq.heappush(pq, (new_dist, nx, ny))

    return distances[(target[0], target[1])]

