import math

def Grasshopper(ng, nb):
	if nb % 2 == 0:
		nb = nb - 1
	if nb <= ng:
		return -1
	if ng == 2:
		return nb
	nng = math.floor(nb ** 0.5)
	if nng > ng:
		nng = ng
	for branch in range(nb, ng, -2):
		flag = True
		for hopper in range(3, nng + 1, 2):
			if branch % hopper == 0:
				flag = False
				break
		if flag == True:
			if branch > ng:
				return branch
			else:
				return -1
	return -1

def hello():
	ar = list(map(int, input().strip().split(' ')))
	result = Grasshopper(ar[0], ar[1])
	print(result)
