from typing import List
from queue import Queue

class Solution:

	def bfsOfGraph(self, V: int, adj: List[List[int]]) -> List[int]:
		isVisited = [1 if i == 0 else 0 for i in range(V)]
		q = Queue()
		q.put(0)
		res = []
		while q.qsize() > 0:
			topNode = q.get()
			res.append(topNode)
			for adjNode in adj[topNode]:
				if not isVisited[adjNode]:
					q.put(adjNode)
					isVisited[adjNode] = 1
		return res

