class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:

        trie = {}
        for x in nums:
            node = trie
            for bit in range(31, -1, -1):
                if (1 << bit) & x:
                    if not node.get(1):
                        node[1] = {}
                    node = node[1]
                else:
                    if not node.get(0):
                        node[0] = {}
                    node = node[0]

        return [self.max_xor(x, mi, trie) for x, mi in queries]

    def max_xor(self, x: int, mi: int, trie):
        ans = 0
        node = trie
        for bit in range(31, -1, -1):
            if (1 << bit) & x:
                if node.get(0):
                    node = node[0]
                    ans |= (1 << bit)
                else:
                    node = node[1]
            else:
                if node.get(1):
                    node = node[1]
                    ans |= (1 << bit)
                else:
                    node = node[0]

            if not node:
                return ans

        return ans

