// Task 2
// The following function counts the number of times a character appears in a string. It uses the for loop.
// The problem is on the side of complexity.

static int howMany(const char *s, char aChar)
{
	// declare the variable to count the occurrences of the character
	int count = 0;
	// traverse the string using a loop
	for (int counter = 0; s[counter] != '\0'; ++counter)
	{ // if the character in string s has been found,
		if (s[counter] == aChar)
		{	// increment count
			++count;
		}
	}

	// return the number of occurrences
	return count;
}

// Task 3
// The following function determines the minimum number of insertions/deletions required to change string string1 into string2.

int diff(string string1, string string2)
{
	int min = string1.length();
	// traverse each string from 0 to the length of the second string - 1
	for (int i = 0; i < string2.length(); ++i)
	{
		int cnt = 0;
		// if the characters in the same position are different, count them
		for (int j = i; j < string2.length(); ++j)
		{
			if (string1[j] != string2[j])
			{
				++cnt;
			}
		}
		if (min > cnt)
		{
			min = cnt;
		}
	}

	// return the difference between the original strings
	return min;
}

// Task 4
// The challenge is not to change the original string.
// Create a new string that contains the letters that are in str1 and str2.
// Given
// Input: str1 = "abc"
//     Output: "abc"
// Input: str1 = ""
//     Output: ""
// Input: str1 = "aabbcc"
//     Output: "abc"

string common(string str1, string str2)
{
	// define a string to store the common letters
	string commonLetters;
	// traverse each character of str1
	for (int i = 0; i < str1.length(); ++i)
	{
		char c = str1[i];
        // traverse each character in the string
		for (int j = 0; j < str2.length(); ++j)
		{
			// check if the letter in str1 is equal to the current letter in str2
			if (str2[j] == c)
			{
				// add the character to the string
				commonLetters.append(1, c);
				// break
				break;
			}
		}
	}

	// return the common letters
	return commonLetters;
}

