import java.util.*;

public class Solution {
    public List<String> invalidTransactions(String[] transactions) {
        List<String> invalidTransactions = new ArrayList<>();
        Map<String, List<Transaction>> map = new HashMap<>();

        // Iterate over the transactions and create a Transaction object for each
        for (String transaction : transactions) {
            String[] parts = transaction.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            int amount = Integer.parseInt(parts[2]);
            String city = parts[3];

            Transaction trans = new Transaction(name, time, amount, city);

            if (!map.containsKey(name)) {
                map.put(name, new ArrayList<>());
            }

            map.get(name).add(trans);
        }

        // Check for invalid transactions
        for (List<Transaction> transList : map.values()) {
            List<Transaction> sortedList = new ArrayList<>(transList);
            Collections.sort(sortedList, Comparator.comparingInt(a -> a.time));

            for (int i = 0; i < sortedList.size(); i++) {
                Transaction curr = sortedList.get(i);

                if (curr.amount > 1000) {
                    invalidTransactions.add(String.format("%s,%d,%d,%s", curr.name, curr.time, curr.amount, curr.city));
                } else {
                    // Check for transactions within 60 minutes in a different city
                    for (int j = i + 1; j < sortedList.size(); j++) {
                        Transaction other = sortedList.get(j);

                        if (Math.abs(curr.time - other.time) <= 60 && curr.city != other.city) {
                            invalidTransactions.add(String.format("%s,%d,%d,%s", curr.name, curr.time, curr.amount, curr.city));
                            invalidTransactions.add(String.format("%s,%d,%d,%s", other.name, other.time, other.amount, other.city));
                            break;
                        }
                    }
                }
            }
        }

        return invalidTransactions;
    }

    static class Transaction {
        String name;
        int time;
        int amount;
        String city;

        Transaction(String name, int time, int amount, String city) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
        }
    }
}

