int* findUnion(int *arr1,int size1,int *arr2,int size2) 
{
    int *union = malloc(size1 + size2 * sizeof(int));
    int i,j,k;
    int pos = 0;

    i = j = 0;

    while (i < size1 && j < size2) {
        if (arr1[i] <= arr2[j])
        {
            union[pos] = arr1[i++];
            pos++;
        }
        else if (arr2[j] <= arr1[i]) {
            union[pos] = arr2[j++];
            pos++;
        }
        else {
            union[pos] = arr2[j++];
            pos++;
        }
}

    while (i < size1) {
        union[pos] = arr1[i++];
        pos++;
    }

    while (j < size2) {
        union[pos] = arr2[j++];
        pos++;
    }

    // Displaying the final values
    display(union,pos);
    return union;
}

