public class Solution {

        public int findMinStep(String board, String hand) {

    	dp.clear();
    	return dfs(board , hand);

    }

    private boolean check(char ch , int cnt , String hand)
    {
    	int i , length = hand.length();
    	for (i = 0;i < length;i ++)
    	{
    		if (hand.charAt(i) == ch)
    			cnt --;
    	}
    	if (cnt <= 0)
    		return true;
    	else
    		return false;
    }

    private String getNextString(String board)
    {
    	char[] array = new char[30];
    	int i , j , length = board.length() , top = 0;
    	for (i = 0;i < length;i ++)
    	{
    		char ch = board.charAt(i);
    		int cnt = 0;
    		while (i < length && (board.charAt(i) == ch))
    		{
    			i ++;
    			cnt ++;
    		}
    		i --;
    		// erase
    		if (cnt >= 3)
    			continue;
    		else
    		{
    			if (top > 0 && array[top - 1] == ch)
    			{
    				while (top > 0 && (array[top - 1] == ch))
    				{
    					top --;
    					cnt ++;
    				}
    				// 可以删掉
    				if (cnt >= 3)
    					continue;
    				else
    				{
    					for (j = 0;j < cnt;j ++)
    					{
    						array[top] = ch;
    						top ++;
    					}
    				}
    			}
    			else
    			{
    				for (j = 0;j < cnt;j ++)
    				{
    					array[top] = ch;
    					top ++;
    				}
    			}
    		}
    	}	
    	return new String(array , 0 , top);
    }

    private String getNextHand(String hand , char ch , int cnt)
    {
    	StringBuilder builder = new StringBuilder();
    	int i , length = hand.length();
    	for (i = 0;i < length;i ++)
    	{
    		if (hand.charAt(i) == ch && cnt > 0)
    			cnt --;
    		else
    			builder.append(hand.charAt(i));
    	}
    	return builder.toString();
    }

    private static class Pair
    {
    	public String board , hand;

    	public Pair(String board , String hand)
    	{
    		this.board = board;

    		char[] array = hand.toCharArray();
    		Arrays.sort(array);
    		this.hand = new String(array);
    	}

    	public int hashCode()
    	{
    		return this.board.hashCode() * 31 + this.hand.hashCode();
    	}

    	public boolean equals(Object object)
    	{
    		Pair pair = (Pair) object;
    		return this.board.equals(pair.board) && this.hand.equals(pair.hand);
    	}
    }

    private Map<Pair , Integer> dp = new HashMap<Pair , Integer>();

    private int dfs(String board , String hand)
    {
    	if (board.equals(""))
    		return 0;

    	if (hand.equals(""))
    		return - 1;

    	Pair pair = new Pair(board , hand);
    	if (dp.containsKey(pair))
    		return dp.get(pair);

    	// 每次试图将一个删掉
    	int i , length = board.length() , ans = - 1;    	
    	for (i = 0;i < length;i ++)
    	{
    		char ch = board.charAt(i);
    		int temp = i , cnt = 0;
    		while (i < length && (board.charAt(i) == ch))
    		{
    			i ++;
    			cnt ++;
    		}
    		i --;
    		// 可以
    		if (check(ch , 3 - cnt , hand))
    		{
    			StringBuilder builder = new StringBuilder();
    			for (int j = 0;j < temp;j ++)
    				builder.append(board.charAt(j));
    			for (int j = i + 1;j < length;j ++)
    				builder.append(board.charAt(j));

    			int need = 3 - cnt;
    			int result = dfs(getNextString(builder.toString()) , getNextHand(hand , ch , need));
    			if (result >= 0)
    			{
    				result += need;
    				if (result < ans || ans < 0)
    					ans = result;
    			}
    		}
    	}

    	dp.put(pair , ans);

    	return ans;
    }

}

