def sum_array(arr):
	if arr == None or arr == []:
		return 0
	mi = min(arr)
	ma = max(arr)
	st = (arr.count(mi) - 1) * mi + (arr.count(ma) - 1) * ma
	for i in arr:
		if i not in [mi, ma]:
			st += i
	return st

def minOperations(self, target: List[int], arr: List[int]) -> int:
        index_target = {}
        for i, el in enumerate(target):
            index_target[el] = i
        stack = []
        arr_len = len(arr)
        for i in range(arr_len):
            while stack and index_target[arr[i]] >= index_target[arr[stack[-1]]]:
                stack.pop()
            stack.append(i)
        res = arr_len - stack[-1] - 1   
        while stack and index_target[arr[stack.pop()]] == len(target)-1:
            pass
        res += len(stack)
        return res

