def findAndReplace(S, Q, index, sources, targets):

    for i in range(Q):
        if S[index[i]:(index[i]+len(sources[i]))] == sources[i]:
            S = S[:index[i]] + targets[i] + S[(index[i]+len(sources[i])):]

    return S

