import itertools

def longest_common_subsequence(words):
    if not words:
        return 0

    shortest_word = min(words, key=len)

    def is_subsequence(word, subsequence):
        j = 0
        for char in word:
            if j < len(subsequence) and char == subsequence[j]:
                j += 1
        return j == len(subsequence)

    for length in range(len(shortest_word), 0, -1):
        for subsequence in itertools.combinations(shortest_word, length):
            if all(is_subsequence(word, subsequence) for word in words):
                return length
    return 0

def min_bad_luck(words):
    return min(longest_common_subsequence([word[i:i+m] for word in words]) 
               for m in range(1, 15) 
               for i in range(len(words[0]) - m + 1))

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        words = [input() for _ in range(n)]
        result = min_bad_luck(words)
        print(result)

