def smallest_b(n, s):
    if s < n or s >= n * (10 ** (len(str(n)) - 1)):
        return -1
    b = 1
    while True:
        total_sum = sum(digit * (b ** (len(str(n)) - i - 1)) for i, digit in enumerate(map(int, str(n)))[::-1])
        if total_sum == s:
            return b
        if total_sum > s:
            break
        b += 1
    while True:
        total_sum = sum(digit * (b ** (len(str(n)) - i - 1)) for i, digit in enumerate(map(int, str(n)))[::-1])
        if total_sum < s:
            b += 1
        elif total_sum == s:
            return b
        else:
            break
    return -1

