MOD = 10 ** 9 + 7
MAX = 20000

def modmul(x, y, c = 0):
    return (x * y + c) % MOD

def inv(x):
    return pow(x, MOD - 2, MOD)

class Solution:
    def idealArrays(self, n: int, maxValue: int) -> int:

        fact = [1]
        for i in range(1, MAX):
            fact.append(modmul(i, fact[i-1]))

        invfact = [1] * (MAX)
        invfact[MAX - 1] = inv(fact[MAX - 1])
        for i in range(MAX - 2, -1, -1):
            invfact[i] = modmul(i + 1, invfact[i+1])


        def comb(x, y):
            return modmul(fact[x], modmul(invfact[y], invfact[x - y]))

        factor = [1] * (maxValue + 1)

        for i in range(1, maxValue + 1):
            if factor[i] == 1:
                for j in range(i, maxValue + 1, i):
                    factor[j] = i

        out = 0
        for ii in range(1, maxValue + 1):
            i = ii
            pc = []
            curr = 1

            while i > 1:
                p = factor[i]
                ct = 0
                while i % p == 0:
                    ct += 1
                    i //= p
                assert ct > 0
                pc.append(ct)

            for v in pc:
                curr = modmul(curr, comb(n - 1 + v, v))

            #print(ii, curr, pc, comb(n, 1))

            out += curr
            out %= MOD
        return out

from typing import List
import math
from heapq import heappop, heappush

class Solution:

	def maximumDistance(self, v: int, e: int, src: int, edges: List[List[int]]) -> List[int]:
		adj = [[] for i in range(v)]
		for (a, b, c) in edges:
			adj[a].append([b, c])
		dist = [-math.inf] * v
		dist[src] = 0
		pq = []
		heappush(pq, (0, src))
		while pq:
			(dis, nod) = heappop(pq)
			for (x, y) in adj[nod]:
				if dist[x] < y + dis:
					heappush(pq, (y + dis, x))
					dist[x] = y + dis
		for i in range(v):
			if dist[i] == -math.inf:
				dist[i] = 'INF'
		return dist

import collections

def count_incoming_edges(graph):
	ret = collections.defaultdict(lambda : 0)
	for vs in graph.values():
		for v in vs:
			ret[v] += 1
	return ret

def topsort(edges, verts):
	sorted = []
	incoming_edges = count_incoming_edges(edges)
	S = collections.deque([v for v in verts if incoming_edges[v] == 0])
	while len(S) != 0:
		u = S.popleft()
		sorted.append(u)
		for v in edges[u]:
			assert incoming_edges[v] > 0
			incoming_edges[v] -= 1
			if incoming_edges[v] == 0:
				S.append(v)
		del edges[u]
	return sorted if len(edges) == 0 else None

def gen_constraint(a, b):
	if a in b or b in a:
		return None
	shorter = min(len(a), len(b))
	for i in range(shorter):
		ca = a[i]
		cb = b[i]
		if ca != cb:
			return (ca, cb)
	raise RuntimeError('should always find a difference!')

def main():
	num_names = int(input())
	names = []
	for _ in range(num_names):
		names.append(input())
	edges = collections.defaultdict(set)
	for i in range(len(names)):
		for j in range(i + 1, len(names)):
			a = names[i]
			b = names[j]
			constraint = gen_constraint(a, b)
			if constraint:
				(u, v) = constraint
				edges[u].add(v)
	all_letters = list(map(chr, range(ord('a'), ord('z') + 1)))
	if len(edges) == 0:
		sorted_names = list(names)
		names.sort()
		if sorted_names == names:
			print(''.join(all_letters))
		else:
			print('Impossible')
		return
	res = topsort(edges, all_letters)
	if res:
		print(''.join(res))
	else:
		print('Impossible')
