void sort(vector< ll > &v,ll low,ll high)
{
        if (low < high)
        {       ll mid = low + (high - low) / 2;
                sort(v,low,mid);
                sort(v,mid+1,high);
                merge(v,low,mid,high);
        }
}

void merge(vector< ll > &v,ll low,ll mid,ll high)
{
        ll a[mid-low+1],b[high - mid],i=0,j=0,k=low;
        for (int x = low; x < mid; ++x)
        {
                a[i] = v[x];
                ++i;
        }
        for (int x = mid; x <= high; ++x)
        {
                b[j] = v[x];
                ++j;
        }
        i = 0;
        j = 0;
        while (i < mid - low && j < high - mid)
        {
                if (a[i] < b[j])
                {
                        v[k++] = a[i++];
                }
                else
                {       v[k++] = b[j++];
                }
        }
        while (i < mid - low)
        {       v[k++] = a[i++];
        }
        while (j < high - mid)
        {       v[k++] = b[j++];
        }
}

