class Solution:

	def print2largest(self, arr, n):
		if n < 2:
			return -1
		largest = sec_largest = float('-inf')
		for i in range(0, n):
			if arr[i] > largest:
				sec_largest = largest
				largest = arr[i]
			elif arr[i] > sec_largest and arr[i] != largest:
				sec_largest = arr[i]
		if sec_largest == float('-inf'):
			return -1
		return sec_largest

