def count_flights(seq):
    """Returns the number of flights from Seattle to San Francisco"""

    flight_count = 0

    for idx, char in enumerate(seq[:-1]):
        if char == "S" and seq[idx+1] == "F":
            flight_count += 1

    return flight_count

def flights_from_forever(seq):
    """Prints 'YES' or 'NO' in case which we flew more times from Seattle to San Francisco"""

    flights = count_flights(seq)

    if flights > len(seq) / 2:
        print('YES')
    else:
        print('NO')

