def find_video_splits(n, k, durations):
    if k > n:
        return "No"

    total_duration = sum(durations)
    post_duration = total_duration // k
    if post_duration * k != total_duration:
        return "No"

    durations.sort(reverse=True)
    s = [0] * k
    for i in range(k):
        s[i] = sum(durations[:i+1]) - sum(durations[i+1:]) // (k-i)

    if sum(s) == n:
        return "Yes" + "\n" + " ".join(map(str, s))
    else:
        return "No"

# Example usage
