import math

def solve(N):
    ans = 0
    for a in range(1, N + 1):
        for b in range(a, N + 1): # start from a to avoid repeating pairs
            s = a * a + b * b + gcd(a, b) * gcd(a, b) + math.lcm(a, b) * math.lcm(a, b)
            if s == N:
                ans += 1
    return ans
