import math

def is_valid_pair(a, b, n):
    return a*a + b*b + math.gcd(a, b)**2 + (n - a*b)//math.gcd(a, b) == n*(n+1)//2

def find_pairs(n):
    count = 0
    for a in range(1, n+1):
        for b in range(a, n+1):
            if is_valid_pair(a, b, n):
                count += 1
    return count

