from math import gcd, sqrt

def is_pair_valid(a: int, b: int, n: int) -> bool:
    return a*a + b*b + (gcd(a, b) * gcd(a, b)) == n

def find_pairs(n: int) -> int:
    pairs_count = 0
    for a in range(1, n+1):
        for b in range(1, min(n+1, n-a)+1): # avoid b > n-a
            if is_pair_valid(a, b, n):
                pairs_count += 1
    return pairs_count

