import math

def extendedgcd(x, y):
	if x < y:
		(x, y) = (y, x)
	if x % y == 0:
		return [0, 1, y]
	eqn = [1, -1 * int(x / y), 0]
	coeff = extendedgcd(y, x % y)
	return [eqn[0] * coeff[1], coeff[1] * eqn[1] + coeff[0], coeff[2]]
