def count_keypresses(x):
    digit = int(str(x)[0])
    length = len(str(x))
    total = 0

    for i in range(1, 10):
        if i < digit:
            total += (1 + 2 + 3 + 4)
        elif i == digit:
            total += sum(range(1, length + 1))
            break

    return total

