    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        l1 = l2 = 0
        cnt1 = cnt2 = 0
        for k in nums1:
            if k == 0:
                cnt1 += 1
            else:
                l1 += k
        for k in nums2:
            if k == 0:
                cnt2 += 1
            else:
                l2 += k
        if l1 + cnt1 > l2 and cnt2 == 0 or l2 + cnt2 > l1 and cnt1 == 0:
            return -1
        if l1 == l2:
            return l1 + max(cnt1, cnt2)
        #print(l1, l2, cnt1, cnt2)
        if l1 < l2:
            l1, l2 = l2, l1
            cnt1, cnt2 = cnt2, cnt1

        l1 += cnt1
        l2 += cnt2
        return max(l1, l2)

