import sys

class item(object):
	def __init__(self, name, entry):
		self.name = name
		self.entry = entry
		self.number = None
		self.extended = False

def assignment(entry, names, outgoing):
	conflicts = []
	errors = []
	for n in names:
		if n.name == entry:
			return [n.name, [entry], [], [], 'Conflict']
	for n in names:
		if n.extended:continue
		for used in n.name:
			first = used
			i, ext = int(first), False
			if len(first) > len(used):
				ext = True
				i = int(first + '1')
			while i not in names[n.name].number and (not (first == used) or not ext):
				if len(first) + len(used) > entry + 31:
					errors.append(['The number must be up to 32 characters.'])
					break
				n.number = [i]
				n.extended = ext

				n.name = [ str(entry)[:-1] + lastTwo(conflict(n.name, a.name), lastTwo(n.number[0], i)) for lastTwo in n.name[1] for a in outgoing ]

