					n.number = mayconflict
					for a in conflictResults:
						if a in mayconflict: continue
						conflicts.append(a)

	errors = [ a[0] for a in errors ]

	return [c.name for c in conflicts], [['The number '+a+' is already used.'] for a in conflicts], names

