n, m, k = map(int, input().split())
def bfs(n, m, k):
    queue = []
    for i in range(n // 2 + 1):
        for j in range(m // 2 + 1):
            if (i + j) % 2 == 1:
                queue.append((i, j))
    return queue

def dfs(n, m, k, x, y, visited):
    visited.add((x, y))
    for i in range(x - 1, x + 2):
        for j in range(y - 1, y + 2):
            if i in range(n) and j in range(m) and (i, j) not in visited:
                dfs(n, m, k, i, j, visited)
    return visited


def check_condition(tube, n, m):
    # no pair of tubes has common cells
    for i in range(1, len(tube)):
        for j in range(i + 1, len(tube)):
            for k in range(i, j):
                x1, y1 = tube[i]
                x2, y2 = tube[j]
                x3, y3 = tube[k]
                if (x1 == x2 and y1 == y3) or (x1 == x3 and y1 == y2):
                    # print(x1, y1, x2, y2, x3, y3)
                    return False
    # each cell of the table belongs to some tube
    for i in range(1, len(tube)):
        for j in range(i + 1, len(tube)):
            x1, y1 = tube[i]
            x2, y2 = tube[j]
            if x1 == x2 and y1 == y2:
                return False
    return True

def solution(n, m, k):
    queue = bfs(n, m, k)
    if len(queue) < k:
        return
    visited = set()
    for i in range(k):
        tube = []
        x, y = queue.pop(0)
        tube.append((x, y))
        visited.add((x, y))
        dfs(n, m, k, x, y, visited)
        tube = list(visited)
        if check_condition(tube, n, m):
            print(len(tube))
            for t in tube:
                print(*t)
            return
    return

