class Solution:

	def findTwoElement(self, arr, n):
		A = set(range(1, n + 1))
		B = set(arr)
		missing = list(A - B)[0]
		dic = Counter(arr)
		twice = 0
		for (key, val) in dic.items():
			if val == 2:
				twice = key
				break
		return [twice, missing]

