bool judge(int a[], int n){

    static int used[SIZE+1];

    for(int i = 1; i <= n; i++) used[i] = 0;

    for(int i = 0; i < n; i++) used[a[i]] = 1;

    for(int i = 1; i <= n; i++) {

        if(!used[i]) return 0;

    }

    return 1;

}

bool judge(int len1, int n){

    return judge(p, len1) && judge(p + len1, n - len1);

