def Sandwiched_Vowel(s):
    vowels = 'aeiou'
    result = []
    n = len(s)

    for i in range(n):
        if i == 0 or i == n - 1 or s[i] not in vowels or s[i-1] in vowels or s[i+1] in vowels:
            result.append(s[i])

    return ''.join(result)

