def findDiagonalOrder(nums):
    diagonal = {}
    for i, row in enumerate(nums):
        for j, val in enumerate(row):
            if i + j not in diagonal:
                diagonal[i + j] = []
            diagonal[i + j].append(val)
    result = []
    for k, v in diagonal.items():
        if k % 2 == 0:
            result += v[::-1]
        else:
            result += v
    return result

python
def minCoins(n, S):
    INF = float('inf')
    dp = [[INF]*(S+1) for _ in range(n+1)]
    coins = [1, 2, 3, 4, 5]

    for i in range(n+1):
        dp[i][0] = 0

    for i in range(1, n+1):
        for j in range(1, S+1):
            if coins[i-1] <= j:
                dp[i][j] = min(dp[i-1][j], 1 + dp[i][j-coins[i-1]])
            else:
                dp[i][j] = dp[i-1][j]
    return dp[n][S]

