def can_form_teams(students):
    n = len(students)
    if n % 2 != 0:
        return False  # It's impossible to split into teams of equal size if n is odd

    distinct_skills = set(students)
    if len(distinct_skills) != n // 2:
        return False  # It's impossible to form teams with unique skills

    for skill in distinct_skills:
        if students.count(skill) != n // 2:
            return False  # Not all students have the same skill in the second team

    return True

def solve_problem():
    t = int(input())
    for _ in range(t):
        n = int(input())
        students = list(map(int, input().split()))
        x = n // 2 if can_form_teams(students) else 0
        print(x)

