def answer(S):
    cache = {}
    def helper(S, i, r):
        if r % 2 == 1:
            # even
            if S[i] % 2 == 0:
                return 0
            else:
                return -1
        elif r > 1:
            for e in xrange(i+1, len(S)):
                if S[e] % 2 == 1:
                    return -1
        return 0
    def try2(S, i, r):
        if r <= 1:
            return 0
        if (i,r) in cache:
            return cache[(i,r)]
        res = -1
        # odd
        if r % 2 == 1:
            if i == len(S):
                res = 0
            else:
                if S[i] % 2 == 1:
                    res = -1
                else:
                    for e in xrange(i, len(S)):
                        if S[e] % 2 == 1:
                            res = -1
                            break
                        else:
                            res = try2(S, i+1, r-1)
            if res == -1:
                res = 0
        # even
        elif r > 1:
            if i == len(S):
                res = 0
            elif S[i] % 2 == 1:
                res = -1
            else:
                for e in xrange(i+1, len(S)):
                    if S[e] % 2 == 1:
                        res = -1
                        break
                    else:
                        res = try2(S, i+1, r-1)
            if res == -1:
                res = 0
        cache[(i,r)] = res
        return res

