def subarraysDivByK(self, nums: List[int], k: int) -> int:class Solution:
    def subarraysDivByK(self, nums: List[int], k: int) -> int:
       dicts = {0:1}
        total = 0
        remainder = 0
        for i in range(len(nums)):
            remainder = (remainder + nums[i]) % k
            value = dicts.get(remainder,-1)
            if value != -1:
                dicts[remainder] = value + 1
            else:
                dicts[remainder] = 1
            total += dicts[remainder]
        return total

