class Solution {
public:
    int getLastMoment(int n, vector<int>& left, vector<int>& right) {
        int maxLeft = 0, minRight = n;
        for(int ant: left)
            maxLeft = max(maxLeft, ant);
        for(int ant: right)
            minRight = min(minRight, ant);
        return max(maxLeft, n - minRight);
    }
};

