def run(n, arr):
    remain = set()
    freq = dict()
    for a in arr:
        if a % k != 0:
            remain.add(a % k)
        freq[a % k] = freq.get(a % k, 0) + 1
    ret = 0
    for k in remain:
        for j in remain:
            if (k + j) % k == 0:
                ret += min(freq.get(k, 0), freq.get(j * 2 - k, 0))
    return ret

