public:
    int numberOfWays(int total, int cost1, int cost2) {
        if (cost1 > total || cost2 > total) {
            return 0;
        }
        if (cost1 == total || cost2 == total) {
            return 1;
        }
        if (cost1 == cost2) {
            return numberOfWays(total - cost1, cost1, cost2);
        }
        int dp[2][total + 1];
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;
        dp[1][0] = 1;
        for (int i = 1; i <= total; ++i) {
            if (i >= cost1) {
                dp[0][i] = dp[0][i - cost1];
            }
            if (i >= cost2) {
                dp[1][i] = dp[1][i - cost2];
            }
            if (i >= cost1 && i >= cost2) {
                dp[0][i] += dp[1][i - cost1];
            }
        }
        return dp[0][total];
    }
