from heapq import *

class Solution:

	def spanningTree(self, V, adj):
		minheap = []
		heappush(minheap, (0, 0))
		res = 0
		visited = [False for i in range(V)]
		while minheap:
			(wt, node) = heappop(minheap)
			if visited[node] == True:
				continue
			visited[node] = True
			res += wt
			for edge in adj[node]:
				nextNode = edge[0]
				nextWt = edge[1]
				if visited[nextNode]:
					continue
				heappush(minheap, (nextWt, nextNode))
		return res

def quickOld(v, st, dr):
	piv = v[st + (dr - st) // 2]
	i = st
	j = dr
	while i <= j:
		while i < dr and v[i] < piv:
			i += 1
		while j > st and v[j] > piv:
			j -= 1
		if i <= j:
			temp = v[i]
			v[i] = v[j]
			v[j] = temp
			i += 1
			j -= 1
	if i < dr:
		quickOld(v, i, dr)
	if j > st:
		quickOld(v, st, j)
