import math
class Solution :
    def maxSum(self, n) : 
        q = deque()
        q.append(n)
        sumVal = 0
        ct = 0
        while(q):
            curr = q.popleft()
            ct += 1
            currSum = math.floor(sumVal/ct)
            if len(str(curr)) == 1:
                currSum += 1
            currSum += sum(int(ch) for ch in str(curr))
            if currSum <= 12:
                q.append(curr)
                if currSum <= 12:
                    sumVal = currSum
                else:
                    sumVal = int(sum([int(ch) for ch in str(curr)]))
            elif curr <= n:
                sumVal = 0
                continue
            elif curr == n:
                ct = 1
            else:
                continue
        if ct > 12:
            return - 1
        else:
            return sumVal

