def min_sum_falling_path(arr):
    n = len(arr)
    heap = []
    for i in range(n):
        for j in range(n):
            heapq.heappush(heap, (arr[i][j], i, j))
    res = float('inf')
    for _ in range(n):
        val, i, j = heapq.heappop(heap)
        if i == n-1:
            res = min(res, val)
        else:
            heapq.heappush(heap, (val, i+1, j))
            heapq.heappush(heap, (val, i+1, j+1))
    return res

