class Solution {
    public int minOrAfterOperations(int[] nums, int k) {

        int [][] nextZero = new int [nums.length][30];

        int [] arr = new int [30];

        Arrays.fill(arr, nums.length);

        for (int i = nums.length - 1; i >= 0; --i) {

            for (int j = 0; j < 30; ++j) {
                if ( ( nums[i] & (1 << j) ) == 0)
                    arr[j] = i;

                nextZero[i][j] = arr[j];
            }
        }



        Set<Integer> set = new HashSet<>();
        int use;

        for (int bit = 29; bit >= 0; --bit) {

            use = solve(nextZero, set, bit);

            if (use <= k)
                set.add(bit);
        }


        int [] resArr = new int [30];

        Arrays.fill(resArr, 1);

        for (int num : set) {
            resArr[num] = 0;
        }

        int result = 0;

        for (int i = 29; i >= 0; --i) {
            result *= 2;
            result += resArr[i];
        }

        return result;
    }


    private int solve(int [][] nextZero, Set<Integer> set, int bit) {
        set.add(bit);

        int n = nextZero.length;
        int [] dp = new int [n + 1];
        int [] dpCheck = new int [n + 1];

        Arrays.fill(dp, 1_000_000);



        int minCheck = n - 1;

        Arrays.fill(dpCheck, minCheck);

        for (int i = n - 1; i >= 0; --i) {
            int pos = 0;

            for (int val : set) {
                pos = Math.max(pos, nextZero[i][val]);
            }

            if (pos == n) {
                continue;
            }

            int val = dpCheck[pos + 1] - i;

            dp[i] = val;
            minCheck = Math.min(minCheck, dp[i] + i - 1);
            dpCheck[i] = minCheck;
        }

        set.remove(bit);
        return dp[0];
    }
}

