const int maxn=1e5+10;
struct node {
    int Left,Right,val;
}NODE[maxn<<2];
void PushUp(int idx) {
    NODE[idx].val=min(NODE[idx<<1].val,NODE[idx<<1|1].val);
}
void build(int l, int r, int idx, string& s) {
    NODE[idx]={l,r,0};
    if (l==r) {
        NODE[idx].val=s[l-1]-'0';
        return;
    }
    int m=(l+r)>>1;
    build(l,m,idx<<1,s);
    build(m+1,r,idx<<1|1,s);
    PushUp(idx);
}
void Updata(int pos, int idx) {
    if (NODE[idx].Left==NODE[idx].Right) {
        NODE[idx].val=11;
        return;
    }
    int m=(NODE[idx].Left+NODE[idx].Right)>>1;
    if (pos<=m) Updata(pos,idx<<1);
    else Updata(pos,idx<<1|1);
    PushUp(idx);
}
int query(int l, int r, int idx) {
    if (NODE[idx].Left==l&&NODE[idx].Right==r) return NODE[idx].val;
    int m=(NODE[idx].Left+NODE[idx].Right)>>1;
    if (r<=m) return query(l,r,idx<<1);
    else if (l>m) return query(l,r,idx<<1|1);
    else return min(query(l,m,idx<<1),query(m+1,r,idx<<1|1));
}
