public class Solution {
    public String strWithout3a3b(int a, int b) {
        int target = a+b;

        char c = 'a';
        StringBuffer sb = new StringBuffer();

        while(target > 0){
            if(target > 1){
                if(a%3==0){
                    target-=1;
                    sb.append(c);
                }
                else{
                    c = 'b';
                    target-=2;
                    sb.append(c);
                    sb.append(c);
                }
            }
            else{
                if(c=='b'){
                    target-=1;
                    sb.append(c);
                }
                else{
                    target-=2;
                    sb.append(c);
                    sb.append(c);
                }
            }
        }

        c ='b';
        sb.toString();
        StringBuffer out = new StringBuffer();
        for(int i=0;i<sb.length();i++){
            if(sb.charAt(i)==c){
                int next = i+1;
                if(sb.charAt(next) == sb.charAt(next)){
                    out.append(sb.substring(next,next+1));
                }
                else{
                    out.append(sb.substring(next,next+2));
                }
            }
        }

        return out.toString();
    }
}




