class Solution {
public:
    bool sequenceReconstruction(vector<int>& nums, vector<vector<int>>& sequences) {
        int n = nums.size();
        vector<int> indegree(n + 1, 0);
        vector<vector<int>> graph(n + 1);
        for (auto& seq : sequences) {
            for (int i = 0; i < seq.size() - 1; i++) {
                int u = seq[i];
                int v = seq[i + 1];
                graph[u].push_back(v);
                indegree[v]++;
            }
        }
        queue<int> q;
        for (int i = 1; i <= n; i++) {
            if (indegree[i] == 0) {
                q.push(i);
            }
        }
        vector<int> topo;
        while (!q.empty()) {
            if (q.size() > 1) {
                return false;
            }
            int u = q.front();
            q.pop();
            topo.push_back(u);
            for (int v : graph[u]) {
                indegree[v]--;
                if (indegree[v] == 0) {
                    q.push(v);
                }
            }
        }
        return topo == nums;
    }
};

