class Solution {
    public int[] rearrangeArray(int[] nums) {
        int n = nums.length;
        List<Integer> pos = new ArrayList<>(n/2);
        List<Integer> neg = new ArrayList<>(n/2);

        for (int num : nums)    {
            if (num < 0)
                neg.add(num);
            else
                pos.add(num);
        }
        int[] ans = new int[n];
        int p = 0, q = 0;
        int index = 0;
        while (index < n)  {
            ans[index++] = pos.get(p++);
            ans[index++] = neg.get(q++);
        }

        return ans;
    }
}

