def numberOfWays(arr, n):
    sameCount = 1 if arr[0]==arr[-1] else 0    #count for elements which are equal to smallest to largest 
    increasing = 1 if arr[-1]>=arr[0] else 0    #count for elements which are increasing from smallest to largest 
    decreasing = 1 if arr[0]<=arr[-1] else 0    #count for elements which can decrease from largest to smallest 
    for i in range(1, n):
        if arr[i] == arr[0]: 
            sameCount+=1
        if arr[i] > arr[0] :
            increasing = 0
        if arr[i] < arr[-1]:
            decreasing = 0

    return sameCount + increasing + decreasing

