vector<int> sum_of_intervals(vector<int>& arr) {
    unordered_map<int, vector<int>> m;
    for (int i = 0; i < arr.size(); ++i) {
        m[arr[i]].push_back(i);
    }
    vector<int> res;
    for (int i = 0; i < arr.size(); ++i) {
        vector<int>& v = m[arr[i]];
        int sum = 0;
        for (int j = 0; j < v.size(); ++j) {
            if (v[j] != i) {
                sum += abs(v[j] - i);
            }
        }
        res.push_back(sum);
    }
    return res;
}

