def hash_value(S, P):
    stack = []
    password_digits = [int(digit) for digit in P]

    def binary_op(op, a, b):
        if op == '+':
            return a | b
        elif op == '*':
            return a & b
        elif op == '^':
            return a ^ b

    for char in S:
        if char in 'abcd':
            stack.append(password_digits[ord(char) - ord('a')])
        elif char in '+*^':
            b = stack.pop()
            a = stack.pop()
            result = binary_op(char, a, b)
            stack.append(result)
        elif char in '[]':
            continue

    return stack[0]

def count_matching_passwords(S, hash_val):
    count = 0
    for i in range(10000):
        P = f"{i:04d}"
        if hash_value(S, P) == hash_val:
            count += 1
    return count

