def who_wins(test_cases):
    results = []
    for test_case in test_cases:
        n = test_case['n']
        goals = test_case['goals']
        team_a = 0
        team_b = 0
        for goal in goals:
            if goal == 'ab':
                team_a += 1
            elif goal == 'bc':
                team_b += 1
        if team_a > team_b:
            results.append('ab')
        elif team_b > team_a:
            results.append('bc')
        else:
            results.append('Draw')
    return results

