class Solution:
    def maxValue(self, events: List[List[int]], k: int) -> int:
        es = sorted(events, key=lambda x: [x[0],x[1],-x[2]])
        ans = 0
        n = len(es)

        @cache
        def dfs(last, k):
            if k == 0:
                return 0
            e = es[last][1]
            ans = 0
            for i in range(last, n):
                if es[i][0] <= e:
                    continue
                ans = max(ans, dfs(i, k-1) + es[i][2])
            return ans

        return max([dfs(i, k-1) + es[i][2] for i in range(n)])

