class Solution:

	def longestWPI(self, hours: List[int]) -> int:
		d = {}
		P = [0]
		F = [0 for i in range(len(hours))]
		res = 0
		for i in range(len(hours)):
			P.append(P[-1] + (1 if hours[i] > 8 else -1))
			if P[-1] > 0:
				F[i] = i + 1
			else:
				s = d.get(P[-1] - 1, -1)
				if s >= 0:
					F[i] = max(F[i], i - s + F[s])
			if P[-1] not in d:
				d[P[-1]] = i
			res = max(res, F[i])
		return res

def getMaxLen(nums):
    max_len = 0
    pos_prod = 0
    neg_prod = 0
    first_neg = -1
    zero_idx = -1

    for i, num in enumerate(nums):
        if num == 0:
            pos_prod = 0
            neg_prod = 0
            first_neg = -1
            zero_idx = i
            continue

        if pos_prod == 0:
            pos_prod = 1 if num > 0 else 0
            neg_prod = 1 if num < 0 else 0
            first_neg = i if num < 0 else -1
        else:
            if num > 0:
                pos_prod += 1
                if first_neg!= -1:
                    neg_prod += 1
            else:
                if first_neg!= -1:
                    pos_prod = neg_prod + 1
                    neg_prod = i - first_neg + 1
                    first_neg = i
                else:
                    neg_prod += 1
                    first_neg = i

        max_len = max(max_len, pos_prod)

    return max_len

