def is_perfect_square(A, M):
	if M == 2 or A == 0:
		return True
	else:
		exponent = (M - 1) // 2
		result = 1
		current_power_of_A = A
		while exponent > 0:
			if exponent % 2 == 1:
				result = result * current_power_of_A
				result = result % M
			exponent = exponent // 2
			current_power_of_A = current_power_of_A * current_power_of_A
			current_power_of_A = current_power_of_A % M
		return result == 1
