import math

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_nearly_primes(limit):
    nearly_primes = []
    max_p = int(math.sqrt(limit)) + 1
    for p in range(2, max_p):
        if is_prime(p):
            for q in range(p + 1, max_p):
                if is_prime(q):
                    nearly_prime = p * q
                    if nearly_prime <= limit:
                        nearly_primes.append(nearly_prime)
    return sorted(set(nearly_primes))

def find_solution(n):
    nearly_primes = generate_nearly_primes(n)
    length = len(nearly_primes)
    for i in range(length):
        for j in range(i + 1, length):
            for k in range(j + 1, length):
                sum_ijk = nearly_primes[i] + nearly_primes[j] + nearly_primes[k]
                if sum_ijk >= n:
                    break
                remaining = n - sum_ijk
                if remaining > nearly_primes[k] and remaining not in nearly_primes:
                    return f"YES\n{nearly_primes[i]} {nearly_primes[j]} {nearly_primes[k]} {remaining}"
    return "NO"

def main():
    import sys
    import threading

    def solve():
        input = sys.stdin.read().split()
        t = int(input[0])
        index = 1
        results = []
        for _ in range(t):
            n = int(input[index])
            results.append(find_solution(n))
            index += 1
        print("\n".join(results))

    sys.setrecursionlimit(1 << 25)
    threading.Thread(target=solve).start()

