def minCoins(n, a):
    cost = 0
    for i in range(n):
        while a[i] != 1:
            if a[i] < 1:
                a[i] = -a[i]
                cost += 1
            else:
                a[i] = 1
                cost += 1
    return cost

if root is None:
        return None

    if root.left is None and root.right is None:
        if root.data == key:
            return None
        else:
            return root

    key_node = None
    q = []
    q.append(root)
    temp = None

    # Do level order traversal to find
    # the deepest node(temp) and node
    # to be deleted (key_node)
    while len(q) > 0:
        temp = q.pop(0)

        if temp.data == key:
            key_node = temp
        if temp.left:
            q.append(temp.left)
        if temp.right:
            q.append(temp.right)

    if key_node:
        x = temp.data
        deleteDeepest(root, temp)
        key_node.data = x

    return root

def deleteDeepest(root, d_node):
    q = []
    q.append(root)
    while (len(q)):
        temp = q.pop(0)
        if temp is d_node:
            temp = None
            return
        if temp.right:
            if temp.right is d_node:
                temp.right = None
                return
            else:
                q.append(temp.right)
        if temp.left:
            if temp.left is d_node:
