from collections import Counter

class Solution:

	def minValue(self, s, k):
		heap = []
		for x in Counter(s).values():
			heappush(heap, -x)
		while k:
			heappush(heap, heappop(heap) + 1)
			k -= 1
		return sum((x * x for x in heap))

