def solve(a, b):
    a = deque(a)
    b = deque(b)
    c = []
    while a and b:
        if a[0] == b[0]:
            c.append(a.popleft())
            b.popleft()
        elif a[0] < b[0]:
            a.popleft()
        else:
            b.popleft()
    if a or b:
        return "NO"
    return "YES", len(c), c

