import os, sys
from io import BytesIO, IOBase
from collections import defaultdict, deque
from copy import deepcopy

def longest_path(path, n):
	st = [1]
	depth = [[0, 0] for _ in range(n + 1)]
	ans = 0
	while len(st):
		if not len(path[st[-1]]):
			x = depth[st.pop()]
			ans = max(ans, sum(x))
			if len(st):
				y = depth[st[-1]]
				if y[0] < x[0] + 1:
					(y[1], y[0]) = (y[0], x[0] + 1)
				elif y[1] < x[0] + 1:
					y[1] = x[0] + 1
			continue
		i = path[st[-1]].pop()
		path[i].remove(st[-1])
		st.append(i)
	return ans

def road(a, b, path, com):
	st = [a]
	ans = 0
	while len(st):
		if not len(path[st[-1]]):
			ans -= 1
			st.pop()
			continue
		x = path[st[-1]].pop()
		path[x].remove(st[-1])
		st.append(x)
		ans += 1
		if x == b:
			return True if ans <= com else False

