def min_minutes_to_sort_vases(N, M, p, robot_pairs):
    # Create a graph for the robot pairs
    robot_graph = {i: [] for i in range(1, N + 1)}
    for x, y in robot_pairs:
        robot_graph[x].append(y)
        robot_graph[y].append(x)

    # Function to check if a permutation can be sorted using the robot
    def can_robot_sort(permutation):
        visited = [False] * (N + 1)
        for i in range(1, N + 1):
            if not visited[i]:
                cycle = []
                while not visited[i]:
                    visited[i] = True
                    cycle.append(i)
                    i = permutation[i - 1]
                for a in cycle:
                    for b in cycle:
                        if b not in robot_graph[a]:
                            return False
        return True

    # Generate all permutations of [1, 2, ..., N]
    all_permutations = list(permutations(range(1, N + 1)))

    # Find the minimum number of swaps needed
    min_swaps = float('inf')
    for perm in all_permutations:
        if can_robot_sort(perm):
            min_swaps = 0
            break
    else:
        # If the robot can't sort it, calculate the minimum swaps
        for perm in all_permutations:
            swaps = 0
            visited = [False] * (N + 1)
            for i in range(1, N + 1):
                if not visited[i]:
                    cycle = []
                    while not visited[i]:
                        visited[i] = True
                        cycle.append(i)
                        i = perm[i - 1]
                    swaps += len(cycle) - 1
            min_swaps = min(min_swaps, swaps)

    return min_swaps

