        for (int i = 0; i < n; i++) a[i] = new Scanner(System.in).nextInt() - 1;
        for (int i = 0; i < n; i++) b[i] = new Scanner(System.in).nextInt() - 1;
        new Solution(n, a, b).print(new PrintWriter(System.out));
    }
}

class Solution {
    Solution(int n, int[] a, int[] b) {
        this.n = n;
        this.a = a;
        this.b = b;
        int[] indeg1 = new int[n], indeg2 = new int[n];
        for (int i = 0; i < n; i++) {
            indeg1[a[i]]++;
            indeg2[b[i]]++;
        }
        if (indeg1[0] > 0 || indeg2[0] > 0) {
            int l = 0;
            while (indeg1[l] > 0 || indeg2[l] > 0) l++;
            in(a, l, 1);
            in(b, l, 1);
        } else in(a, 0, -1);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] != b[i]) {
                in(a, a[i], -1);
                in(b, a[i], 1);
                p[i] = ans++;
                in(a, a[i], 1);
                in(b, a[i], -1);
            }
        }
        if (ans < n) for (int i = 0; i < n; i++) if (a[i] != b[i]) {
            in(a, b[i], -1);
            in(a, b[i], 1);
            p[n + i] = ans++;
            in(a, b[i], 1);
            in(a, b[i], -1);
        }
        for (int i = 0; i < n; i++) b[i] += 1;
        pinv = new int[n];
        for (int i = 0; i < n; i++) {
            in(b, p[i], -1);
            pinv[b[p[i]]] = i;
            in(b, p[i], 1);
        }
        System.out.print(ans);
    }
    int n, a[], b[], p[] = new int[2 * n];
    int[] pinv;
    int indeg(int[] a, int x, int v) {
        return a[in(a, x, a[x])];
    }
    int in(int[] a, int x, int v) {
        x = indeg(a, x, v);
        a[in(a, x, x + 1)] = x;
        return x;
    }
    void print(PrintWriter out) {
        for (int i = 0; i < n; i++) out.println(pnv[i] + 1);
    }
}

