public class Solution {
    private static class State implements Comparable<State> {
        int r;
        int c;
        int dir;
        int distance;
        String path;

        public State(int r, int c, int dir, int distance, String path) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.distance = distance;
            this.path = path;
        }

        @Override
        public int compareTo(State o) {
            if (this.distance != o.distance) {
                return Integer.compare(this.distance, o.distance);
            }

            return this.path.compareTo(o.path);
        }
    }

    private static int[] DIR_R = {-1, 0, 1, 0};
    private static int[] DIR_C = {0, 1, 0, -1};
    private static char[] DIR_NAME = {'u', 'r', 'd', 'l'};

    public String findShortestWay(int[][] maze, int[] ball, int[] hole) {
        int n = maze.length;
        int m = maze[0].length;
        int[][][] visited = new int[4][n][m];

        PriorityQueue<State> q = new PriorityQueue<State>();
        int r = ball[0];
        int c = ball[1];
        for (int i = 0; i < 4; i++) {
            int tr = r + DIR_R[i];
            int tc = c + DIR_C[i];
            if (tr >= 0 && tr < n && tc >= 0 && tc < m && maze[tr][tc] == 0) {
                q.add(new State(tr, tc, i, 1, new String("" + DIR_NAME[i])));
                visited[i][tr][tc] = 1;
            }
        }

        while (!q.isEmpty()) {
            State s = q.poll();
            if (s.r == hole[0] && s.c == hole[1]) {
                return s.path;
            }

            int tr = s.r + DIR_R[s.dir];
            int tc = s.c + DIR_C[s.dir];
            if (tr >= 0 && tr < n && tc >= 0 && tc < m && maze[tr][tc] == 0) {
                if (visited[s.dir][tr][tc] == 0) {
                    q.add(new State(tr, tc, s.dir, s.distance + 1, s.path));
                    visited[s.dir][tr][tc] = 1;
                }
            } else {
                for (int i = 0; i < 4; i++) {
                    tr = s.r + DIR_R[i];
                    tc = s.c + DIR_C[i];
                    if (tr >= 0 && tr < n && tc >= 0 && tc < m && maze[tr][tc] == 0) {
                        if (visited[i][tr][tc] == 0) {
                            q.add(new State(tr, tc, i, s.distance + 1, s.path + DIR_NAME[i]));
                            visited[i][tr][tc] = 1;
                        }
                    }
                }
            }
        }

        return "impossible";
    }
}

