import copy
from math import inf

def get_vector(x1, x2, y1, y2):
    x_diff = x1 - x2
    y_diff = y1 - y2

    x_diff = x_diff * -1 if x_diff <= 0 else x_diff # it is important to not modify original diff
    y_diff = y_diff * -1 if y_diff <= 0 else y_diff

    return x_diff, y_diff

def get_quantity_by_(inpt, *args, try_num = 0):
    vectors = set()
    length_vectors = set()

    for i in range(1, len(inpt)):

        x1, y1 = int(inpt[0][1]), int(inpt[0][2]) # coordinates of gun
        x2, y2 = int(inpt[i][1]), int(inpt[i][2])  # coordinates of stormtrooper

        x_diff, y_diff = get_vector(x1, x2, y1, y2)

        if x_diff == 0 or y_diff == 0:
            if x_diff == 0:
                x_diff = inf
            if y_diff == 0:
                y_diff = inf

        vectors.add((x_diff, y_diff))
        length_vectors.add((x_diff, y_diff, x1, y1, x2, y2))

    prev_vectors = copy.deepcopy(length_vectors)

