class Solution:
    def __init__(self, length: int, remove: int):
        self.length = 0
        self.remove = 0
        if not isinstance(length, int) or not isinstance(remove, int) or length and remove and (remove > length or length >= remove):
            raise Exception('Wrong input value')
        self.length = length
        self.remove = remove

    def run(self) -> str:
        sub = self.remove
        str = ''.join(reversed(sorted("abcdefghijklmnopqrstuvwxyz")))
        storage = ["".join(i) for i in zip(*[iter(str)]*self.remove)]
        final = []
        while self.remove:
                start = -1
                for i in storage:
                    if i not in final:
                        start = start + 1
                        final.append(i)
                        break
                index = str.find(i)
                del str[index:index+start]
                self.remove = self.remove - start
                sub = self.remove
        for i in storage:
            if i in final:
                str = str.replace(i, '')
        return ''.join(reversed(sorted(str)))

