class Solution:
    def longestPalindrome(self, words: list[tuple[str, int]]) -> int:
        words = sorted(words, key = lambda x: x[1], reverse = True)

        d = collections.defaultdict(int)
        for a, b in words:
            d[a] += 1
            d[b] -= 1

        count = 0
        for key, val in d.items():
            if val % 2 == 1:
                count += val
            else:
                count += val // 2 * 2
        return count

