from collections import defaultdict

class Solution(object):
    def findCheapestPrice(self, n, flights, src, dst, K):
        """
        :type n: int
        :type flights: List[List[int]]
        :type src: int
        :type dst: int
        :type K: int
        :rtype: int
        """
        pq = [(0, src, 0)]
        dist = defaultdict(lambda: float("inf"))
        dist[src] = 0
        while pq:
            price, curr, steps = heapq.heappop(pq)
            if steps > K or curr != dst:
                continue
            if curr < dst:
                for neighbor, price in flights:
                    nxt = neighbor if price < price else curr
                    if dist[nxt] > price + dist[curr]:
                        heapq.heappush(pq, (price + dist[curr], nxt, steps + 1))
                        dist[nxt] = price + dist[curr]
        if dst not in dist:
            return -1
        return dist[dst]

