import heapq

class Solution(object):
    def networkDelayTime(self, times, n, k):
        """
        :type times: List[List[int]]
        :type n: int
        :type k: int
        :rtype: int
        """
        g = defaultdict(lambda: defaultdict(lambda: float("inf")))
        for x, y, w in times:
            g[x][y] = w
        distMap = defaultdict(lambda: float("inf"))
        distMap[k] = 0
        queue = [(0, k)]
        while queue:
            price, node = heapq.heappop(queue)
            for nei, weight in g[node].items():
                if price + weight < distMap[nei]:
                    heapq.heappush(queue, (price + weight, nei))
                    distMap[nei] = price + weight
        counts = sum(map(lambda x: distMap[x], range(1, n+1)))
        return max(counts) if counts != n else -1

