    max_beauty_difference = flowers[-1] - flowers[0]
    count = 0

    for i in range(len(flowers)):
        for j in range(i + 1, len(flowers)):
            if flowers[j] - flowers[i] == max_beauty_difference:
                count += 1

    return max_beauty_difference, count

def main():
    input = sys.stdin.readline
    n = int(input())
    flowers = list(map(int, input().split()))

    max_beauty_difference, count = calculate_beauty_difference(n, flowers)
    print(max_beauty_difference, count)

if __name__ == "__main__":
    main()

