def game(N, S):
  if N > S:
    return "NO"
  mean = S // N
  if mean % 2 == 0:
    return "NO"
  answer = [mean] * (N - N // 4) + [mean - 1] * (N // 4)
  k = (sum(answer[:-N // 4]) - sum(answer[-N // 4:])) // 2
  return "YES\n" + " ".join(map(str, answer)) + "\n" + str(k)

print(game(1,4))
print(game(3,4))
print(game(3,8))

