import heapq
def passcodeDerivation(n):
    pressed = [False] * (n+1)
    visited = [0] * (n+1)
    stillPressed = []

    heapq.heapify(stillPressed)

    for i in range(1,n+1):
        heapq.heappush(stillPressed,i)

    current = 1

    while len(stillPressed) > 0:
        top = heapq.heappop(stillPressed)
        if top == current:
            current += 1
        else:
            heapq.heappush(stillPressed,top)
            pressed[top] = True

        for i in range(1,top):
            if pressed[i]:
                visited[i] = visited[top] + abs(top - i)
                break

        for i in range(top+1,n+1):
            if pressed[i]:
                visited[i] = visited[top] + abs(top - i)
                break

    countPush = 0
    for i in range(1,n+1):
        if not pressed[i]:
            countPush += visited[i]

    return countPush

