import java.util.*;



public class solution {

  static Scanner myscanner = new Scanner(System.in);

  public static void main(String[] args){

    int test = myscanner.nextInt();

    while(test > 0){

      int n = myscanner.nextInt();

      int m = myscanner.nextInt();

      int[] a = new int[n + 1];

      for(int i = 1; i <= n; ++i){

        a[i] = myscanner.nextInt();

      }

      PriorityQueue<Integer> Q = new PriorityQueue<> (Collections.reverseOrder());

      long sum = 0;

      int ans = 0;

      for(int i = m; i > 1; --i){

        sum += a[i];

        Q.add(a[i]);

        if(sum > 0){

          int x = Q.peek();

          Q.poll();

        //  System.out.print(sum + " " + a[i] + "\n");

          sum -= 2 * x;

          ans += 1;

        }

      }

      PriorityQueue<Integer> R = new PriorityQueue<Integer> ();

      sum = 0;

      for(int i = m + 1; i <= n; ++i){

        sum += a[i];

        R.add(a[i]);

        if(sum < 0){

          int x = R.peek();

          R.poll();

          sum -= 2 * x;

          ans += 1;

        }

      }

      System.out.println(ans);

      test--;

    }

  }

}

