int check(string &s, int l, int r){
    if(r-l+1==s.length())
        return s.empty() ? 0 : r-l+1;

	int sum = 0;
    int minIndex = r+1;

	for(int i = l; i <= r; ++i) {
		if(s[i] == '+') {
			sum++;
		} else {
			sum--;
		}

		if(sum == 0 && (r - i + 1) < minIndex) {
			minIndex = r - i + 1;
		}
	}

	if(sum < 0)
		minIndex = min(minIndex, -sum);

	return minIndex;
}

