import java.util.*;

public class D {

	BufferedReader bufIn;
	PrintWriter out;

	String tok = null;

	String readTok() throws IOException{
		while (tok == null || tok.isEmpty()) {
			tok = bufIn.readLine();
		}
		return tok;
	}

	int nextInt() throws IOException {
		return Integer.parseInt(readTok());
	}

	long nextLong() throws IOException {
		return Long.parseLong(readTok());
	}

	String next() throws IOException {
		return readTok();
	}


	void solve() throws IOException, InterruptedException {
		int n = nextInt();
		int k = nextInt();
		int[] ingredients = new int[n];
		int[] own = new int[n];
		for (int i = 0; i < n; i++) {
			ingredients[i] = nextInt();
		}
		for (int i = 0; i < n; i++) {
			own[i] = nextInt();
		}
		int limit = 0;
		for (int i = 0; i < n; i++) {
			limit = Math.max(limit, k / ingredients[i]);
		}

		int [][] ms = new int[n][limit];
		for (int i = 0; i < n; i++) {
			int[] as = ms[i];
			for (int j = 0; j < limit; j++) {
				as[j] = (int) Math.min(as[j], Math.max(0, own[i] / ingredients[i]));
			}
		}
		int [] sum = new int[limit];

		for (int[] arr : ms) {

			for (int i = 0; i < limit; i++) {
				sum[i] += arr[i];
			}
		}
		int res = 0;

		for (int i = 0; i < limit; i++) {
			if (sum[i] >= k) {
				int x = k / ingredients[i];
				res = Math.max(res, sum[i] - 1 + x);
			}
		}
		if (res > 0)
			res--;
		out.println(res);
	}

	public static void main(String[] args) throws InterruptedException {
		new D().run();
	}

