from typing import List, Tuple

@dataclass
class TestCase:
    x: str
    k: int

def solve(test_case: TestCase) -> int:
    x = test_case.x
    k = test_case.k

    if k == 0:
        return int(x)

    if k >= len(x):
        return 1

    # Find the first non-zero digit
    for i in range(len(x)):
        if x[i] != '0':
            # Remove the first non-zero digit
            return int(x[:i] + x[i+1:])

    # If all digits are zero, remove the last digit
    return int(x[:-1])

def main():
    t = int(input())
    test_cases: List[TestCase] = []

    for _ in range(t):
        x = input()
        k = int(input())
        test_cases.append(TestCase(x, k))

    for test_case in test_cases:
        result = solve(test_case)
        print(result)

