def solver(strings):
	maxLength = 0
	for s in strings:
		if len(s) > maxLength:
			maxLength = len(s)
	print('*' * (maxLength + 2))
	leftBound = True
	for s in strings:
		spaces = maxLength - len(s)
		line = None
		if spaces % 2 == 0:
			line = '*' + ' ' * (spaces // 2) + s + ' ' * (spaces // 2) + '*'
		else:
			if leftBound == True:
				line = '*' + ' ' * (spaces // 2) + s + ' ' * (spaces // 2 + 1) + '*'
			else:
				line = '*' + ' ' * (spaces // 2 + 1) + s + ' ' * (spaces // 2) + '*'
			leftBound = not leftBound
		print(line)
	print('*' * (maxLength + 2))
