import sys

def mex(s):
    if '0' not in s:
        return 0
    if '1' not in s:
        return 1
    return 2

def optimal_mex_sum(s):
    if '0' not in s:
        return 0
    if '1' not in s:
        return len(s)
    last_zero = -1
    last_one = -1
    total = 0
    for i, c in enumerate(s):
        if c == '0':
            if last_one != -1:
                total += mex(s[last_one:i])
                last_one = -1
            last_zero = i
        else:
            if last_zero != -1:
                total += mex(s[last_zero:i])
                last_zero = -1
            last_one = i
    if last_zero != -1:
        total += mex(s[last_zero:])
    if last_one != -1:
        total += mex(s[last_one:])
    return total

