class Solution {
public:
    int n,m;
    bool valid(int row,int col){
        if(row>=0&&row<n&&col>=0&&col<m)return true;
        return false;
    }
    vector<vector<int>> matrixBlockSum(vector<vector<int>>& mat, int k) {
        n = mat.size();
        m = mat[0].size();
        vector<vector<int>>ans;
        for(int i = 0;i<n;i++){
            for(int j = 0;j<m;j++){
                if(valid(i-1,j))mat[i][j] += mat[i-1][j];
                if(valid(i,j-1))mat[i][j] += mat[i][j-1];
                if(valid(i-1,j-1))mat[i][j] -= mat[i-1][j-1];
            }
        }

        for(int i = 0;i<n;i++){
            vector<int>temp;
            for(int j = 0;j<m;j++){
                int row = min(n-1,i+k);
                int col = min(m-1,j+k);
                int sum = mat[row][col];
                if(valid(i-k-1,min(j+k,m-1)))sum -= mat[i-k-1][min(j+k,m-1)];
                if(valid(min(i+k,n-1),j-k-1))sum -= mat[min(i+k,n-1)][j-k-1];
                if(valid(i-k-1,j-k-1))sum += mat[i-k-1][j-k-1];
                temp.push_back(sum);
            }
            ans.push_back(temp);
        }
        return ans;
    }
};

