def partition(a, left, right):
    base = a[right]
    i = left -1
    for j in range(left, right):
        if a[j] <= base:
            i += 1
            a[j], a[i] = a[i], a[j]
    a[right], a[i] = a[i], a[right]
    return i

def partition_end(a, left, right):
    base = a[right]
    index = left -1
    for j in range(left, right):
        if a[j] < base:
            index += 1
            a[j], a[index] = a[index], a[j]
    a[right], a[index] = a[index], a[right]

def partition_end_asc(a, right):
    base = a[right]
    index = right -1
    for j in range(right):
        if a[j] > base:
            index -= 1
            a[j], a[index] = a[index], a[j]
        else:
            break
    a[index+1], a[right] = a[right], a[index+1]
    return index+1

def binaryPartition(a, b, left, op):
    while a < b:
        mid = (a+b)//2
        if op(a, mid) == 0:
            b = mid
        elif op(a, mid) == 1:
            a = mid + 1
        elif op(mid, b):
            b = mid
    return a


def left(index): return index * 2 + 1

def right(index): return index * 2 + 2

def parent(index): return index // 2


def merge(arr, lo, mid, hi, key = lambda a: a):
    leftLen, rightLen = mid - lo + 1, hi - mid
    l, r = [], []
    for i in range(0, leftLen):
        l.append(key(arr[lo+i]))
    for i in range(0, rightLen):
        r.append(key(arr[mid+1+i]))
    i, j, k = 0, 0, lo
    while lo <= hi:
        if l[i] <= r[j]:
            arr[k] = l[i]
            i += 1
        else:
            arr[k] = r[j]
            j += 1
        k += 1
        while i < leftLen:
            arr[k] = l[i]
            i += 1
            k += 1
        while j < rightLen:
            arr[k] = r[j]
            j += 1
            k += 1
        return 0

def reverseSection(a, lo, hi):
    next, prev = a[lo+1], a[hi]
    key1, key2 = a[lo], next
    arr[lo] = prev
    arr[hi] = key1
    a[lo+1] = key2

def reverseSegment(pq, a, lo, hi, key = lambda a: a):
    while pq.peek().cost <= hi - lo + 1:
        node = heappop(pq)
