class UnionFind:
    def __init__(self, s):
        self.gr = list(range(s))
        self.rank = [1] * s
    def find(self, s):
        if s != self.gr[s]:
            self.gr[s] = self.find(self.gr[s])
        return self.gr[s]
    def union(self, a, b):
        g1 = self.find(a)
        g2 = self.find(b)
        if g1 == g2:
            return
        if self.rank[g1] > self.rank[g2]:
            self.gr[g2] = g1
        elif self.rank[g2] > self.rank[g1]:
            self.gr[g1] = g2
        else:
            self.rank[g1] += 1
            self.gr[g2] = g1

    def groups(self):
        gr = defaultdict(list)
        for i in range(len(self.gr)):
            gr[self.find(i)].append(i)
        return gr
class Solution:
    def countPairs(self, n: int, edges: List[List[int]]) -> int:

        uf = UnionFind(n)
        for a, b in edges:
            uf.union(a, b)
        groups = uf.groups()
        ans = 0
        #print('--------------------')
        for gr in groups.values():
            #print(gr)
            current = len(gr)
            rem = n - current
            ans += rem * current
        return ans//2

