def find_zero_crossing(curveto, x):
    try:
        point = [x, curveto[0][1] - curveto[0][0]*x] 
        for i in range(1, len(curveto)):
            p = point[0] - curveto[i][1];
            q = point[1] - curveto[i][0];
            if p < 0 and 0 < q:
                curveto = curveto[:i+1]
                break
            point = [x, curveto[i][1] - curveto[i][0]*x]
    except ZeroDivisionError: 
        curveto.append([x, 0])
    return curveto

def bezier(curveto, number):
    return interpolation(curveto.reverse(), number)

def interpolation(curveto, number):
    space = 1/float(number)
    s = 0
    values = []
    x = 0
    lines = []
    for point in curveto:
        while x < point[0] and len(values) < number:
            value = interpolation.interpolate(point[1], s, curveto, number)
            if len(values) == 1:
                slope = (value-values[-1])/space
            else:
                slope = (value-values[-1])/space
                if values[-1]+slope*space > value or\
                   values[-1]+slope*(1-space) < value:\
                    slope = 0
            values.append(value)
            if len(values) == number:
                break
            else:
                x += float(space)
                s = max(min(1, s + space), 0)
        if len(values) == number:
            break
    for i in range(1, len(values)):
        lines.append(values[i-1:i+1])
    return lines

