class Solution:

	def reverseBetween(self, head, m, n):
		l = None
		r = None
		i = 1
		li = []
		curr = head
		while curr:
			li.append(curr.data)
			curr = curr.next
		li[m - 1:n] = li[m - 1:n][::-1]
		head = None
		tail = None
		for i in li:
			newnode = Node(i)
			if head is None:
				head = newnode
				tail = newnode
			else:
				tail.next = newnode
				tail = newnode
		return head

