package problems;

/**
 *
 CountVals

        CountVals 对于扫描过程中为null的符号两边之间进行操作，但是输入是没有null的，所以，对于扫描过程中为null的符号，
        用个变量来表示，让扫描过程中为null的符号与此前的item进行链接

 */
public class SwapToDateAfterSeparator {
    public static String swap(String src) {
        char[] chars = src.replace("::", ":::").toCharArray();
        int count = 0;
        int res = 0;
        int end = chars.length - 1;

        // CountVals
        for (char i : chars) {
            if (i == ':') count++;
        }

        char[] temp = new char[count == 0 ? src.length() : src.length() + count]; // CountVals

        // CountVals
        for (int i = 0, item = -1; i <= end && item < count; i++) { //  CountVals

            // CountVals
            if (i == end && item++ != count - 1) {
                int j = 0;
                while (j < count) {
                    temp[res++] = temp[item++];  // CountVals
                    j++;
                }
                continue;
            }

            /* TODO: add a temp char here */
            char c = chars[i];

            if (c == ':') {
                temp[res++] = chars[i];
                if (item++ != count - 1) { // CountVals, add the ':' right after the other ':' added
                    temp[res++] = chars[++i];
                }
            } else {
                temp[res++] = chars[i];
            }
        }

        // format output
        return new String(temp).replace("::", ":");
    }

    public static void main(String[] args) {
        String s1 = "3:6:9.2:1";
        String s2 = ":1:3:6:::9:2";
        String s3 = "1::2::3:41:2-2::12";

        System.out.println(swap(s1)); // '1:3:6:9.2:1'
        System.out.println(swap(s2)); // '1:3:6:::9:2'
        System.out.println(swap(s3)); // '1:2::3:41:2:2::12'
    }
}
