import sys

def is_subsequence(subsequence, sequence):
    i = 0
    for num in subsequence:
        while i < len(sequence) and sequence[i] != num:
            i += 1
        if i == len(sequence):
            return False
        i += 1
    return True

def find_common_subsequence(a, b):
    i, j = 0, 0
    c = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            c.append(a[i])
            i += 1
            j += 1
        else:
            i += 1
    return c

