#include <bits/stdc++.h>

using namespace std;



#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops,fast-math,O3")

#include <ext/pb_ds/assoc_container.hpp> 

#include <ext/pb_ds/tree_policy.hpp> 

using namespace __gnu_pbds; 

template <class T>

using ordered_set = tree<T, null_type,less<T>, rb_tree_tag,tree_order_statistics_node_update>;



#define ll long long

int tt, tc;



const int N = 1e6 + 9;

vector<vector<int>> queries[N]; // queries[i] are the queries that are on the ith node

// first is l, second is k, third is query index

int query_ans[N], n, q;

vector<int> g[N]; // children

int p[N]; // parent

int a[N];

ordered_set<pair<int, int>> maintain; // first is the number of occurrences, second is the number itself

int occ[N];



void add(int v) {

    maintain.erase({occ[a[v]], a[v]});

    occ[a[v]]++;

    maintain.insert({occ[a[v]], a[v]});

}



void rem(int v) {

    maintain.erase({occ[a[v]], a[v]});

    occ[a[v]]--;

    if (occ[a[v]] == 0) return;

    maintain.insert({occ[a[v]], a[v]});

}



void solve_queries(int v) {

    for (auto& query : queries[v]) {

        int l = query[0], k = query[1], idx = query[2];

        int num_less_than = maintain.order_of_key(make_pair(l, INT_MIN));

        int query_at = num_less_than + k - 1;

        if (query_at >= (int)maintain.size()) {

            query_ans[idx] = -1;

            continue;

        }

        query_ans[idx] = maintain.find_by_order(query_at)->second;

    }

}



void dfs(int v) {

    add(v);

    solve_queries(v);

    for (auto& u : g[v]) dfs(u);

    rem(v);

}



void reset() {

    maintain.clear(); 

    fill(occ, occ + n + 5, 0);

    for (int i = 1; i <= n; i++) g[i].clear();

    fill(query_ans, query_ans + q + 5, 0);

    for (int i = 1; i <= n; i++) queries[i].clear();

}



void solve() {

    cin >> n >> q;

    reset();

    for (int i = 1; i <= n; i++) cin >> a[i];

    for (int i = 2; i <= n; i++) {

        cin >> p[i];

        g[p[i]].emplace_back(i);

    }

    for (int i = 1; i <= q; i++) {

        int v, l, k; cin >> v >> l >> k;

        queries[v].push_back({l, k, i});

    }

    dfs(1);

    for (int i = 1; i <= q; i++) cout << query_ans[i] << " \n"[i == q];

}



int main() {

    ios::sync_with_stdio(0); cin.tie(0);

    tt = 1, tc = 1; cin >> tt;

    while (tt--) solve(), tc++;

}

