			d += 1
		else:
			c += s[i]
	if d % 2 != abs(c) % 2 or d < abs(c):
		return False
	for i in range(k, n):
		if s[i] == '?':
			d += 1
		else:
			c += s[i]
		if s[i - k] == '?':
			d -= 1
		else:
			c -= s[i]
		if d % 2 != abs(c) % 2 or d < abs(c):
			return False
	return True
