import java.util.HashSet;

class Solution {
    public int countDistinctIntegers(int[] arr) {
        HashSet<String> set = new HashSet<>();
        for (int v  :arr) {
            set.add(Integer.toString(v));
            while (v > 0 && v % 10 ==0) {
                v /= 10;
            }
            String rev = new StringBuilder(Integer.toString(v)).reverse().toString();
            set.add(rev);

        }
        return set.size();

    }
}

def solution(arr):
	ans = []
	slope = []
	for i in range(1, len(arr)):
		val = arr[i] - arr[i - 1]
		if val < 0:
			val = -1
		elif val > 0:
			val = 1
		slope.append(val)
	ans.append(arr[0])
	for i in range(1, len(slope)):
		if slope[i - 1] != slope[i]:
			ans.append(arr[i])
	ans.append(arr[-1])
	return ans
