#define FOR(i, a, b) for (remove_cv<remove_reference<decltype(b)>::type>::type i = (a); i < (b); i++)
#define REP(i, n) FOR(i, 0, n)

class Solution {
public:
  int numSquarefulPerms(vector<int>& A) {
    int n = A.size(), nn = 1<<n;
    if (n == 1) {
      long x = round(sqrt(A[0]));
      return x*x == A[0];
    }
    vector<vector<char>> g(n, vector<char>(n));
    REP(i, n)
      REP(j, n)
      if (i != j) {
        long t = A[i]+A[j];
        long x = round(sqrt(t));
        if (x*x == t) g[i][j] = 1;
      }
    vector<vector<int>> p(n, vector<int>(nn)), q(n, vector<int>(nn));
    REP(i, n)
      p[i][1<<i] = 1;
    FOR(i, 1, n) {
      REP(j, n)
        REP(k, nn)
          q[j][k] = 0;
      REP(j, n)
        REP(k, nn)
          if (p[j][k])
            REP(jj, n)
              if (!(k & (1<<jj)) && g[j][jj])
                q[jj][k | 1<<jj] += p[j][k];
      p.swap(q);
    }
    int ans = 0;
    REP(j, n)
      REP(k, nn)
        ans += p[j][k];
    sort(A.begin(),A.end());
    for (int i = 0, j=0; i < n; i = j) {
      for (; j<n && A[i]==A[j]; j++);
      FOR(k,1,j-i+1)
        ans /= k;
    }
    return ans;
  }
};

