def solution(n, a):
    total_seats = sum(a)
    majority = (total_seats + 1) // 2
    coalition_count = 0
    coalition = []

    for i in range(1, n + 1):
        a1 = a[i - 1]
        if a1 > majority:
            continue
        for j in range(i + 1, n + 1):
            a2 = a[j - 1]
            if a1 * 2 <= a2:
                continue
            coalition_seats = a1 + a2
            if coalition_seats > majority:
                coalition.append(i)
                coalition.append(j)
                coalition_count += 1
    return [coalition_count, *coalition] if coalition_count > 0 else [0]

def calculate_time(path):
    visited = set()
    x, y = 0, 0
    total_time = 0
    directions = {'N': (0, 1), 'S': (0, -1), 'W': (-1, 0), 'E': (1, 0)}
    reverse_directions = {(0, 1): 'N', (0, -1): 'S', (-1, 0): 'W', (1, 0): 'E'}

    for direction in path:
        dx, dy = directions[direction]
        new_x, new_y = x + dx, y + dy
        segment = (x, y, new_x, new_y)
        reverse_segment = (new_x, new_y, x, y)

        if segment in visited or reverse_segment in visited:
            total_time += 1
        else:
            total_time += 5
            visited.add(segment)
            visited.add(reverse_segment)

        x, y = new_x, new_y

    return total_time


