private static final int MOD = 1000000007;

    public int countIncreasingPaths(int[][] grid) {
		int[] ans = new int[grid.length];
		for(int i = grid.length-1; i >= 0; i--)
			for(int j = 0; j < grid[i].length; j++)
				ans[j] = helper(i, j, grid);
		int res = 0;
		for(int i : ans)
			res += i;
		return res % MOD;
    }

	private int helper(int i, int j, int[][] grid) {
		if(grid[i][j] == 0)
			return 0;
		if(i == grid.length-1 && j == grid[0].length-1)
			return 1;
		int res = 0;
		int[] arr = new int[] {-1, 0, 1, 0};
		int[] arr2 = new int[] {0, 1, 0, -1};
		for(int k = 0; k < 4; k++)
			if(i + arr[k] < grid.length && j + arr2[k] < grid[0].length && grid[i][j] < grid[i + arr[k]][j + arr2[k]])
				res += helper(i + arr[k], j + arr2[k], grid);
		return res % MOD;
	}
}

