    vector<vector<string>> mostPopularCreator(vector<string>& creators, vector<string>& ids, vector<int>& views) {
      int n = creators.size();
      map<string, ll> p;
      map<string, pair<int, string>> minid;
      rep(i, n) {
        p[creators[i]] += views[i];
        if (minid.count(creators[i])) chmin(minid[creators[i]], pair(-views[i], ids[i]));
        else minid[creators[i]] = pair(-views[i], ids[i]);
      }
      ll mx = -1;
      vector<vector<string>> ans;
      for(auto& [k, v]: p) chmax(mx, v);
      for(auto& [k, v]: p) if (v == mx) ans.push_back(vector<string>{k, minid[k].second});
      return ans;
    }
