class Solution {
    private int[][] dp;
    public int stoneGameII(int[] piles) {
        dp = new int[piles.length][piles.length*100];
        int[] sum = new int[piles.length + 1];
        for (int i = 0; i < piles.length; i++) {
            sum[i + 1] = sum[i] + piles[i];
        }
        int d = helper(piles, sum, 0, 1);
        return (d + sum[piles.length]) / 2;
    }
    private int helper(int[] piles, int[] sum, int i, int M) {
        if (i == piles.length) return 0;
        if (dp[i][M] != 0) return dp[i][M];
        int res = -1000000;
        for (int k = 1; k <= 2 * M && i + k <= piles.length; k++) {
            int n = sum[i + k] - sum[i];

            res = Math.max(res, n - helper(piles, sum, i + k, Math.max(k, M)));
        }
        dp[i][M] = res;
        // System.out.printf("%d %d %d\n", i, M, res);
        return res;
    }
}

