/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
public class Solution {
    public int diameterOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        int diameter = intMaxDepth(root.left) + intMaxDepth(root.right);

        return Math.max(diameter, Math.max(diameterOfBinaryTree(root.left), diameterOfBinaryTree(root.right)));
    }

    private int intMaxDepth(TreeNode node) {
        if (node == null) {
            return 0;
        }

        return 1 + Math.max(intMaxDepth(node.left), intMaxDepth(node.right));
    }
}

