class Solution:

	def zigzag(self, head):
		if head is None or head.next is None:
			return head
		temp = head
		c = 0
		while temp.next != None:
			c += 1
			if c % 2 == 0:
				if temp.data < temp.next.data:
					(temp.data, temp.next.data) = (temp.next.data, temp.data)
			elif temp.data > temp.next.data:
				(temp.data, temp.next.data) = (temp.next.data, temp.data)
			temp = temp.next
		return head

