from collections import deque

def bfs(graph, start, end):
    queue = deque([(start, [])])
    visited = set()
    while queue:
        node, path = queue.popleft()
        if node == end:
            return len(path) + 1
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, path + [neighbor]))
    return -1

def most_popular_friend(friend_groups):
    most_popular = None
    min_notoriety = float('inf')
    for group in friend_groups:
        n = len(group)
        graph = {i: set() for i in range(1, n+1)}
        for i in range(1, n+1):
            for j in group[i]:
                graph[i].add(j)
        for i in range(1, n+1):
            notoriety = 0
            for j in range(1, n+1):
                if i != j:
                    notoriety += bfs(graph, i, j)
            if notoriety < min_notoriety:
                min_notoriety = notoriety
                most_popular = i
            elif notoriety == min_notoriety:
                most_popular = min(most_popular, i)
    return most_popular, min_notoriety / n

