class Solution:
    def maxMatrixSum(self, matrix: List[List[int]]) -> int:
        h, w = len(matrix), len(matrix[0])
        s = [abs(matrix[i][j]) for i in range(h) for j in range(w)]
        n = [1 for i in range(h) for j in range(w) if matrix[i][j] < 0]
        c = Counter(s)
        if sum(n) % 2 == 0 or c[0] > 0:
            return sum(s)

        return sum(s) - (2*min(s))

