def primeFactors(n):
    arr = []
    l = 0
    while n % 2 == 0:
        arr.append(2)
        l += 1
        n = n // 2
    for i in range(3,int(math.sqrt(n))+1,2):
        while n % i== 0:
            arr.append(i)
            l += 1
            n = n // i
    if n > 2:
        arr.append(n)
        l += 1
    return arr
