def primeFactorsSet(n):
    s = set()
    while n % 2 == 0:
        s.add(2)
        n = n // 2
    for i in range(3,int(math.sqrt(n))+1,2):
        while n % i== 0:
            s.add(i)
            n = n // i
    if n > 2:
        s.add(n)
    return s
def sieve(n):
    res=[0 for i in range(n+1)]
    #prime=set([])
    prime=[]
    for i in range(2,n+1):
        if not res[i]:
            #prime.add(i)
            prime.append(i)
            for j in range(1,n//i+1):
                res[i*j]=1
    return prime
def isPrime(n) : # Check Prime Number or not 
    if (n <= 1) : return False
    if (n <= 3) : return True
    if (n % 2 == 0 or n % 3 == 0) : return False
    i = 5
    while(i * i <= n) : 
        if (n % i == 0 or n % (i + 2) == 0) : 
            return False
        i = i + 6
    return True
def countPrimesLessThanN(n):
    seen, ans = [0] * n, 0
    for num in range(2, n):
        if seen[num]: continue
        ans += 1
        seen[num*num:n:num] = [1] * ((n - 1) // num - num + 1)
    return ans
def gcd(x, y):
    return math.gcd(x, y)
def lcm(a,b):
    return (a // gcd(a,b))* b
def isBitSet(n,k):
    # returns the count of numbers up to N having K-th bit set.
    res = (n >> (k + 1)) << k
    if ((n >> k) & 1):
        res += n & ((1 << k) - 1)
    return res
def popcount(x):
    x = x - ((x >> 1) & 0x55555555)
    x = (x & 0x33333333) + ((x >> 2) & 0x33333333)
    x = (x + (x >> 4)) & 0x0f0f0f0f
    x = x + (x >> 8)
    x = x + (x >> 16)
    return x & 0x0000007f
def modular_exponentiation(x, y, p):    #returns (x^y)%p
    res = 1
    x = x % p
    if (x == 0) :
        return 0
    while (y > 0) :
        if ((y & 1) == 1) :
            res = (res * x) % p
        y = y >> 1
        x = (x * x) % p
    return res

def modInverse(A, M):  # returns (1/A) % M
    g = gcd(A, M)
    if (g == 1):
        return modular_exponentiation(A, M - 2, M)

def nCr(n, r, p):    # returns nCr % p
    num = den = 1
    for i in range(r):
        num = (num * (n - i)) % p
        den = (den * (i + 1)) % p
    return (num * pow(den,
            p - 2, p)) % p
def smallestDivisor(n):
    if (n % 2 == 0):
        return 2
    i = 3
    while(i * i <= n):
        if (n % i == 0):
            return i
        i += 2
    return n
def numOfDivisors(n):
