# My Solution
def min_swaps(n, a):
    # list of sorted values
    sorted_a = sorted(a)

    # create a dictionary with the values and their indices in the original array
    a_dict = {}
    for i, val in enumerate(a):
        a_dict[val] = i

    # variable to store the number of swaps
    swaps = 0

    # iterate through the list
    for i in range(n):
        # if the current value is not in the correct position
        if a[i] != sorted_a[n - i - 1]:
            # find the index of the value that should be in this position
            j = a_dict[sorted_a[n - i - 1]]

            # swap the values
            a[i], a[j] = a[j], a[i]

            # update the dictionary
            a_dict[a[i]], a_dict[a[j]] = a_dict[a[j]], a_dict[a[i]]

            # increment the number of swaps
            swaps += 1

    # return the number of swaps
    return swaps

if __name__ == '__main__':
    n = int(input())
    a = list(map(int, input().split()))
    print(min_swaps(n, a))

