I wrote the following solution in Java. I haven't tested it for all the edge cases but I hope it helps!
int minSwaps(int[] arr) {
    int n = arr.length;
    int max = arr[0];
    int min = arr[n-1];
    int swaps = 0;
    boolean isMax = true;
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
            if (isMax) {
                swaps++;
                isMax = false;
            }
        } else if (arr[i] < min) {
            min = arr[i];
            if (!isMax) {
                swaps++;
                isMax = true;
            }
        }
    }
    return swaps;
}

