def minSwaps(arr):
    n = len(arr)
    swaps = 0
    maxIndex = 0
    minIndex = n - 1
    for i in range(1, n):
        if arr[i] > arr[maxIndex]:
            maxIndex = i
        if arr[i] < arr[minIndex]:
            minIndex = i
    if maxIndex == n - 1:
        return swaps
    elif minIndex == 0:
        return swaps + 1
    else:
        arr[maxIndex], arr[minIndex] = arr[minIndex], arr[maxIndex]
        swaps += 1 + minSwaps(arr)
        return swaps

