def find(N):
    digits = list(str(N))
    n = len(digits)

    for i in range(n - 2, -1, -1):
        if digits[i] > digits[i + 1]:
            digits[i] = str(int(digits[i]) - 1)
            for j in range(i + 1, n):
                digits[j] = '9'
            break

    return int(''.join(digits).rstrip('9'))

def min_colors(n, a):
    used = [False] * n
    colors = 0

    for i in range(n):
        if not used[i]:
            colors += 1
            min_val = a[i]
            for j in range(n):
                if a[j] % min_val == 0:
                    used[j] = True

    return colors

