function upperOrLower(word) {
    var lwrCase = []
    var upprCase = []
    var lwrUpprCase = []
    for (var w = 0; w < word.length; ++w) {
        word[w] === word[w].toLowerCase() ? lwrCase.push(word[w]) : upprCase.push(word[w])
    }
    word.replace(/ /, "") === "";
    if (lwrCase.length > upprCase.length) {
        for (var i = 0; i < word.length; ++i) {
            word[i] === word[i].toUpperCase() ? lwrUpprCase.push(word[i]) : lwrUpprCase.push(word[i].toUpperCase())
        }
    }
    if (lwrCase.length <= upprCase.length && word !== word.toUpperCase()) {
        for (var i = 0; i < word.length; ++i) {
            word[i] === word[i].toLowerCase() ? lwrUpprCase.push(word[i]) : lwrUpprCase.push(word[i].toLowerCase())
        }
    }
    return lwrUpprCase.join("");
}

