import sys

def infinite_zoo():
    """Process queries about the infinite zoo graph."""
    q = int(input())
    results = []

    for _ in range(q):
        u, v = map(int, input().split())
        if (u & v) == v:
            results.append("YES")
        else:
            results.append("NO")

    return results

def main():
    """Run the infinite zoo solver and print the results."""
    results = infinite_zoo()
    for result in results:
        print(result)

