def countTriplets(head, X):
    count = 0
    if head is None:
        return count
    current = head
    while current is not None:
        slow = current
        fast = current.next
        while fast is not None:
            sum = slow.data + fast.data
            if sum == X:
                count += 1
                fast = fast.next
                while fast is not None and fast.data == slow.data:
                    fast = fast.next
            else:
                slow = fast
                fast = fast.next
        current = current.next
    return count

