class Solution {
public:
    vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
        vector<pii> vp;
        int n=intervals.size();
        int m=queries.size();
        REP(i,n) {
            vp.push_back({intervals[i][0], -(i+1)});
            vp.push_back({intervals[i][1], (i+1)});
        }
        REP(i,m){
            vp.push_back({queries[i], n+10 + i});
        }
        sort(vp.begin(), vp.end());
        set<pii> id;
        int N=vp.size();
        vector<int> ans(m, -1);
        for(int i=0,j=0;i<N;i=j) {
            for(j=i;j<N&&vp[i].first==vp[j].first;j++);
            for(int k=i;k<j;k++) {
                int X=vp[k].second;
                if (X<0) {
                    int y=-X-1;
                    id.insert({intervals[y][1]-intervals[y][0] ,y});
                }
            }
            for(int k=i;k<j;k++) {
                int X=vp[k].second;
                if (X>n+5) {
                    if(!id.empty()) ans[X-(n+10)]=id.begin()->first+1;
                }
            }
            for(int k=i;k<j;k++) {
                int X=vp[k].second;
                if (X>0 && X<=n+5) {
                    int y=X-1;
                    id.erase({intervals[y][1]-intervals[y][0] ,y});
                }
            }
        }
        return ans;
    }
};

