from collections import Counter

def solve(S):
	S = S[::-1]
	C = Counter(S)
	N = {k: C[k] / 2 for k in C}
	(i, sol) = (0, [])
	while len(sol) < len(S) // 2:
		j = -1
		while True:
			if N[S[i]] and (j < 0 or S[i] < S[j]):
				j = i
			C[S[i]] -= 1
			if C[S[i]] < N[S[i]]:
				break
			i += 1
		for k in range(j + 1, i + 1):
			C[S[k]] += 1
		N[S[j]] -= 1
		sol.append(S[j])
		i = j + 1
	return ''.join(sol)
