class Solution:

	def largest1BorderedSquare(self, grid: List[List[int]]) -> int:
		m = len(grid)
		n = len(grid[0])
		dpdown = [[0] * n for i in range(m)]
		dpright = [[0] * n for i in range(m)]
		for i in range(m):
			cur = 0
			for j in range(n - 1, -1, -1):
				if grid[i][j] == 1:
					cur += 1
					dpright[i][j] = cur
				else:
					cur = 0
		for j in range(n):
			cur = 0
			for i in range(m - 1, -1, -1):
				if grid[i][j] == 1:
					cur += 1
					dpdown[i][j] = cur
				else:
					cur = 0
		res = 0
		for i in range(m):
			for j in range(n):
				for k in range(min(dpright[i][j], dpdown[i][j])):
					if dpright[i + k][j] > k and dpdown[i][j + k] > k:
						res = max(k + 1, res)
		return res ** 2

N = int(input())
points = [list(map(int, input().split())) for i in range(N)]

def dist(cx, cy, nx, ny):
	return ((cx - nx) ** 2 + (cy - ny) ** 2) ** 0.5

def circumcenter(x1, x2, x3, y1, y2, y3):
	a2 = (x2 - x3) ** 2 + (y2 - y3) ** 2
	b2 = (x1 - x3) ** 2 + (y1 - y3) ** 2
	c2 = (x2 - x1) ** 2 + (y2 - y1) ** 2
	area = ((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1)) / 2
	if area == 0:
		d1 = dist(x1, y1, x2, y2)
		d2 = dist(x1, y1, x3, y3)
		d3 = dist(x2, y2, x3, y3)
		if max(d1, d2, d3) == d1:
			return ((x1 + x2) / 2, (y1 + y2) / 2)
		elif max(d1, d2, d3) == d2:
			return ((x1 + x3) / 2, (y1 + y3) / 2)
		else:
			return ((x2 + x3) / 2, (y2 + y3) / 2)
	x = (a2 * (b2 + c2 - a2) * x1 + b2 * (c2 + a2 - b2) * x2 + c2 * (a2 + b2 - c2) * x3) / (16 * area * area)
	y = (a2 * (b2 + c2 - a2) * y1 + b2 * (c2 + a2 - b2) * y2 + c2 * (a2 + b2 - c2) * y3) / (16 * area * area)
	return (x, y)
ans = float('inf')
for i in range(N):
