			(x3, y3) = points[k]
			(cx, cy) = circumcenter(x1, x2, x3, y1, y2, y3)
			tmp_ans = 0
			for (nx, ny) in points:
				tmp_ans = max(tmp_ans, dist(cx, cy, nx, ny))
			ans = min(ans, tmp_ans)
print(ans)

import os
import sys
