def getVol(self, A: int, B: int) -> int:
    if A == 0 or B == 0:
      return 0
    a = (A*B)//2
    if B>A:
      a = a- (A-4)*(B-1)//8 
      b = (A-1)*(B-4)//8
      c = (A-2)*(B-3)//8
    else:
      b = (A-1)*(B-4)//8 
      c = (A-2)*(B-3)//8
      a = (A*B)-b-c
    return a

