class Solution:
    # Approach: To maximize the box volume, the length and width of the box
    # must be prime. So we use the parametrization of a (length, width)
    # and determine which dimensions are bigger. Depending on that we have
    # to keep a number of the material as a foundation. We may append
    # the area of the remaining base.
    def getVol(self, A: int, B: int) -> int:
        length = 0
        if A<B:
            length, width = B, A
        else:
            length, width = A, B

        l = set([length])
        w = set([width])

        a = A * B
        x = 0

        while True:
            # We remove todre edges from the l,w
            if length%2 == 0:
                if length >= width:
                    length = length / 2
                else:
                    length = length + width
                w.discard(width)
            if width%2 == 0:
                if width >= length:
                    width = width / 2
                else:
                    width = width + length
                l.discard(length)
            x += 1

            for e in range(max(l.pop(), width.pop())):
                a = a - 2
                x = a / 2
            if len(l) == 0 or len(w) == 0:
                break

        X = a - length * width/2

        return  x + int(X)

s = Solution()
