class Solution {
    public int maximizeSquareArea(int m, int n, int[] h, int[] v) {
        Set<Integer> st = new HashSet<>();
        st.add(m-1);
        for(int i= 0 ; i<h.length; ++i) {

            for(int j=i-1;j>=0;--j) {
                int d = Math.abs(h[i]-  h[j]);
                st.add(d);
            }
            st.add(h[i]-1);
            st.add(m-h[i]);
        }
        long mod = 1000000007;

        long r = -1;

        for(int i= 0 ; i<v.length; ++i) {

            for(int j=i-1;j>=0;--j) {
                int d = Math.abs(v[i]-  v[j]);
                if(st.contains(d)) {
                    r =Math.max(r, d);
                }
            }
            if(st.contains(v[i]-1)) {
                r = Math.max(r, v[i]-1);
            }
            if(st.contains(n-v[i])) {
                r = Math.max(r, n-v[i]);
            }
        }
        if(st.contains(n-1)){
            r = Math.max(r, n-1);
        }
        if(r==-1) {
            return -1;
        }
        long p =(r*r)%mod;
        return (int)p;
    }
}

