from typing import List

def minimum_shots(n: int, r: int, x: List[int]) -> int:
    x.sort()
    shots = 0
    i = 0
    while i < n:
        j = i
        while j < n and x[j] - x[i] <= 2*r:
            j += 1
        shots += 1
        if j < n and x[j] - x[j-1] > 2*r:
            i = j
        else:
            i = j - 1
    return shots

