class UnionFind:

	def __init__(self):
		self.leaders = defaultdict(lambda : None)

	def find(self, x):
		l = self.leaders[x]
		if l is not None:
			while self.leaders[l] is not None:
				l = self.leaders[l]
			self.leaders[x] = l
			return l
		return x

	def union(self, x, y):
		(lx, ly) = (self.find(x), self.find(y))
		if lx != ly:
			self.leaders[lx] = ly

	def get_groups(self):
		groups = defaultdict(set)
		for x in self.leaders:
			groups[self.find(x)].add(x)
		return groups
