def numSubmat(mat):
    m, n = len(mat), len(mat[0])
    dp = [[0]*n for _ in range(m)]
    res = 0

    for i in range(m):
        for j in range(n):
            if mat[i][j]:
                width = dp[i][j] = dp[i][j-1] + 1 if j else 1
                for k in range(i, -1, -1):
                    width = min(width, dp[k][j])
                    res += width
    return res

