def solve(n, b, a, s):
    if b == 0:
        return 0
    if a == 0:
        return sum(s)
    if n == 1:
        return s[0]
    if s[0] == 0:
        return solve(n - 1, b - 1, a, s[1:])
    return max(solve(n - 1, b - 1, a, s[1:]), solve(n - 1, b, a - 1, s[1:])) + 1

