def reorder_sequences(A, B):
    A_dict = {value: index for index, value in enumerate(A)}
    B_sorted = sorted(B, key=lambda x: A_dict[x])

    if len(B_sorted) != len(set(B_sorted)):
        return 'No'

    return 'Yes', ' '.join(map(str, B_sorted))


