class Solution {
    public int minSideJumps(int[] obstacles) {
        int n = obstacles.length;
        int[] lanes = new int[3];
        int[] newLanes = new int[3];

        lanes[0] = lanes[2] = 1;

        for (int i = 1; i < n; i++) {
            int obsLane = obstacles[i] - 1;

            for (int j = 0; j < 3; j++) {
                newLanes[j] = n;
                if (j != obsLane) {
                    newLanes[j] = Math.min(newLanes[j], lanes[j]);

                    for (int k = 0; k < 3; k++) {
                        if (k != j && obsLane != k) {
                            newLanes[j] = Math.min(newLanes[j], 1 + lanes[k]);
                        }
                    }
                }
            }

            lanes[0] = newLanes[0];
            lanes[1] = newLanes[1];
            lanes[2] = newLanes[2];
        }

        return Math.min(lanes[0], Math.min(lanes[1], lanes[2]));
    }
}

