def solve(n, p):

    if n == 1:
        return 1

    adj = [[] for _ in range(n+1)]
    for i in range(n):
        for j in range(i+1, n):
            if p[i] > p[j]:
                adj[p[i]].append(p[j])
                adj[p[j]].append(p[i])

    visited = [False] * (n+1)
    ans = 0
    for i in range(1, n+1):
        if visited[i]:
            continue
        stack = [i]
        while stack:
            curr = stack.pop()
            if visited[curr]:
                continue
            visited[curr] = True
            for nex in adj[curr]:
                stack.append(nex)
        ans += 1

    return ans

