        elif last_activity == 'gym' and day == 3:
            last_activity = 'contest'
        elif last_activity is None and day == 1:
            last_activity = 'contest'
        elif last_activity is None and day == 2:
            last_activity = 'gym'
        elif last_activity is None and day == 3:
            last_activity = 'contest'

    return rest_days

