    int left = 1, right = m;
    for (int i = 1; i <= n; i++) {
        int l = left, r = right;
        while (l < r) {
            int mid = l + r >> 1;
            int x = query(i, mid);
            int y = query(i, mid + 1);
            update(x);
            update(y);
            if (x > y) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        left = max(left, l);
        update(query(i, left));
    }
    printf("! %d\n", ans);
    fflush(stdout);
    return 0;
}

