#include <iostream>
#include <set>
using namespace std;

class Solution {
public:
    int dfs(TreeNode* r, int d, int dis) {
        int c1=0, c2=0;
        if(r==NULL)
            return 0;
        if(r->left==NULL && r->right==NULL) {
            if(dis>=d)
                c1=1;
            return c1;
        }
        int c=0;
        if(c1==0)
            c+=dfs(r->left, d+1, dis);
        if(c1==0)
            c+=dfs(r->right, d+1, dis);

        if(dis>=d)
            c1=c/2;
        if(dis>=d+1)
            c2=c-(c/2);
        return c1+c2;
    }
    int countPairs(TreeNode* root, int distance) {
        // Code here
        return dfs(root, 0, distance);
    }
};

