def maxNumberOfAlloys(n, k, budget, composition, stock, cost):
    def can_produce(mid, comp):
        total_cost = 0
        for i in range(n):
            needed = mid * comp[i]
            if stock[i] < needed:
                total_cost += (needed - stock[i]) * cost[i]
        return total_cost <= budget

    max_alloys = 0
    for comp in composition:
        left, right = 0, 10**8
        while left <= right:
            mid = (left + right) // 2
            if can_produce(mid, comp):
                max_alloys = max(max_alloys, mid)
                left = mid + 1
            else:
                right = mid - 1
    return max_alloys

