        //         curCnt += Math.Abs(num - v);
        //     }
        //     minCnt = Math.Min(curCnt, minCnt);
        // }
        // return minCnt;

        // Sort by ascending then find the number of moves to get to that target number
        Array.Sort(nums);
        int cnt = 0;
        int curNum = nums[0];
        int curCnt = 0;
        for (int i = 1; i < nums.Length; i++)
        {
            curCnt += nums[i] - curNum;
            cnt += curCnt;
            curNum = nums[i];
        }
        return cnt;

    }

    static int MinimumMovesToMakeAtLeastOneArraySorted_SortBy_CountGroups(int[] nums)
    {
        Array.Sort(nums);
        int cnt = 0;
        int curNum = nums[0];
        int curCnt = 0;
        int curGroupStart = 0;
        for (int i = 1; i < nums.Length; i++)
        {
            if (nums[i] != curNum)
            {
                for (int j = curGroupStart; j < i; j++)
                {
                    curCnt += nums[i] - nums[j];
                }
                cnt += curCnt;
                curNum = nums[i];
                curCnt = 0;
                curGroupStart = i;
            }
        }
        return cnt;

    }

    static int MinimumMovesToMakeAtLeastOneArraySorted_SortBy_CountGroups_1(int[] nums)
    {
        Array.Sort(nums);
        int cnt = 0;
        int curNum = -1;
        for (int i = 0; i < nums.Length; i++)
        {
            if (nums[i] != curNum)
            {
                // calc the numbers in cur group
                if (curNum >= 0)
                {
                    cnt += Math.Abs(curNum - nums[i]) * (i - curGroupStart);
                }
                curNum = nums[i];
                curGroupStart = i;
            }
        }
        return cnt;

    }

}

public class Solution
{
    public int MinimumMovesToMakeAtLeastOneArraySorted(int[] nums)
    {

        return Main.MinimumMovesToMakeAtLeastOneArraySorted(nums);

    }
