def can_flow(pipes):
    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    visited = [[False] * len(pipes[0]) for _ in range(2)]

    def dfs(i, j, di, dj):
        if 0 <= i < len(pipes) and 0 <= j < len(pipes[0]) and not visited[i][j]:
            visited[i][j] = True
            if i == len(pipes) - 1 and j == len(pipes[0]) - 1:
                return True
            for d in directions:
                ni, nj = i + d[0] * 2, j + d[1] * 2
                if 0 <= ni < len(pipes) and 0 <= nj < len(pipes[0]) and not visited[ni][nj]:
                    if dfs(ni, nj, d[0], d[1]):
                        return True
        return False

    for i in range(len(pipes)):
        for j in range(len(pipes[i])):
            if dfs(0, j, 1, 0):
                return True

    return False

