class Solution:

	def FindMaxSum(self, arr, n):
		p1 = arr[0]
		p2 = 0
		for i in range(1, n):
			take = arr[i]
			if i > 1:
				take += p2
			noTake = p1 + 0
			p2 = p1
			p1 = max(take, noTake)
		return p1

	def rec(self, i, arr, dp):
		if i < 0:
			return 0
		if i == 0:
			return arr[0]
		take = arr[i]
		if dp[i - 2] != -1:
			take += dp[i - 2]
		else:
			val = self.rec(i - 2, arr, dp)
			dp[i - 2] = val
			take += val
		noTake = 0
		if dp[i - 1] != -1:
			noTake += dp[i - 1]
		else:
			val = self.rec(i - 1, arr, dp)
			dp[i - 1] = val
			noTake += val
		return max(take, noTake)

