void solve()

{

    ll n;

    read(n);

    vll c;

    read(c,n);

    if(n<3){

        if(is_sorted(all(c))){

            wrtline(yes);

        }

        else{

            wrtline(no);

        }

        return;

    }

    set<pll> pos;

    vll f(n+1,0);

    forn(i,n){

        pos.ins({c[i],i});

        f[c[i]]++;

        if(f[c[i]]>1){

            wrtline(yes);

            return;

        }

    }

    ll i=0;

    while(i<n-2){

        auto it=*pos.begin();

        if(i<n-2 and it.scd==i){

            pos.erase(pos.begin());

            i++;

            continue;

        }

        if(i>=n-2){

            break;

        }

        if(it.scd==n-1){

            ll temp=c[n-1];

            pos.erase({c[n-1],n-1});

            pos.ins({c[n-1],n-3});

            c[n-1]=c[n-2];

            pos.erase({c[n-2],n-2});

            pos.ins({c[n-2],n-1});

            c[n-2]=c[n-3];

            pos.erase({c[n-3],n-3});

            pos.ins({c[n-3],n-2});

            c[n-3]=temp;

        }

        it=*pos.begin();

        if(it.scd==i){

            pos.erase(pos.begin());

            i++;

            continue;

        }

        ll tempPos=it.scd,tempVal=it.fst;

        pos.erase({c[i],i});

        pos.ins({tempVal,i});

        swap(tempVal,c[i]);

        pos.erase({c[n-1],n-1});

        pos.ins({tempVal,n-1});

        swap(tempVal,c[n-1]);

        pos.erase({c[tempPos],tempPos});

        pos.ins({tempVal,tempPos});

        swap(c[tempPos],tempVal);

        i++;

        // debug(pos)

        // debug(c)

        pos.erase(pos.begin());

    }   

    // debug(c)

    if(is_sorted(all(c))){

        wrtline(yes);

    }

    else{

        vll temp=c;

        reverse(temp.end()-3,temp.end()-2);

        reverse(temp.end()-2,temp.end());

        reverse(temp.end()-3,temp.end());

        // debug(temp)

        if(is_sorted(all(temp))){

            wrtline(yes);

            return;

        }

        temp=c;

        reverse(temp.end()-3,temp.end()-1);

        reverse(temp.end()-1,temp.end());

        reverse(temp.end()-3,temp.end());

        // debug(temp)

        if(is_sorted(all(temp))){

            wrtline(yes);

            return;

        }

        wrtline(no);

    }

}

