def repeatedStringMatch(A, B):
    if len(B) <= len(A):
        if B in A:
            return 1
        A += A
        if B in A:
            return 2
        return -1
    n = len(A)
    i = 1
    while len(A) * i <= len(B):
        if B in A * i:
            return i
        i += 1
    return -1

