   int maxStarSum(vector<int>& vals, vector<vector<int>>& edges, int k) {
    int maxSum = 0;
    int n = vals.size();
    // 法一，遍历每一次进行动规
    // dp[i] 表示 以边i结尾的最大起尔数 = dp[i - 1] + vals[edges[i]]
    // 对于边i，如果这条边和前节点值较大也是可能的结果，如果这条边和前i个节点值较小，也是可能的结果
