MOD = 10**9 + 7

def max_ways(N, K):
    # Initialize the memoization table
    memo = [[[0] * (K+1) for _ in range(N+1)] for _ in range(N+1)]

    for i in range(1, N+1):
        for j in range(1, K+1):
            for k in range(i):
                memo[i][j] = (memo[i][j] + memo[k][j-1] * ((K-j+1)**(i-k-1))) % MOD
            memo[i][j] = (memo[i][j] + 1) % MOD  # Include case where all zombies take the same color

    return memo[N][K]

def solve_subtask_3():
    T = int(input())
    for _ in range(T):
        N, K = map(int, input().split())
        print(max_ways(N, K))

