def max_num(a, coded):
	result = [el for el in a]
	for (index, el) in enumerate(a):
		if coded[int(el) - 1] > el:
			result[index] = coded[int(el) - 1]
			start_index = index + 1
			while start_index < len(a):
				if a[start_index] > coded[int(a[start_index]) - 1]:
					break
				result[start_index] = coded[int(a[start_index]) - 1]
				start_index += 1
			break
	return ''.join(result)
