def min_max_digit(x):
    x_str = str(x)
    digits = [int(d) for d in x_str]
    return min(digits), max(digits)


def compute_next(a, min_digit, max_digit):
    return a + min_digit * max_digit


def calculate_a_k(a1, k):
    a = a1
    for _ in range(k):
        min_digit, max_digit = min_max_digit(a)
        a = compute_next(a, min_digit, max_digit)
    return a


