def shortestPalindrome(x):
    for i in range(len(x)):
        if x[i:len(x) - 1] == x[i - 1::-1]:
            return i
        if x[i:len(x) - 1] == x[i::-1]:
            return 0


def solution(s):
    if s[::-1] == s:
        return 'DRAW'

    pos = shortestPalindrome(s)

    moves = len(s) + len(s[pos:])
    blindMove = min(moves, moves + 1 if 0 == pos else moves - 1)

    coins = (blindMove - moves) // 2

    return 'BOB' if coins % 2 == 1 else 'ALICE'


