class Solution {
    public boolean isPossible(int[] target) {
        int n = target.length;
        if (n == 1) {
            return true;
        }
        int[] temp = new int[n];
        for (int i = 0; i < n; i++) {
            temp[i] = target[i];
        }
        Arrays.sort(temp);
        for (int i = 0; i < n; i++) {
            int need = target[i];
            if (need > temp[n - 1]) {
                return false;
            }
            if (need > 0) {
                int start = n - 1;
                while (start > i) {
                    if (temp[start] >= need) {
                        temp[start] -= need;
                        temp[i] -= need;
                        break;
                    }
                    need -= temp[start];
                    temp[i] -= temp[start];
                    start--;
                }
                if (start == i && need > 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

