    def maximumDifference(self, nums: List[int]) -> int:
        minNum = 10**9 + 1
        maxDiff = 0
        for n in nums:
            maxDiff = max(maxDiff, n - minNum)
            minNum = min(minNum, n)
        if maxDiff == 0:
            return -1
        return maxDiff

