#     例如：[3,5,1,2,3,5,2]
#         差异最大的子数组是[3,5]和[5,2]，返回5 - 2 = 3
#
# 思路：数组之和减去子数组之和
#
# 利用双指针方法，从后往前不断累加，不过要先进行逆排序，使每次的更新后求和都是正确结果，才不会受到小于差值而提前更新的情况。

def getSubArrLenghtDifference(arr):
    arr.sort(reverse=True)  # 逆排序
    result = 0
    lastValue = arr[0]  # 双指针，最左和最右
    left = 0
    right = len(arr) - 1

    while left < right:
        if lastValue == 0:
            lastValue = arr[left]
            lastValue -= arr[right]
            left += 1
            right -= 1
        elif lastValue < 0:
            lastValue -= arr[right]
            right -= 1
        elif lastValue > 0:
            lastValue -= arr[left]
            left += 1
        else:  # 相等的情况
            result = right - left - 1  # 两子数组的长度差
            break

    return result

