import sys

def solve(n, a):
    even = [x for x in a if x % 2 == 0]
    odd = [x for x in a if x % 2 == 1]
    e, o = 0, 0
    for i, x in enumerate(a):
        if i % 2 == 0:
            if x % 2 == 1:
                e += 1
        else:
            if x % 2 == 0:
                o += 1
    if len(even) < e or len(odd) < o:
        return -1
    return max(e, o)

