class Solution:

	def lenOfLongSubarr(self, a, n, k):
		ans = 0
		total = 0
		di = {}
		for i in range(n):
			total += a[i]
			if total not in di:
				di[total] = i
			if total == k:
				ans = max(ans, i + 1)
			elif total - k in di:
				ans = max(ans, i - di[total - k])
		return ans

