import chess
import chess.engine
from collections import defaultdict
import sys
import json

# Utility function to evaluate board positions
def evaluate_board(board, depth):
    if depth == 0 or board.is_game_over():
        if board.result() == '*':
            return 0  # End of evaluation at the beginning of the game
        else:
            if board.result() == '1-0':  # White wins
                return 1000000 - board.bishops_count()
            else:
                return board.bishops_count()
    # Standard evaluation function to be extended...
    return 1000 + board.pawns_count() - board.knights_count()  # Successor evaluation

# Recursive minimax function with alpha-beta pruning
def minimax(board, depth, alpha, beta, maximizing_player):
    if depth == 0 or board.is_game_over():
        return evaluate_board(board, depth)

    if maximizing_player:
        max_eval = -float('inf')
        for move in board.legal_moves:
            board.push(move)
            eval = minimax(board, depth-1, alpha, beta, False)
            board.pop()
            max_eval = max(max_eval, eval)
            alpha = max(alpha, eval)
            if beta <= alpha:
                break
        return max_eval
    else:
        min_eval = float('inf')
        for move in board.legal_moves:
            board.push(move)
            eval = minimax(board, depth-1, alpha, beta, True)
            board.pop()
            min_eval = min(min_eval, eval)
            beta = min(beta, eval)
            if beta <= alpha:
                break
        return min_eval

# Given a board position and a start depth, outputs a list of top 10 moves
def recommend_move(board, depth):
    best_moves = []
    best_eval = -float('inf')
    for move in board.legal_moves:
        board.push(move)
        eval = minimax(board, depth-1, -float('inf'), float('inf'), False)
        board.pop()
        if eval > best_eval:
            best_moves = [move]
            best_eval = eval
        elif eval == best_eval:
            best_moves.append(move)
    return best_moves

def main():
    try:
        board_fen = input()
        board = chess.Board(board_fen)
        depth = int(input())
        result, best_moves = board.fen(), recommend_move(board, depth)
        print(json.dumps({'result': result, 'moves': [chess.Move.from_uci(str(move.uci()))._uci() for move in best_moves][:10]}))
    except ValueError:
        print('Invalid input')

if __name__ == '__main__':
    main()

