public:
    long long minimumReplacement(string s) {
        int n = s.length();
        vector<long long> dp(n + 1);
        for (int i = n - 1; i >= 0; i--) {
            dp[i] = 1LL * (n - i) * (n - i);
            for (int j = i + 1; j < n; j++) {
                if (s[i] <= s[j]) break;
                long long cost = (s[i] - 1) / s[j];
                dp[i] = min(dp[i], dp[j + 1] + cost);
            }
        }
        return dp[0];
    }
