def solve(n, l, r, s):
    if s > (n * (n+1)) // 2 or s < n * l:
        return [-1]
    lst = list(range(1, n+1))
    if l == 1:
        diff = s - n
        lst[0], lst[r-1] = lst[r-1]+diff, lst[0]
    else:
        diff = s - sum(lst[:r])
        if (r-l+1)*l <= s and s <= (n*(n+1))//2:
            lst[l-1:r] = lst[l-1:r][::-1]
            lst[l] += diff
        else:
            return [-1]
    return lst

