class Solution {
public:
    bool hasAlternatingBits(int n) {
        int pre;
        bool result = true;

        pre = 1 - n & 1;
        n >>= 1;
        while(n && result) {
            if((n & 1) == pre) pre = 1 - pre;
            else result = false;
            n >>= 1;
        }

        return result;
    }
};

