def solution(N, a, x, f):
    if sum(a) < f:
        return -1
    if x <= f:
        return 0
    a = sorted(a)
    a.reverse()
    count = 0
    for i in range(N):
        if a[i] > x:
            count += math.ceil((a[i]-x)/f)
    return count*f

