from math import sqrt, floor

def factors(n):
	until = floor(sqrt(n))
	result = 2
	if n == 1:
		return 1
	i = 2
	while i <= until:
		if n % i == 0:
			if i * i == n:
				result += 1
			else:
				result += 2
		i += 1
	return result
