This solution iterates through each cell in the matrix except for the borders (because a cross requires four cells to form). For each cell that is not a '.', it checks all the required cells for a cross pattern. If these conditions are met, it increments the counter. Finally, it prints the counter which holds the total number of crosses.

class Solution {
    public int countPartitions(int[] nums, int k) {
        int count = 0;
        int mod = 1_000_000_007;

        List<Integer> list = new ArrayList<>();

        int otherSum = 0;

        long totalSum = 0;

        for (int num : nums){
            totalSum += num;
            if (num >= k){
                count++;
                continue;
            }

            list.add(num);
            otherSum += num;
        }

        int total = 1;

        for (int num : nums){
            total *= 2;
            total %= mod;
        }

        int [] counts = new int [k];
        int [] prev = new int [k];
        prev[0] = 1;
        counts[0] = 1;

        int val;

        int cTotal = 0;

        for (int num : list){
            counts = new int [k];

            for (int i = 0; i < k; ++i){
                counts[i] = prev[i];
            }

            for (int i = 0; i < k; ++i){
                val = i + num;
                if (val >= k) break;

                counts[val] += prev[i];
                counts[val] %= mod;
            }

            //counts[num]++;
            //counts[num] %= mod;

            prev = counts;
        }

        //System.out.println(Arrays.toString(counts) + " " + total);

        for (int i = 0; i < k; ++i){


            val = counts[i];
            cTotal += val;
            val *= (totalSum - i) < k ? 1 : 2;
            val %= mod;
            total += mod - val;
            total %= mod;
        }

        //System.out.println(cTotal);
        return total;
    }
}

