class Solution {
    boolean isBeautiful(String s, int l, int r) {
        boolean[] lower = new boolean[26], upper = new boolean[26];
        for (int i = l; i < r; ++i) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                lower[ch - 'a'] = true;
            } else {
                upper[ch - 'A'] = true;
            }
        }
        for (int i = 0; i < 26; ++i) {
            if ((lower[i] ^ upper[i])) return false;
        }
        return true;
    }

    public String longestNiceSubstring(String s) {
        int l = 0, r = 0, ans = 0;
        for (int i = 0; i < s.length(); ++i) {
            for (int j = i; j < s.length(); ++j) {
                if (isBeautiful(s, i, j + 1) && j - i + 1 > ans) {
                    ans = j - i + 1;
                    l = i;
                    r = j;
                }
            }
        }
        if(ans==0) return "";
        return s.substring(l, r+1);
    }

    public static void main(String[] args) {
        String s = "c";
        new Solution().
                longestNiceSubstring(s);
    }
}

