def solve(n, a):
    total = 0
    for i in range(n):
        if a[i] == 1:
            break
        total += a[i]
    j = i + 1
    while j < n and a[j] != 1:
        j += 1
    if j < n:
        total += max(0, j - i - 1)
    return total

