You can use a dictionary to keep track of the number of times each character appears in the string. Then, you can iterate through the string and check if the number of times each character appears in the string is equal to the number of times it appears in the target string.
Here's an example implementation:
def can_transform(s, r):
    char_counts = {}
    for char in s:
        if char not in char_counts:
            char_counts[char] = 0
        char_counts[char] += 1
    for char in r:
        if char not in char_counts or char_counts[char] == 0:
            return False
        char_counts[char] -= 1
    return True

print(can_transform("11000", "01001")) # True
print(can_transform("110", "001")) # False

