using namespace std;
string reverse(string& s, int left, int right){
   while (left < right){
       char temp = s[left];
       s[left++] = s[right];
       s[right--] = temp;
   }
   return s;
}
bool isEmpty(string& s){
   if (s.size() == 0)
       return true;
   return false;
}
bool isOpen(string& s){
   if (s[0] == '(')
      return true;
   return false;
}
bool isClosed(string& s){
   if (s[s.size() - 1] == ')')
      return true;
   return false;
}
string solve(string s){
   stack<pair<int, int>> open;
   string result = "";
   int index = 0;
   while (index < s.size()) {
      if (!isEmpty(s) || isOpen(s[index])){
         open.push({index, s[index]});
      }
      else{
         if (!open.empty()){
            int index2 = open.top().first;
            int c = open.top().second;
            open.pop();
            result += c;
            result += reverse(s, index2 + 1, index);
         }else{
             result += s[index];
         }
      }
      index++;
   }
   string result_final = result;
   int index = 0;
   string final = "";
   bool flag = false;
   for (index = 0; index < result_final.size(); index++){
      if (!isOpen(result_final[index]) && !isClosed(result_final[index])){
         if (result_final[index] == ")" || result_final[index] == "[" || result_final[index] == "{" || result_final[index] == "}"){
             result_final = reverse(result_final, index + 1, index + 2);
         }else{
             flag = true;
         }
         if (flag){
             if (index != 0 && result_final[index] == ','){
                 index++;
             }
         }else{
            final += result_final[index];
         }
      }
   }
   return final;
}
int main(){
    string s = "(abcd)(u(love)i)";
    cout << solve(s);
}

