(N, Q) = list(map(int, input().split()))

class RUQ:

	def __init__(self, N, default=None):
		self.N0 = 2 ** (N - 1).bit_length()
		self.data = [(-1, N - 1)] * (2 * self.N0)
		self.INF = (-1, default)

	def update(self, l, r, v):
		L = l + self.N0
		R = r + self.N0
		while L < R:
			if R & 1:
				R -= 1
				self.data[R - 1] = v
			if L & 1:
				self.data[L - 1] = v
				L += 1
			L >>= 1
			R >>= 1

	def _query(self, k):
		k += self.N0 - 1
		s = self.INF
		while k >= 0:
			if self.data[k]:
				s = max(s, self.data[k])
			k = (k - 1) // 2
		return s

	def query(self, k):
		return self._query(k)[1]
TATE = RUQ(N - 1, N - 2)
YOKO = RUQ(N - 1, N - 2)
hidari = N
ue = N
ans = (N - 2) ** 2
for t in range(Q):
	(c, x) = list(map(int, input().split()))
	if c == 1:
		ans -= TATE.query(x - 2)
		if x < hidari:
			hidari = x
			YOKO.update(0, TATE.query(x - 2), (t, x - 2))
	else:
		ans -= YOKO.query(x - 2)
		if x < ue:
			ue = x
			TATE.update(0, YOKO.query(x - 2), (t, x - 2))
print(ans)

