from collections import deque
def longest_increasing_subsequence(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    dp[0][0] = 1

    if n <= 1:
        return 1

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i][j] = dp[j][i - 1] + 1

    return max(map(max, dp))


