# for zero of is imminent, determine maximum cut
def max_cut(arr):
    arr = arr[:-1] + arr[::-1]
    n = len(arr)
    dp = deque((0, n))
    ans = []
    while dp and len(ans) < 3 or len(ans) == 1:
        cut, rp = dp.popleft()
        op = 0

        if rp == 0:
            op = cut
        elif arr[rp - 1] - arr[cut - 1] < 0:
            left = rp - 1
            right = cut
        else:
            left, right = cut - 1, rp

        while left and right - left >= 1:
            if (op and dp[op][0] - cut >= dp[op - 1][0]) or (not op and dp[op][0] - cut >= dp[op][1]):
                dp.append((dp[op][0], rp))
                op = op - 1
            left -= 1
            right += 1

        dp.append((dp[op][0] + rp, rp))

    ans.append(dp[0][1])
    return ans
