using namespace std;
// Sieve of Eratosthenes
void printAllPrimes(int N)
{
    BitArray<uint64_t> b(N - 1, 1);
    b[0] = 0; // must mark 0 and 1 as not prime

    for (auto i = 2; i * i <= N; ++i)
    {
        if (b[i - 1])
        {
            for (auto j = i * i; j <= N; j += i) 
            {
                if (b[j - 1]) 
                {
                    b[j - 1] = 0;
                }
            }
        }
    }

    int sum = 0;
    for (int i = 0; i < N; ++i) {
        if (b[i]) { cout << i + 1 << " "; sum += i+1;}
    }
    cout << endl;

    cout << sum << endl;
}
int main() {
    int N;
    cin >> N;
    printAllPrimes(N);
    return 0;
}

