def kosaraju(V, adj):
    transgraph={}
    graph={}
    transgraph.update({i:set() for i in range(V)})
    graph.update({i:set() for i in range(V)})
    for i in range(V):
        graph[i]=adj[i]
        for j in range(V):
            if adj[i][j]:transgraph[j].add(i)
    res=0
    for i in range(V):
        vis=[False]*(V)
        vis[i]=find_component(V,graph,vis)
        if vis[i]==False:res+=1
    return res

