def circularSubarraySum(arr, n):
	if n == 1:
		return arr[0]
	z = 0
	for i in range(n):
		if arr[i] < 0:
			z = z + 1
	if z == n:
		return max(arr)

	def kdan(arr, n):
		sm = 0
		ind = -1
		mx = 0
		for i in range(n):
			sm = sm + arr[i]
			if sm <= 0:
				sm = 0
				ind = i + 1
			if mx < sm:
				mx = sm
		return mx
	mx1 = kdan(arr, n)
	totalsm = 0
	for i in range(n):
		totalsm += arr[i]
		arr[i] = 0 - arr[i]
	sm1 = kdan(arr, n)
	mx2 = totalsm - -sm1
	return max(mx1, mx2)

