	def nextPalin(self, string: str):
		string = list(string)
		N = len(string)
		if N <= 3:
			return -1
		mid = N // 2 - 1
		i = mid - 1
		while i >= 0:
			if string[i] < string[i + 1]:
				break
			i -= 1
		if i < 0:
			return -1
		smallest = i + 1
		j = i + 2
		while j <= mid:
			if string[j] > string[i] and string[j] <= string[smallest]:
				smallest = j
			j += 1
		temp = string[i]
		string[i] = string[smallest]
		string[smallest] = temp
		temp = string[N - 1 - i]
		string[N - 1 - i] = string[N - 1 - smallest]
		string[N - 1 - smallest] = temp
		reverse(string, i + 1, mid)
		if N % 2 == 0:
			reverse(string, mid + 1, N - i - 2)
		else:
			reverse(string, mid + 2, N - i - 2)
		return ''.join(string)

