def solve(n, s):
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[0][i] = dp[0][i - 1] + (s[i - 1] == '1')
        dp[1][i] = dp[1][i - 1]
    for i in range(2, n + 1):
        for j in range(i, n + 1):
            dp[i][j] = min(dp[i][j - 1], dp[i - 1][j - 1] + (s[j - 1] == '1'))
    return dp[k][n]

