class Solution {
    public int minDominoRotations(int[] A, int[] B) {
        int n = A.length;
        int res = n + 1;
        for (int num=1; num<=6; num++) {
            int temp = 0;
            for (int i=0; i<n; i++) {
                if (A[i] == num) {
                    continue;
                } else if (B[i] == num) {
                    temp++;
                } else {
                    temp = n+1;
                    break;
                }
            }
            res = Math.min(res, temp);
        }

        for (int num=1; num<=6; num++) {
            int temp = 0;
            for (int i=0; i<n; i++) {
                if (B[i] == num) {
                    continue;
                } else if (A[i] == num) {
                    temp++;
                } else {
                    temp = n+1;
                    break;
                }
            }
            res = Math.min(res, temp);
        }

        if (res == n+1) {
            return -1;
        }
        return res;
    }
}

