            char[] a = s.toCharArray();
            int[] cnt = new int[10];

            for (int i = 0; i < a.length; i++) {
                cnt[a[i] - '0']++;
            }

            StringBuilder b = new StringBuilder();
            StringBuilder c = new StringBuilder();

            for (int i = 0; i < a.length; i++) {
                cnt[a[i] - '0']--;
                int k = a[i] - '0' + 1;

                if (k > 9) {
                    k = 9;
                }

                if (cnt[a[i] - '0'] > 0 && k < a[i] - '0') {
                    b.append(k);
                } else {
                    c.append(a[i]);
                }
            }

            for (int i = 1; i <= 9; i++) {
                for (int j = 0; j < b.length(); j++) {
                    if (b.charAt(j) - '0' == i) {
                        c.insert(c.length(), b.charAt(j));
                    }
                }
            }

            System.out.println(c.toString());
        }
    }
