def solve(arr, K):
    # Prepare two lists count and need for counting the occurrences 
    # and the minimum need for every number, respectively.
    min_val = min(arr)
    right = max(arr)
    count = [0] * (max(arr) + 2)
    need = [0] * (max(arr) + 2)

    # Process the array from left to right.
    for x in arr:
        count[x] += 1

    for x in range(min_val, right + 1):
        while need[x] < count[x]:
            for i in range(x * 2, right + 2, x):
                need[i] += 1
        while need[x] > count[x]:
            for i in range(x * 2, right + 2, x):
                need[i] -= 1

    # Check if there is no number in the array in the current need. 
    for x in range(min_val, right + 1):
        if need[x] > 0:
            return -1

    return right

