def can_reach_cell(n, m, k):
    # If k is 0, we are already at the end cell.
    if k == 0:
        return "YES"
    # If n and m are the same, it's only one path with cost n*m.
    elif n == m:
        if k == n*m:
            return "YES"
        else:
            return "NO"
    # If n is the same as m multiplied by a whole number, find the cost.
    else:
        # Calculate the maximum cost of either moving down or right,
        # taking care not to exceed the current k value.
        for i in range(1, n):
            cost_right = k - i  # Cost to move right
            cost_down = k - (n - i)  # Cost to move down after adjusting for i
            if cost_right >= m - i and cost_down >= m - i:
                return "YES"
        return "NO"

