class Solution 
{
public:
    int maximumSwap(int num) 
    {
        string data, nums;
        fun(num, data);
        nums = data;
        reverse(nums.begin(),nums.end());
        sort(data.begin(),data.end(),[](char a,char b){return a>b;});
        int n=data.size(),i,j;
        for(i=0;i<n;i++)
            if(nums[i]!=data[i])
                break;
        if(i==n)
            return num;
        for(j=n-1;j>i;j--)
            if(nums[j]==data[i])
                break;
        swap(nums[i],nums[j]);
        return stoi(nums);
    }
    void fun(int num, string &data)
    {
        while(num!=0)
        {
            data.push_back(num%10+'0');
            num/=10;
        }
    }
};

