class BinarySearchTree(list):

	def __init__(self):
		list.__init__(self)
		self.root = None

	def insert(self, z):
		z = Node(z)
		y = None
		x = self.root
		while x is not None:
			y = x
			if z.key < x.key:
				x = x.left
			else:
				x = x.right
		z.parent = y
		if y is None:
			self.root = z
		elif z.key < y.key:
			y.left = z
		else:
			y.right = z

	def preorder(self):

		def preParse(u):
			if u == None:
				return
			print(' ' + str(u.key), end='')
			preParse(u.left)
			preParse(u.right)
		preParse(self.root)
		print('')

	def inorder(self):

		def inParse(u):
			if u == None:
				return
			inParse(u.left)
			print(' ' + str(u.key), end='')
			inParse(u.right)
		inParse(self.root)
		print('')

	def print(self):
		self.inorder()
		self.preorder()

	def find(self, k):
		x = self.root
		while x is not None and k != x.key:
			if k < x.key:
				x = x.left
			else:
				x = x.right
		return x
