class $UnionFind$ (object):

    def __init__ (self, n):

        self._id = list(range(n))

        self._sz = [1] * n

    def find (self, p):

        while p != self._id[p]:
            self._id[p] = self._id[self._id[p]]
            p = self._id[p]

        return p

    def union (self, p, q):
        proot = self.find (p)
        qroot = self.find(q)
        if proot != qroot:

            if self._sz[proot] < self._sz[qroot]:
                proot, qroot = qroot, proot

            self._sz[qroot] += self._sz[proot]

            self._id[proot] = qroot

    def connected (self, p, q):
        return self.find(p) == self.find(q)

