class FrontMiddleBackQueue {

    IFrontMiddleBackQueue sln;

    public FrontMiddleBackQueue() {
        sln = new Sln1();
    }

    public void pushFront(int val) {
        sln.pushFront(val);
    }

    public void pushMiddle(int val) {
        sln.pushMiddle(val);
    }

    public void pushBack(int val) {
        sln.pushBack(val);
    }

    public int popFront() {
        return sln.popFront();
    }

    public int popMiddle() {
        return sln.popMiddle();
    }

    public int popBack() {
        return sln.popBack();
    }
}

interface IFrontMiddleBackQueue{

    public void pushFront(int val);

    public void pushMiddle(int val) ;

    public void pushBack(int val) ;

    public int popFront() ;

    public int popMiddle() ;

    public int popBack() ;
}


class Sln1 implements IFrontMiddleBackQueue {

    Deque<Integer> front;
    Deque<Integer> back;

    public Sln1() {
        front= new ArrayDeque<>();
        back = new ArrayDeque<>();

    }

    public void pushFront(int val) {
        front.addFirst(val);
        if(front.size()-back.size()>0) back.addFirst(front.removeLast());
    }

    public void pushMiddle(int val) {
        front.addLast(val);
        if(front.size()-back.size()>0) back.addFirst(front.removeLast());
    }

    public void pushBack(int val) {
        back.addLast(val);
        if(back.size()-front.size()>1) front.addLast(back.removeFirst());
    }

    public int popFront() {
        if(back.size()==0) return -1;
        if(front.size()==0) return back.removeLast();
        int res = front.removeFirst();
        if(back.size()-front.size()>1) front.addLast(back.removeFirst());
        return res;
    }

    public int popMiddle() {
        if(back.size()==0) return -1;
        if((front.size()+back.size())%2==1) return back.removeFirst();
        else return front.removeLast();
    }

    public int popBack() {
        if(back.size() == 0) return -1;
        int res = back.removeLast();
        if(front.size()-back.size()>0) back.addFirst(front.removeLast());
        return res;
    }
}
