        if(res < 0) res += mod;
        return (int)(res % mod);

    }

    public long cal(String s, long dp[][][]) {

        int d = s.charAt(0) - '0';
        long res = 0;
        for(int i = 1; i < d; i++) {
            if(i <= m2) {
                res += dfs(s, dp, 1, 1, i);
                res %= mod;
            }
        }
        if(d <= m2) {
            res += dfs(s, dp, 1, 0, d);
            res %= mod;
        }

        //System.out.println(s + " " + res);

        int n = s.length();
        long f[][] = new long[n][m2 + 1];
        for(int i = 1; i < 10; i++) {
            if(i <= m2)
                f[0][i] = 1;
        }

        for(int i = 1; i < n - 1; i++) {
            for(int j = 0; j < 10; j++) {
                for(int sum = 0; sum <= m2; sum++) {
                    if(sum >= j) {
                        f[i][sum] += f[i - 1][sum - j];
                        f[i][sum] %= mod;
                    }
                }
            }
        }

        long sum1 = 0;
        for(int i = 0; i < n - 1; i++) {
            for(int j = m1; j <= m2; j++) {
                sum1 += f[i][j];
                sum1 %= mod;
            }
        }

        //System.out.println(sum1);

        res += sum1;
        sum1 %= mod;


        return res;

    }

    public long dfs(String s, long dp[][][], int idx, int st, int sum) {
        if(idx >= s.length()) {
            if(sum >= m1 && sum <= m2) {
                return 1;
            }
            return 0;
        }
        //System.out.println("gg " + sum);
        if(dp[idx][st][sum] != -1) {
            return dp[idx][st][sum];
        }

        long res = 0;
        int d = s.charAt(idx) - '0';
        if(st == 0) { //same prefix
            if(sum + d <= m2) {
                res += dfs(s, dp, idx + 1, st, sum + d);
                res %= mod;
            }

            for(int i = 0; i < d; i++) {
                if(sum + i <= m2) {
                    res += dfs(s, dp, idx + 1, 1, sum + i);
                    res %= mod;
                }
            }

        } else {
            for(int i = 0; i < 10; i++) {
                if(sum + i <= m2) {
                    res += dfs(s, dp, idx + 1, st, sum + i);
                    res %= mod;
                }
            }
        }

        return dp[idx][st][sum] = res;
    }
}

