def checkSubsequence(a, b):
    if not a or not b:
        return False
    index = 0
    match = 0
    for i in range(len(a)):
        while match < len(b) and a[i] > b[match]:
            match += 1
        if match == len(b):
            return False
        while index < len(b) and b[index] == a[i]:
            index += 1
        if index == len(b):
            return False
    return match == len(b)

