def min_operations(a, b):
    # Count the number of 4s and 7s that need to be changed
    count_4_to_7 = 0
    count_7_to_4 = 0

    for i in range(len(a)):
        if a[i] != b[i]:
            if a[i] == '4':
                count_4_to_7 += 1
            else:
                count_7_to_4 += 1

    # The minimum number of operations is the maximum of the two counts
    # because we can swap 4s and 7s, but if one count is larger, we need to replace the excess
    return max(count_4_to_7, count_7_to_4)

