class Solution {
public:
    int earliestFullBloom(vector<int>& plantTime, vector<int>& growTime) {
		vector<pair<int,int>> V;
		int i;
		FOR(i,plantTime.size()) V.push_back({-growTime[i],plantTime[i]});
		sort(ALL(V));
		int ma=0;
		int cur=0;
		FORR(a,V) {
			cur+=a.second;
			ma=max(ma,cur-a.first);
		}
		return ma;

    }
};

