class TrieNode:
    def __init__(self):
        self.children = {}
        self.valid_word = False

class StreamChecker:
    def __init__(self, words):
        self.root = TrieNode()
        self.stream = deque([])
        for word in words:
            node = self.root
            for ch in reversed(word):
                if not ch in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.valid_word = True

    def query(self, letter):
        self.stream.appendleft(letter)
        node = self.root
        for ch in reversed(self.stream):
            if ch not in node.children or node.valid_word:
                return node.valid_word
            node = node.children[ch]        
        return False

