def panos_sort(first, end, a):
	cur = end - first + 1
	mid = first + (cur - 1) // 2
	if cur == 1:
		return 1
	if cur == 2:
		return 2 if a[first] <= a[end] else 1
	f_res = panos_sort(first, mid, a)
	e_res = panos_sort(mid + 1, end, a)
	if f_res == cur // 2 and e_res == cur // 2:
		return cur if a[mid] <= a[mid + 1] else max(f_res, e_res)
	else:
		return max(f_res, e_res)

def main():
	n = int(input())
	a = list(map(int, input().split()))
	print(panos_sort(0, n - 1, a))
