def find_life_time(X, A, N):
    left, right = 0, max(A)
    while left < right:
        mid = (left + right) // 2
        if sum(A) + mid < N * X:
            left = mid + 1
        else:
            right = mid
    return right

def main():
    T = int(input())
    for _ in range(T):
        N, X = map(int, input().split())
        A = list(map(int, input().split()))
        print(find_life_time(X, A, N))

