def smallest_prime_divisor(n):
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

def number_of_subtractions(n):
    count = 0
    while n > 0:
        d = smallest_prime_divisor(n)
        n -= d
        count += 1
    return count

