public:
    bool Find1(vector<int>& nums, int start, int end, bool &result)
    {
        if (start >= end)
        {
            result = false;
            return result;
        }
        int mid = start + (end - start) / 2;

        result = true;
        for (int i = start; i < mid; ++i)
        {
            result = result && (nums[i] < nums[i + 1]);
        }
        for (int i = mid + 1; i < end; ++i)
        {
            result = result && (nums[i] > nums[i - 1]);
        }

        if (!result)
        {
            return result;
        }

        return Find2(nums, mid + 1, end, result) || Find1(nums, start, mid - 1, result);
    }

    bool Find2(vector<int>& nums, int start, int end)
    {
        if (start >= end)
        {
            return false;
        }
        int mid = start + (end - start) / 2;
        bool result = false;
        result = Find1(nums, start, mid, result) || Find1(nums, mid + 1, end, result);
        return result;
    }

    bool IncreasingTriplet(vector<int>& nums) 
    {
        bool result = false;
        Find1(nums, 0, nums.size() - 1, result);
        return result;
    }
};











