def solve(x):
	log_2 = (x + 1).bit_length() - 1
	if x < 8:
		return log_2
	return log_2 + bin(x + 1 - (1 << log_2) >> 1 & (1 << log_2 - 2) - 1).count('1')
for i in range(int(input())):
	n = int(input())
	if n == 1:
		print(1)
	elif n % 2 == 0:
		print(n + 1 - solve(n + 1))
	else:
		print(solve(n))

