ll binary_search(function<bool(ll)> check, ll ok, ll ng) {

  assert(check(ok));

  while (abs(ok - ng) > 1) {

    auto x = (ng + ok) / 2;

    if (check(x))

      ok = x;

    else

      ng = x;

  }

  return ok;

}



template <typename F>

double binary_search_real(F check, double ok, double ng, int iter = 100) {

  FOR(iter) {

    double x = (ok + ng) / 2;

    if (check(x)) {

      ok = x;

    } else {

      ng = x;

    }

  }

  return (ok + ng) / 2;

}



