struct Scanner {

  FILE *fp;

  char line[(1 << 15) + 1];

  size_t st = 0, ed = 0;

  void reread() {

    memmove(line, line + st, ed - st);

    ed -= st;

    st = 0;

    ed += fread(line + ed, 1, (1 << 15) - ed, fp);

    line[ed] = '\0';

  }

  bool succ() {

    while (true) {

      if (st == ed) {

        reread();

        if (st == ed) return false;

      }

      while (st != ed && isspace(line[st])) st++;

      if (st != ed) break;

    }

    if (ed - st <= 50) {

      bool sep = false;

      for (size_t i = st; i < ed; i++) {

        if (isspace(line[i])) {

          sep = true;

          break;

        }

      }

      if (!sep) reread();

    }

    return true;

  }

  template <class T, enable_if_t<is_same<T, string>::value, int> = 0>

  bool read_single(T &ref) {

    if (!succ()) return false;

    while (true) {

      size_t sz = 0;

      while (st + sz < ed && !isspace(line[st + sz])) sz++;

      ref.append(line + st, sz);

      st += sz;

      if (!sz || st != ed) break;

      reread();

    }

    return true;

  }

  template <class T, enable_if_t<is_integral<T>::value, int> = 0>

  bool read_single(T &ref) {

    if (!succ()) return false;

    bool neg = false;

    if (line[st] == '-') {

      neg = true;

      st++;

    }

    ref = T(0);

    while (isdigit(line[st])) { ref = 10 * ref + (line[st++] & 0xf); }

    if (neg) ref = -ref;

    return true;

  }

  template <class T, is_modint_t<T> * = nullptr>

  bool read_single(T &ref) {

    long long val = 0;

    bool f = read_single(val);

    ref = T(val);

    return f;

  }

  bool read_single(double &ref) {

    string s;

    if (!read_single(s)) return false;

    ref = std::stod(s);

    return true;

  }

  bool read_single(char &ref) {

    string s;

    if (!read_single(s) || s.size() != 1) return false;

    ref = s[0];

    return true;

  }

  template <class T>

  bool read_single(vector<T> &ref) {

    for (auto &d: ref) {

      if (!read_single(d)) return false;

    }

    return true;

  }

  template <class T, class U>

  bool read_single(pair<T, U> &p) {

    return (read_single(p.first) && read_single(p.second));

  }

  template <class A, class B, class C>

  bool read_single(tuple<A, B, C> &p) {

    return (read_single(get<0>(p)) && read_single(get<1>(p))

            && read_single(get<2>(p)));

  }

  template <class A, class B, class C, class D>

  bool read_single(tuple<A, B, C, D> &p) {

    return (read_single(get<0>(p)) && read_single(get<1>(p))

            && read_single(get<2>(p)) && read_single(get<3>(p)));

  }

  void read() {}

  template <class H, class... T>

  void read(H &h, T &... t) {

    bool f = read_single(h);

    assert(f);

    read(t...);

  }

  Scanner(FILE *fp) : fp(fp) {}

};



struct Printer {

  Printer(FILE *_fp) : fp(_fp) {}

  ~Printer() { flush(); }



  static constexpr size_t SIZE = 1 << 15;

  FILE *fp;

  char line[SIZE], small[50];

  size_t pos = 0;

  void flush() {

    fwrite(line, 1, pos, fp);

    pos = 0;

  }

  void write(const char &val) {

    if (pos == SIZE) flush();

    line[pos++] = val;

  }

  template <class T, enable_if_t<is_integral<T>::value, int> = 0>

  void write(T val) {

    if (pos > (1 << 15) - 50) flush();

    if (val == 0) {

      write('0');

      return;

    }

    if (val < 0) {

      write('-');

      val = -val; // todo min

    }

    size_t len = 0;

    while (val) {

      small[len++] = char(0x30 | (val % 10));

      val /= 10;

    }

    for (size_t i = 0; i < len; i++) { line[pos + i] = small[len - 1 - i]; }

    pos += len;

  }

  void write(const string &s) {

    for (char c: s) write(c);

  }

  void write(const char *s) {

    size_t len = strlen(s);

    for (size_t i = 0; i < len; i++) write(s[i]);

  }

  void write(const double &x) {

    ostringstream oss;

    oss << fixed << setprecision(15) << x;

    string s = oss.str();

    write(s);

  }

  void write(const long double &x) {

    ostringstream oss;

    oss << fixed << setprecision(15) << x;

    string s = oss.str();

    write(s);

  }

  template <class T, is_modint_t<T> * = nullptr>

  void write(T &ref) {

    write(ref.val);

  }

  template <class T>

  void write(const vector<T> &val) {

    auto n = val.size();

    for (size_t i = 0; i < n; i++) {

      if (i) write(' ');

      write(val[i]);

    }

  }

  template <class T, class U>

  void write(const pair<T, U> &val) {

    write(val.first);

    write(' ');

    write(val.second);

  }

  template <class A, class B, class C>

  void write(const tuple<A, B, C> &val) {

    auto &[a, b, c] = val;

    write(a), write(' '), write(b), write(' '), write(c);

  }

  template <class A, class B, class C, class D>

  void write(const tuple<A, B, C, D> &val) {

    auto &[a, b, c, d] = val;

    write(a), write(' '), write(b), write(' '), write(c), write(' '), write(d);

  }

  template <class A, class B, class C, class D, class E>

  void write(const tuple<A, B, C, D, E> &val) {

    auto &[a, b, c, d, e] = val;

    write(a), write(' '), write(b), write(' '), write(c), write(' '), write(d), write(' '), write(e);

  }

  template <class A, class B, class C, class D, class E, class F>

  void write(const tuple<A, B, C, D, E, F> &val) {

    auto &[a, b, c, d, e, f] = val;

    write(a), write(' '), write(b), write(' '), write(c), write(' '), write(d), write(' '), write(e), write(' '), write(f);

  }

  template <class T, size_t S>

  void write(const array<T, S> &val) {

    auto n = val.size();

    for (size_t i = 0; i < n; i++) {

      if (i) write(' ');

      write(val[i]);

    }

  }

  void write(i128 val) {

    string s;

    bool negative = 0;

    if(val < 0){

      negative = 1;

      val = -val;

    }

    while (val) {

      s += '0' + int(val % 10);

      val /= 10;

    }

    if(negative) s += "-";

    reverse(all(s));

    if (len(s) == 0) s = "0";

    write(s);

  }

};



