// HLD euler tour をとっていろいろ。

// 木以外、非連結でも dfs 順序や親がとれる。

template <typename Graph>

struct TREE {

  Graph &G;

  using Graph_type = Graph;

  using WT = typename Graph::cost_type;

  int N;

  bool hld;

  vector<int> LID, RID, head, V, parent, root;

  vc<int> depth;

  vc<WT> depth_weighted;

  vector<bool> in_tree;



  TREE(Graph &G, int r = -1, bool hld = 1)

      : G(G),

        N(G.N),

        hld(hld),

        LID(G.N),

        RID(G.N),

        head(G.N, r),

        V(G.N),

        parent(G.N, -1),

        root(G.N, -1),

        depth(G.N, -1),

        depth_weighted(G.N, 0),

        in_tree(G.M, 0) {

    assert(G.is_prepared());

    int t1 = 0;

    if (r != -1) {

      dfs_sz(r, -1);

      dfs_hld(r, t1);

    } else {

      for (int r = 0; r < N; ++r) {

        if (parent[r] == -1) {

          head[r] = r;

          dfs_sz(r, -1);

          dfs_hld(r, t1);

        }

      }

    }

    for (auto &&v: V) root[v] = (parent[v] == -1 ? v : root[parent[v]]);

  }



  void dfs_sz(int v, int p) {

    auto &sz = RID;

    parent[v] = p;

    depth[v] = (p == -1 ? 0 : depth[p] + 1);

    sz[v] = 1;

    int l = G.indptr[v], r = G.indptr[v + 1];

    auto &csr = G.csr_edges;

    // 使う辺があれば先頭にする

    for (int i = r - 2; i >= l; --i) {

      if (depth[csr[i + 1].to] == -1) swap(csr[i], csr[i + 1]);

    }

    int hld_sz = 0;

    for (int i = l; i < r; ++i) {

      auto e = csr[i];

      if (depth[e.to] != -1) continue;

      in_tree[e.id] = 1;

      depth_weighted[e.to] = depth_weighted[v] + e.cost;

      dfs_sz(e.to, v);

      sz[v] += sz[e.to];

      if (hld && chmax(hld_sz, sz[e.to]) && l < i) { swap(csr[l], csr[i]); }

    }

  }



  void dfs_hld(int v, int &times) {

    LID[v] = times++;

    RID[v] += LID[v];

    V[LID[v]] = v;

    bool heavy = true;

    for (auto &&e: G[v]) {

      if (!in_tree[e.id] || depth[e.to] <= depth[v]) continue;

      head[e.to] = (heavy ? head[v] : e.to);

      heavy = false;

      dfs_hld(e.to, times);

    }

  }



  int e_to_v(int eid) {

    auto e = G.edges[eid];

    return (parent[e.frm] == e.to ? e.frm : e.to);

  }



  int ELID(int v) { return 2 * LID[v] - depth[v]; }

  int ERID(int v) { return 2 * RID[v] - depth[v] - 1; }



  /* k: 0-indexed */

  int LA(int v, int k) {

    assert(k <= depth[v]);

    while (1) {

      int u = head[v];

      if (LID[v] - k >= LID[u]) return V[LID[v] - k];

      k -= LID[v] - LID[u] + 1;

      v = parent[u];

    }

  }



  int LCA(int u, int v) {

    for (;; v = parent[head[v]]) {

      if (LID[u] > LID[v]) swap(u, v);

      if (head[u] == head[v]) return u;

    }

  }



  int lca(int u, int v) { return LCA(u, v); }

  int la(int u, int v) { return LA(u, v); }



  int subtree_size(int v) { return RID[v] - LID[v]; }



  int dist(int a, int b) {

    int c = LCA(a, b);

    return depth[a] + depth[b] - 2 * depth[c];

  }



  WT dist(int a, int b, bool weighted) {

    assert(weighted);

    int c = LCA(a, b);

    return depth_weighted[a] + depth_weighted[b] - 2 * depth_weighted[c];

  }



  // a is in b

  bool in_subtree(int a, int b) { return LID[b] <= LID[a] && LID[a] < RID[b]; }



  int jump(int a, int b, int k = 1) {

    if (k == 1) {

      if (a == b) return -1;

      return (in_subtree(b, a) ? LA(b, depth[b] - depth[a] - 1) : parent[a]);

    }

    int c = LCA(a, b);

    int d_ac = depth[a] - depth[c];

    int d_bc = depth[b] - depth[c];

    if (k > d_ac + d_bc) return -1;

    if (k <= d_ac) return LA(a, k);

    return LA(b, d_ac + d_bc - k);

  }



  vc<int> collect_child(int v) {

    vc<int> res;

    for (auto &&e: G[v])

      if (e.to != parent[v]) res.eb(e.to);

    return res;

  }



  vc<pair<int, int>> get_path_decomposition(int u, int v, bool edge) {

    // [始点, 終点] の"閉"区間列。

    vc<pair<int, int>> up, down;

    while (1) {

      if (head[u] == head[v]) break;

      if (LID[u] < LID[v]) {

        down.eb(LID[head[v]], LID[v]);

        v = parent[head[v]];

      } else {

        up.eb(LID[u], LID[head[u]]);

        u = parent[head[u]];

      }

    }

    if (LID[u] < LID[v]) down.eb(LID[u] + edge, LID[v]);

    elif (LID[v] + edge <= LID[u]) up.eb(LID[u], LID[v] + edge);

    reverse(all(down));

    up.insert(up.end(), all(down));

    return up;

  }



  void debug() {

    print("V", V);

    print("LID", LID);

    print("RID", RID);

    print("parent", parent);

    print("depth", depth);

    print("head", head);

    print("in_tree(edge)", in_tree);

    print("root", root);

  }

};

