void solve() {

  LL(N);

  Graph<int, 0> G(N);

  G.read_tree();

  TREE<decltype(G)> tree(G);



  vv(ll, dp, N, N, -1);

  auto dfs = [&](auto& dfs, int a, int b) -> ll {

    if (a > b) swap(a, b);

    if (dp[a][b] != -1) return dp[a][b];

    ll& res = dp[a][b];

    res = 0;

    if (a == b) return res;

    int xa = tree.jump(a, b);

    int xb = tree.jump(b, a);

    ll na = (xa == tree.parent[a] ? tree.subtree_size(a)

                                  : N - tree.subtree_size(xa));

    ll nb = (xb == tree.parent[b] ? tree.subtree_size(b)

                                  : N - tree.subtree_size(xb));

    chmax(res, na * nb + dfs(dfs, xa, b));

    chmax(res, na * nb + dfs(dfs, xb, a));

    return res;

  };



  ll ANS = 0;



  FOR(a, N) FOR(b, N) { chmax(ANS, dfs(dfs, a, b)); }

  print(ANS);

}



