private:
    int index;
    vector<int> flipped;

    vector<int> dfs(TreeNode* root, vector<int>& voyage){
        if(!root) return {};
        if(root->val != voyage[index]) return {-1};
        index++;
        if(root->left && root->left->val != voyage[index]){
            root->left= swap(root->left, root->right);
            flipped.push_back(root->val);
        }
        vector<int> leftDfsResult = dfs(root->left, voyage);
        if(leftDfsResult[0] == -1) return leftDfsResult;
        vector<int> rightDfsResult = dfs(root->right, voyage);
        if(rightDfsResult[0] == -1) return rightDfsResult;
        return {};
    }

public:
    vector<int> flipMatchVoyage(TreeNode* root, vector<int>& voyage) {
        this->index = 0;
        vector<int> result = dfs(root, voyage);
        return result.empty() ? flipped : {-1};
    }
