class Solution:
    def allPairs(self,A,B,X):
        # Code Here
        res = list()
        A.sort()
        B.sort()
        for a in A:
            l = 0
            r = len(B)-1
            while l <= r:
                mid = (l+r)//2
                if B[mid] + a == X:
                    res.append([a,B[mid]])
                    l = mid + 1
                    r = mid - 1
                elif B[mid] + a < X:
                    l = mid + 1
                else:
                    r = mid - 1
        return res

