def count_distinct_plans(gym, m):
    distinct_plans = 1
    for i in range(1, m + 1):
        distinct_plans *= count_distinct_plans_for_type(gym, i)
        distinct_plans %= 10**9 + 7
    return distinct_plans

def count_distinct_plans_for_type(gym, type):
    distinct_plans = 1
    for i in range(len(gym)):
        if gym[i] == type:
            distinct_plans *= count_distinct_plans_for_type(gym[:i] + gym[i + 1:], type)
            distinct_plans %= 10**9 + 7
    return distinct_plans

