public String largestGoodInteger(String num) {
    String max = "";
    for (int i = 0; i < num.length() - 2; i++) {
        String substr = num.substring(i, i + 3);
        if (isGoodInteger(substr) && substr.compareTo(max) > 0) {
            max = substr;
        }
    }
    return max;
}

private boolean isGoodInteger(String num) {
    return num.charAt(0) == num.charAt(1) && num.charAt(1) == num.charAt(2);
}

MOD = 998244353

def count_sequences(S, T):
    n = len(S)
    m = len(T)

    # dp[i][j] will store the number of ways to make A a prefix of T using the first i characters of S and j operations
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: dp[0][0] = 1, no operations needed to make an empty A a prefix of T
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            # Option 1: Delete the first character of S and add it at the front of A
            if j > 0:
                dp[0][j] = (dp[0][j] + dp[0][j - 1]) % MOD
            # Option 2: Delete the first character of S and add it at the back of A
            dp[0][j] = (dp[0][j] + dp[0][j]) % MOD

    for i in range(1, m + 1):
        for j in range(n + 1):
            for k in range(n + 1):
                if j > 0 and k > 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][k - 1]) % MOD

    return dp[m][n]

