import sys

def mex(arr):
    """Find the smallest non-negative integer that does not occur in the set."""
    for i in range(len(arr) + 1):
        if i not in arr:
            return i

def calculate_cost(arr):
    """Calculate the cost of a partition."""
    cost = 0
    for sub_arr in arr:
        cost += 1 + mex(sub_arr)
    return cost

def find_partitions(arr):
    """Find all possible partitions of the array."""
    partitions = []
    for i in range(1 << (len(arr) - 1)):
        partition = []
        last_index = 0
        for j in range(len(arr) - 1):
            if (i & (1 << j)):
                partition.append(arr[last_index:j + 1])
                last_index = j + 1
        partition.append(arr[last_index:])
        partitions.append(partition)
    return partitions

def calculate_value(arr):
    """Calculate the value of the array."""
    max_cost = 0
    for partition in find_partitions(arr):
        cost = calculate_cost(partition)
        if cost > max_cost:
            max_cost = cost
    return max_cost

def main():
    input_lines = sys.stdin.readlines()
    input_index = 0
    def next_line():
        nonlocal input_index
        input_index += 1
        return input_lines[input_index - 1].strip()

    t = int(next_line())
    for _ in range(t):
        n = int(next_line())
        arr = list(map(int, next_line().split()))
        total_value = 0
        for i in range(n):
            for j in range(i, n):
                sub_arr = arr[i:j + 1]
                total_value += calculate_value(sub_arr)
        print(total_value)

