def possibleBipartition(self, N: int, dislikes: List[List[int]]) -> bool:
        graph = collections.defaultdict(list)
        for u, v in dislikes:
            graph[u].append(v)
            graph[v].append(u)

        color = {}
        def dfs(node, c=0):
            if node in color:
                return color[node] == c
            color[node] = c
            return all(dfs(nei, c ^ 1) for nei in graph[node])

        return all(dfs(node)
                   for node in range(1, N+1)
                   if node not in color)






class Solution:
    def possibleBipartition(self, N: int, dislikes: List[List[int]]) -> bool:
        graph = [[] for _ in range(N)]
        for edge in dislikes:
            graph[edge[0] - 1].append(edge[1] - 1)
            graph[edge[1] - 1].append(edge[0] - 1)

        colors = [0] * N

        def dfs(node, c):
            colors[node] = c
            for neighbor in graph[node]:
                if colors[neighbor] == c:
                    return False
                if colors[neighbor] == 0 and not dfs(neighbor, -c):
                    return False
            return True

        for node in range(N):
            if colors[node] == 0:
                if not dfs(node, 1):
                    return False

        return True

