import numpy as np

def find_common_subsequence(a, b):
    K = len(a) + 1
    L = len(b) + 1

    dp_table = np.zeros((K, L), dtype=int)

    for i in range(1, K):
        for j in range(1, L):
            if a[i - 1] == b[j - 1]:
                dp_table[i][j] = dp_table[i - 1][j - 1] + 1
            else:
                dp_table[i][j] = max(dp_table[i][j - 1], dp_table[i - 1][j])

    k = dp_table[-1, -1]
    i, j = K - 1, L - 1
    c = []

    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            c.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp_table[i - 1][j] > dp_table[i][j - 1]:
            i -= 1
        else:
            j -= 1

    c = c[::-1]

    return k, c

