# Python3 program to insert into a Binary Search Tree

# Helper function to inorder traversal
def printInorder(root):
    if root:
        printInorder(root.left)
        print(root.data,end=" ")
        printInorder(root.right)

# Helper function to insert a new node with given key in BST and return root of modified BST
def insert(root,key):
    # if the tree is empty, assign a new node address
    if root is None:
        return Node(key)
    else:
        # Otherwise check the key with root
        if root.data < key:
            if root.right:
                # If key is greater than root's key, recur for right subtree
                root.right = insert(root.right, key)
            else:
                # If right child is None, assign new node
                root.right = Node(key)
        else:
            if root.left:
                # If key is smaller than root's key, recur for left child
                root.left = insert(root.left, key)
            else:
                # If left child is None, assign new node
                root.left = Node(key)
    return root

