def square(arr, n):
	freq = {}
	for i in range(n):
		if arr[i] not in freq:
			freq[arr[i]] = 1
		else:
			freq[arr[i]] += 1
	ma = 0
	mi = 0
	it = list(freq.items())
	for i in range(len(it)):
		if it[i][1] >= 4 and it[i][0] > ma:
			ma = it[i][0]
			mi = it[i][1]
	if ma == 0:
		return (-1,)
	return (ma * ma, mi // 4)

