def count_NGEs(arr, queries, indices):
    len_ = len(queries)
    NGEs = []
    for idx in range(len_):
        NGE = -1
        target = indices[idx]
        stack = []
        for i in range(min(target+1,len(arr))): 
            if target+1<len(arr):
                if target<len(arr) and i>/target+1:
                    n_idx = stack[0]
                    if i<n_idx:
                        if arr[i]>arr[n_idx]:
                            NGE = arr[n_idx]
                            stack.pop(0)
                            break
                        else:
                            stack.append(n_idx)
                    else:
                        if arr[i]>arr[n_idx]:
                            NGE = arr[n_idx]
                            break
                        else:
                            stack.append(i)
                else:
                    if target<i:
                        if arr[i]>arr[i]:
                            NGE = arr[i]
                            break
                        else:
                            stack.append(i)
                    else:
                        if arr[i]>arr[i]:
                            NGE = arr[i]
                            break
                        else:
                            stack.append(i)
        NGEs.append(NGE)
    return NGEs

