def is_good_word(word):
    return len(set(word)) == 5 and 'z' in word


def dfs(word, i):
    if i == len(word):
        return True

    if word[i] == '.':
        if is_good_word(word[:i]):
            return dfs(word[:i] + 'z' * (len(word) - i), i + 1)
        return False

    return dfs(word, i + 1)


def is_good(word):
    if len(word) == 5:
        return is_good_word(word)

    for i in range(len(word) + 1):
        if word[i] != '.' and is_good(word[:i] + word[i + 1:]):
            return True

    return False


def solve(n):
    if n % 2 == 1 or n <= 4:
        return False

    s = str(n)

    if is_good(s):
        return True
    elif len(s) % 2 == 0 and is_good_word(s[:len(s) // 2]) and is_good(s[len(s) // 2:]):
        return True

    return False


