def func(n, m, originals, changed):
	result = []
	for i in range(len(originals[0])):
		before = Counter([val[i] for val in originals])
		after = Counter([val[i] for val in changed])
		result.append(list((before - after).keys())[0])
	return ''.join(map(str, result))

