class Solution:

	def smallestSumSubarray(self, A, N):
		total = sum(A)
		curSum = A[0]
		minSum = A[0]
		for i in range(1, N):
			if curSum > 0:
				curSum = A[i]
			else:
				curSum += A[i]
			minSum = min(minSum, curSum)
		return minSum

