import bisect
from collections import defaultdict
from typing import List

# Accepted but slow, needs improvement
def closet_targets(arr: List[str], target_word: str, start_index: int):
    # this shouldn't happen
    if not arr:
        return -1
    # repeat the words since it's a circular array
    if arr[0] != target_word:
        arr.append(target_word)
    if arr[-1] != target_word:
        arr.insert(0, target_word)

    head_index = arr.index(target_word)
    if head_index == 0:
        return len(arr) - 1
    arr1 = arr[head_index:] + arr[:head_index]
    head_index = arr.index(target_word)
    if head_index == 0:
        return len(arr) - 1
    arr2 = arr1[:head_index + 1][::-1] + arr1[head_index + 1:]
    ret = min(len(arr1) - head_index, head_index)
    ret = min(ret, head_index - len(arr2))
    return ret - 1

class ClosestTargetWordsTrie:
    __slots__ = 'arr', 'pnext', 'depth', 'min_depth', 'head_index', '_target', 'arr_head', 'arr_count', '_tail_index', 'arr_tail'

    def __init__(self, arr: List[str], target_word: str, start_index: int):
        self.arr = arr
        self.arr_head = arr[start_index]
        self.arr_count = self._set_arr_tail_index()
        self._target = (bisect.bisect_left(arr, target_word), target_word)
        self._init_stack()
        self.arr_tail = arr[self._tail_index]
        self.pnext = self._set_parent()
        self.depth = -1
        self.min_depth = float('inf')
        self.head_index = start_index
        self._run()

    def _init_stack(self):
        i = 1
        while True:
            if self.arr[self.arr[i]] == self._target[1]:
                break
            i += 1
            if self.arr[i] == self._target[0]:
                return
        self.arr = self.arr[i + 1:]
        self.arr.append(self._target[1])
        self.arr_count = self._set_arr_tail_index()
        self.arr_tail = self.arr[self._tail_index]

    def _run(self):
        self._move_till(self.pnext)

    def _set_arr_tail_index(self):
        i = 0
        for i in range(len(self.arr)):
            # wrap around when we find the start of t HiFi words
            if self.arr[~i] != self._target[1]:
                return i
        return 0

    def _set_parent(self):
        low = 0
        high = self.arr_count - 1
        while True:
            mid = (low + high) // 2
            if self.pnext(mid) == self._target[0]:
                return mid
            if self.arr[self.pnext(mid)] == self._target[1]:
                return self.pnext(mid)
