def maximumFrequency(S: str) -> str:
    # Split the sentence into words
    words = S.split()

    # Dictionary to store frequency of each word
    frequency = {}

    # First pass: count the frequency of each word
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    # Initialize variables to track the maximum frequency word
    max_freq_word = words[0]
    max_freq = frequency[max_freq_word]

    # Second pass: find the word with the highest frequency that appears first
    for word in words:
        if frequency[word] > max_freq:
            max_freq_word = word
            max_freq = frequency[word]

    # Return the result as a string
    return f"{max_freq_word} {max_freq}"

