def parallel_orthogonal():
	xy = map(int, readline().split())
	(p0, p1, p2, p3) = [x + y * 1j for (x, y) in zip(*[xy] * 2)]
	if 0 == dot(p1 - p0, p3 - p2):
		return 1
	if 0 == cross(p1 - p0, p3 - p2):
		return 2
	return 0

def dot(a, b):
	return a.real * b.real + a.imag * b.imag

def cross(a, b):
	return a.real * b.imag - a.imag * b.real
