import math

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 2 if i * i != n else 1
    return count

def phi_function(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def get_shichi_go_numbers_count(n):
    perfect_n_divisors = 1
    n_phi = phi_function(n)

    for p in prime_factors(n_phi):
        prime_power = 1
        while n_phi % p == 0:
            n_phi //= p
            prime_power *= p

        perfect_n_divisors *= (prime_power + 1)

    return count_divisors(perfect_n_divisors) - 75

def prime_factors(n):
    factors = []
    # Count the number of 2s that divide n
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    for i in range(3, int(math.sqrt(n)) + 1, 2):
        # Count the number of odd primes that divide n
        while n % i == 0:
            factors.append(i)
            n //= i

    # Handle the case where n is a prime number greater than 2
    if n > 2:
        factors.append(n)

    return factors

