def max_sum_of_digits_product(arr):
    max_sum_digits = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            product = arr[i] * arr[j]
            sum_digits = sum_of_digits(product)
            max_sum_digits = max(max_sum_digits, sum_digits)
    return max_sum_digits

