class Solution {
public:
    int maxDiff(int num) {
        vector<int> v;
        while (num) {
            v.push_back(num % 10);
            num /= 10;
        }
        int x = 9, y = 9, a = 0, b = 0;
        for (int i = v.size() - 1; i >= 0; --i) {
            if (v[i] != 9) {
                x = v[i];
                break;
            }
        }
        for (int i = v.size() - 1; i >= 0; --i) {
            a *= 10;
            if (v[i] != x)
                a += v[i];
            else
                a += y;
        }
        x = 0;
        for (int i = v.size() - 1; i >= 0; --i) {
            if (i == v.size() - 1 && v[i] != 1) {
                x = v[i];
                y = 1;
                break;
            }
            if (i != v.size() - 1 && v[i] != 1) {
                x = v[i];
                y = 0;
                break;
            }
        }
        if (x == 0) {
            for (int i = v.size() - 1; i >= 0; --i) {
                if (i != v.size() - 1 && v[i] != 0 && v[i] != 1) {
                    x = v[i];
                    y = 0;
                    break;
                }
            }
        }
        for (int i = v.size() - 1; i >= 0; --i) {
            b *= 10;
            if (v[i] != x)
                b += v[i];
            else
                b += y;
        }
        //cout << a << " " << b << endl;
        return a - b;
    }
};

