vector<int> solve(vector<int>& a) {
	vector<int> v(a.size());
	for (int m = 1, p; m < v.size(); p == 2 * p ? p = p / 2 : (p += p, m = m * 2)) {
		int c = max(p, m) * 2;
		memset(v.data(), 0, sizeof(int) * v.size());
		for (int i = 0; i < a.size(); i++) v[(i < c && !(i % p) ? i + i : i - p) % c] ^= a[i];
	}
	return v;
}

