	q = []
	for (i, a) in enumerate(A):
		while q:
			(j, b) = q[-1]
			if a - b > i - j:
				q.pop()
			else:
				break
		q.append((i, a))
	pos = 0
	for (i, a) in enumerate(A):
		while pos < len(q) and q[pos][0] <= i:
			pos += 1
		if pos == len(q):
			break
		(j, b) = q[pos]
		if b - a >= j - i + 1:
			return (i + 1, j + 1)
	return (-1, -1)
