        for i in range(1, len(arr)):
            arr[i] += arr[i - 1]
        if arr[k] >= limit:
            return False
        return True

    low, high = 1, n - 1
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            high = mid - 1
        else:
            low = mid + 1
    print(low)

