@lru_cache()
def pentabonacci(n):
	return n if n in (0, 4) else 1 if n in (1, 2) else 2 if n == 3 else sum((pentabonacci(n - k) for k in range(1, 6)))

def count_odd_pentaFib(n):
	return sum((1 for i in range(n + 1) if pentabonacci(i) % 2)) - (1 if n > 1 else 0)

class Solution:

	def calc(self, h, cost, value, maxi, n):
		import sys
		if value < 1 or value > maxi:
			return sys.maxsize
		ans = 0
		for i in range(n):
			ans += abs(h[i] - value) * cost[i]
		return ans

	def Bsearch(self, n, h, cost):
		low = 1
		maxi = max(h)
		high = maxi
		import sys
		ans = sys.maxsize
		while low <= high:
			mid = low + (high - low) // 2
			mid_ans = self.calc(h, cost, mid, maxi, n)
			left_ans = self.calc(h, cost, mid - 1, maxi, n)
			right_ans = self.calc(h, cost, mid + 1, maxi, n)
			if mid_ans < left_ans and mid_ans < right_ans:
				ans = min(ans, mid_ans)
				return ans
			elif left_ans < mid_ans:
				ans = min(ans, left_ans)
				high = mid - 1
			else:
				ans = min(ans, right_ans)
				low = mid + 1
		return ans

