            change(0, 0, 0, 1, 1, 0);
        } else if (a[0][0] + a[0][1] == 2) {
            change(0, 0, 1, 0, 1, 1);
            change(0, 1, 1, 0, 1, 1);
        } else if (a[0][0] + a[1][0] == 2) {
            change(0, 0, 0, 1, 1, 1);
            change(1, 0, 0, 1, 1, 1);
        } else if (a[1][0] + a[0][1] == 2) {
            change(1, 0, 0, 0, 1, 1);
            change(0, 1, 0, 0, 1, 1);
        } else if (a[0][0] == 1) {
            change(0, 0, 0, 1, 1, 0);
            change(0, 0, 0, 1, 1, 1);
