MOD = 998244353

def power(x, k):
    if k == 0:
        return 1
    if k % 2 == 1:
        return (x * power(x, k - 1)) % MOD
    else:
        y = power(x, k // 2)
        return (y * y) % MOD

def main():
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = (fact[i - 1] * (N - i + 1)) % MOD
    C = [[0] * (N + 2) for _ in range(N + 2)]
    for i in range(N + 2):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
    prob = [0] * (N + 1)
    prob[0] = 1
    themArtab = [0] * (N + 1)
    for k in range(1, N + 1):
        themArtab[k] = (power(fact[k], MOD - 2) * binomial(N - k + 1, k)) % MOD
        for last Town in range(2 * k - 1):
            if C[N - last Town][k - 1] != 0:
                art = (themArtab[k] * power(2, MOD - 2 * N + last Town)) % MOD * C[N - last Town][k - 1] % MOD
                prob[last Town] = (prob[last Town] + art) % MOD
    answer = (prob[N] * 2) % MOD
    if answer == 0: answer = 1
    return answer

