			ans.pb(i+1);

			rep(j,0,i+1) s[j] ^= 1;

			reverse(s.begin(), s.begin()+i+1);

		}

	}

	assert(len(ans) <= 2*n);

	assert(s==t);

	cout << len(ans) << ' ';

	for (auto e : ans) cout << e << ' ';

	cout << endl;

