Count the number of returnable rooms in the given snake exhibition.

-----Note-----

In the first test case, all rooms are returnable except room $2$. The snake in the room $2$ is trapped and cannot exit. This test case corresponds to the picture from the problem statement.

 In the second test case, all rooms are returnable by traveling on the series of clockwise belts.
```python
def count_returnable_rooms(n, s):
    if n == 2:
        return 1 if s == '-><-' else 0

    clockwise = [i for i in range(n) if s[i] == '>']
    anticlockwise = [i for i in range(n) if s[i] == '<']
    off = [i for i in range(n) if s[i] == '-']

    if not clockwise and not anticlockwise and not off:
        return n

    returnable = set()
    for i in range(n):
        if s[i] == '-':
            continue
        if s[i] == '>':
            j = (i + 1) % n
            while s[j] == '<':
                if j in returnable:
                    break
                returnable.add(j)
                k = (j - 1) % n
                while s[k] == '<':
                    if k in returnable:
                        break
                    returnable.add(k)
                    j = k
                    k = (k - 1) % n
                j = k
            if s[j] == '-':
                returnable.add(j)
        else:
            j = (i + 1) % n
            while s[j] == '>':
                if j in returnable:
                    break
                returnable.add(j)
                k = (j - 1) % n
                while s[k] == '>':
                    if k in returnable:
                        break
                    returnable.add(k)
                    j = k
                    k = (k - 1) % n
                j = k
            if s[j] == '-':
                returnable.add(j)

    return len(returnable)

def solve():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        s = input()
        results.append(count_returnable_rooms(n, s))
    for result in results:
        print(result)

