namespace big
{
	ll C(ll n,ll m)
	{
		if(n<m||m<0||n<0)return 0;
		ll tt=1;
		for(int i=1;i<=m;i++)
			tt*=(n-i+1),tt%=mod;
		for(int i=1;i<=m;i++)
			tt*=ksm(i,mod-2),tt%=mod;
		return tt;
	}
	void solve()
	{
		ll tt=0;
		for(int i=1;i<=m;i++)
			if(s[i]=='0')tt+=(1ll<<(i-1));
		ll ans=0;
		ll ct=__builtin_popcountll(tt);
		for(int i=0;i<=ct;i++)
		{
			ll nw=1;
			ll gs=C(ct,i);
			for(int j=1;j<=n;j++)
			{
				if(e[j].p>=m)
					nw*=e[j].p-m+i,nw%=mod;
			}
			ans+=1ll*(((ct-i)&1)?mod-1:1)*nw%mod*gs,ans%=mod;

		}
		ll other=1;
		for(int i=1;i<=n;i++)other*=ksm(e[i].p,e[i].q-1),other%=mod;
		cout<<1ll*ans*other%mod<<"\n";
		exit(0);
	}
}

