			tt*=(n-i+1),tt%=mod;
		for(int i=1;i<=m;i++)
			tt*=ksm(i,mod-2),tt%=mod;
		return tt;
	}
	ll St[80][80];
	int lim;
	ll num[80];
	//aaaa 很好哇！这个siz非常的小！！！！
	void dfs(int x,ll S)
	{
		if((tt&S)!=S)return;
		if(x==lim)
		{
			//mp[S]=1;
			num[__builtin_popcountll(S)]++;
			return;
		}
		for(int j=0;j<e[x].p;j++)
			dfs(x+1,S|St[x][j]);
	}
	void solve()
	{
		for(int i=1;i<=m;i++)
			if(s[i]=='0')tt+=(1ll<<(i-1));
		sort(e+1,e+n+1,[&](const nod&A,const nod&B){return A.p<B.p;});
		lim=n+1;
		for(int i=1;i<=n;i++)
		{
			if(e[i].p>=m)
			{
				lim=i;
				break;
			}
		}
		for(int i=1;i<lim;i++)
		{
			for(int j=0;j<e[i].p;j++)
			{
				for(int k=j;k<m;k+=e[i].p)
					St[i][j]|=(1ll<<k);
			}
		}
		dfs(1,0);
		//cerr<<mp.size()<<"$$\n";
		ll ans=0;
		ll tct=__builtin_popcountll(tt);
		for(int i=0;i<=tct;i++)
		{
			ll nw=1;
			for(int j=1;j<=n;j++)
			{
				if(e[j].p>=m)
					nw*=e[j].p-m+i,nw%=mod;
			}
			//求一个 sigma 
			ll sigm=0;
			for(int j=0;j<=i;j++)
				sigm+=C(tct-j,i-j)*num[j]%mod,sigm%=mod;
			ans+=1ll*(((tct-i)&1)?mod-1:1)*nw%mod*sigm,ans%=mod;
		}
		ll other=1;
		for(int i=1;i<=n;i++)other*=ksm(e[i].p,e[i].q-1),other%=mod;
		cout<<1ll*ans*other%mod<<"\n";
		exit(0);
	}
