import sys


def solve(s, t):
    if len(s) != len(t):
        return False
    letter_dict = collections.defaultdict(int)
    for letter in s:
        letter_dict[letter] += 1
    for letter in t:
        letter_dict[letter] -= 1
    for letter_count in letter_dict.values():
        if letter_count != 0:
            return False
    return True


