parent = {-1, -1, -1, ...}
    def find(self, i):
        if self.parent[i] < 0:
            return i
        else:
            self.parent[i] = self.find(self.parent[i])
            return self.parent[i]
    def union(self, i, j):
        x, y = self.find(i), self.find(j)
        if x == y:
            return
        if x < y:
            self.parent[y] = x
        else:
            self.parent[x] = y
    def kruskals(self):
        while self.count > 1:
            i, j, w = self.moves.pop(0)
            if self.find(i) != self.find(j):
                print(f"Connection: {w} for points {i:d}, {j:d}")
                self.union(i, j)
                self.moves.append((i, j, w))

    def minimHeap(self, values, args):
        for i, j, w in values:
            args.append([w, [i, j]])
        heapq.heapify(args)


class Solution:
    def minCostConnectPoints(self, rslt: List[List[int]]) -> int:

        rslt = sorted(rslt)
        h = DSU()
        p = [(0, rslt.pop(0))]
        m = 0

        while len(rslt) > 0:
            if len(p) == 1 and p[0][0] != -1:
                m += p.pop()
            if m == p[0][0] and len(p) > 1: 
                heapq.heappop(p)
                m += p.pop()[0]
            new_rslt = h.minimHeap(rslt, p.copy())
            rslt.clear()
            rslt.extend(new_rslt)

        return m

