# Solution
def solve():
    a, b, c = map(int, input().split())
    m = int(input())

    usb_price = []
    ps2_price = []

    for _ in range(m):
        val, port = input().split()
        val = int(val)
        if port == 'USB':
            usb_price.append(val)
        else:
            ps2_price.append(val)

    usb_price.sort()
    ps2_price.sort()

    total_cost = 0
    equipped_computers = 0

    usb_index = 0
    ps2_index = 0

    while usb_index < len(usb_price) and ps2_index < len(ps2_price):
        if a > 0:
            equipped_computers += 1
            a -= 1
            total_cost += usb_price[usb_index]
            usb_index += 1
        elif b > 0:
            equipped_computers += 1
            b -= 1
            total_cost += ps2_price[ps2_index]
            ps2_index += 1
        else:
            break

    while usb_index < len(usb_price):
        if c > 0:
            equipped_computers += 1
            c -= 1
            total_cost += usb_price[usb_index]
            usb_index += 1
        else:
            break

    while ps2_index < len(ps2_price):
        if c > 0:
            equipped_computers += 1
            c -= 1
            total_cost += ps2_price[ps2_index]
            ps2_index += 1
        else:
            break

    return str(equipped_computers) + ' ' + str(total_cost)

