def solve2():
	n = int(input())
	A = [int(char) for char in input().split()]
	B = [int(char) for char in input().split()]
	A_pos = {a: i for (i, a) in enumerate(A)}
	Bs = sorted([(b, i) for (i, b) in enumerate(B)])
	Bmin = [i for (b, i) in Bs]
	for i in range(n - 2, -1, -1):
		Bmin[i] = min(Bmin[i + 1], Bmin[i])
	ans = 2 * (n - 1)
	for i in range(n):
		odd_num = 2 * i + 1
		ans = min(ans, A_pos[odd_num] + Bmin[i])
	return ans
