def mctFromLeafValues(arr):
    dp = [[float('inf')] * len(arr) for _ in range(len(arr))]
    stack = []

    for i in range(len(arr)):
        while stack and arr[stack[-1]] <= arr[i]:
            index = stack.pop()
            dp[index][i] = min(dp[index][i], arr[i] * arr[stack[-1]] if stack else arr[i])
        stack.append(i)

    for i in range(1, len(arr)):
        for j in range(len(arr) - i):
            left, right = j, j + i
            for k in range(left, right):
                dp[left][right] = min(dp[left][right], dp[left][k] + dp[k + 1][right])

    return dp[0][-1]

