class circleQueue:
    def __init__(self):
        self.queue = []
        self.maxsize = len(self.queue)
    def enQueue(self,item):
        if((self.maxsize+1)/self.maxsize)!=1:
            return
        else:
            self.queue.append(item)
    def deQueue(self):
        self.queue.pop(0)
    def size(self):
        return len(self.queue)

class MyThread(threading.Thread):
    def __init__(self, Qt, threadName, Pros):
        threading.Thread.__init__(self)
        self.Qt = Qt
        self.threadname = threadName
        self.queue = Pros
        self.exit = False
    def run(self):
        while True:
            if self.exit:
                break
            for pros in range(self.queue.qsize()):
                time.sleep(0.1)
                while (self.queue.size()+1)/self.queue.size()!=1:
                    if self.exit:
                        break
                else:
                    self.Qt.acquire()
                    for pros in range(self.queue.size()):
                        print('*',end='')
                        self.queue.deQueue()
                    print('\n---count---:'+threading.current_thread().getName())

