def find_smallest_pretty_int(a, b):
    # Initialize the smallest number to a large value
    smallest_number = float('inf')

    # Helper function to check if a number contains at least one digit from list `a`
    def contains_digit_from_list_a(number):
        return any(digit in a for digit in str(number))

    # Helper function to check if a number contains at least one digit from list `b`
    def contains_digit_from_list_b(number):
        return any(digit in b for digit in str(number))

    # Iterate over all possible combinations of digits from lists `a` and `b`
    for digit_from_a in a:
        for digit_from_b in b:
            # Combine the digits to form a potential "pretty" number
            potential_number = int(str(digit_from_a) + str(digit_from_b))
            # If the potential number is smaller and satisfies the "pretty" condition, update `smallest_number`
            if potential_number < smallest_number and contains_digit_from_list_a(potential_number) and contains_digit_from_list_b(potential_number):
                smallest_number = potential_number

    # Return the smallest pretty number found
    return smallest_number if smallest_number != float('inf') else 0

