class Solution {
    unordered_map<string, vector<TreeNode*> > ht;
    vector<TreeNode *> results;

    string preorder_encode(TreeNode* root) {
        if (root == NULL) return "null ";
        else {
            string s = to_string(root->val) + ' ';
            s += preorder_encode(root->left);
            s += preorder_encode(root->right);
            // cout << s << endl;

            if (ht[s].size() == 1) results.push_back(root);
            ht[s].push_back(root);
            return s;
        }
    }

public:
    vector<TreeNode*> findDuplicateSubtrees(TreeNode* root) {
        preorder_encode(root);
        return results;
    }
};

