from collections import deque

def can_build_diamond(queue):
    '''
    >>> queue = deque([1, 3, 5, 7, 9, 10])
    >>> can_build_diamond(queue)
    YES

    >>> queue = deque([4, 3, 2, 1, 8, 9])
    >>> can_build_diamond(queue)
    NO
    '''
    top = float('inf')

    while queue:
        lft = queue[0]
        rgt = queue[-1]
        if rgt >= lft:
            popped = queue.pop()
        else:
            popped = queue.popleft()

        if popped <= top:
            top = popped

        else:
            print('NO')
            break

    else:
        print('YES')

