import heapq

class Node:

	def __init__(self, x):
		self.data = x
		self.next = None

	def __lt__(self, nxt):
		return self.data < nxt.data

class Solution:

	def mergeKLists(self, arr, K):
		try:
			min_heap = []
			idx = 0
			for i in range(K):
				heapq.heappush(min_heap, (arr[i].data, idx, arr[i]))
				idx += 1
			new_head = new_tail = None
			while min_heap:
				(data, _, node) = heapq.heappop(min_heap)
				if new_head is None:
					new_head = node
					new_tail = node
				else:
					new_tail.next = node
					new_tail = node
				if node.next:
					idx += 1
					heapq.heappush(min_heap, (node.next.data, idx, node.next))
			new_tail.next = None
			return new_head
		except Exception as e:
			print('Error: ', e)

