class Solution:
    def alertNames(self, keyName: List[str], keyTime: List[str]) -> List[str]:
        d = defaultdict(list)
        for n, t in zip(keyName, keyTime):
            h, m = map(int, t.strip().split(":"))
            d[n].append((h, m))
        res = set()
        for n, v in d.items():
            v.sort()
            for i in range(len(v)):
                for j in range(i + 1, min(i + 3, len(v))):
                    h1, m1 = v[i]
                    h2, m2 = v[j]
                    if h1 * 3600 + m1 >= h2 * 3600 + m2:
                        res.add(n)
                        break
        return sorted(res)

def count_substrings(commands):
    n = len(commands)
    count = 0

    for i in range(n):
        for j in range(i+1, n+1):
            moves = commands[i:j]
            up, right, down, left = 0, 0, 0, 0

            for cmd in moves:
                if cmd == 'U':
                    up += 1
                elif cmd == 'R':
                    right += 1
                elif cmd == 'D':
                    down += 1
                elif cmd == 'L':
                    left += 1

            if up == down and right == left:
                count += 1

    return count


