        while (l < h) {
            int mid = l + (h - l) / 2;
            if (valid(stations, mid, r, k)) {
                h = mid;
            } else {
                l = mid + 1;
            }
        }
        return maxNetworkPower(stations, l) + k;
    }

    private boolean valid(int[] stations, int len, int r, int k) {
        int balance = 0;
        for (int i = 0; i <= stations.length - len; i++) {
            balance += stations[i];
            if (i > r) {
                balance -= stations[i - r - 1];
            }
            if (balance < 0) {
                return false;
            }
            if (balance == 0 && k > 0) {
                k--;
            }
        }
        return k == 0;
    }

    private int maxNetworkPower(int[] stations, int len) {
        int maxNet = 0;
        for (int i = 0; i < stations.length - len + 1; i++) {
            int net = 0;
            for (int j = i; j < i + len; j++) {
                net += stations[j];
            }
            maxNet = Math.max(maxNet, net);
        }
        return maxNet;
    }
}

