def quickSort(tab, start, end): 
    if len(tab) <= 1: 
        return tab
    if start < end: 
        pivot = changeSort2(cardMin=tab[start], 
            cardMax=tab[end], n=len(tab))            
        itemsLeft, itemsRight = split(tab, 
            start, end, pivot)
        quickSort(tab, itemsLeft[0], itemsLeft[1])
        quickSort(tab, itemsRight[0], itemsRight[1])
        return (pivot, (itemsLeft, itemsRight))                
    return ()

def split(tab, start, end, pivot): 
    itemsLeft, itemsRight = (0, 0) 
    i = start 
    current, greaterValue = pivot 
    while i < end: 
        while i < end and current <= tab[i]: 
            if current > tab[i]: 
                greaterValue = tab[i]
            i += 1
        tab[i], tab[end] = tab[end], tab[i]
        itemsRight, itemsLeft = i, end 
        i += 1
        while i < end and tab[i] <= greaterValue: 
            i += 1
        tab[itemsRight], tab[i - 1] = tab[i - 1], tab[itemsRight]
        itemsRight = i
    return (start, itemsLeft, i), (i, itemsRight, end)

