    mod = 10**9 + 7
    dp = [[0] * (girls + 1) for _ in range(boys + 1)]

    for i in range(girls + 1):
        dp[0][i] = 1

    for b in range(1, boys + 1):
        for g in range(girls + 1):
            if g < b - 1:
                dp[b][g] = 0
            else:
                k = g
                while k >= 2 * b - 1:
                    dp[b][g] = (dp[b][g] + dp[b - 1][k + 1]) % mod
                    k -= 2

