from collections import defaultdict

def chu_liu_edmonds(vertices, edges, root):

    class Edge(object):
        def __init__(self, tail, head, weight):
            self.tail = tail
            self.head = head
            self.weight = weight

    def contract(edges, block):
        return [Edge(
            '0' if e.tail == block else e.tail,
            '0' if e.head == block else e.head,
            e.weight) for e in edges if (e.tail != block and e.head != block)]

    def merge(edges, cycle, new_node):
        return [Edge(
            e.tail if e.tail != cycle else new_node,
            e.head if e.head != cycle else new_node,
            e.weight) for e in edges]

    def shrink(vertices, edges, cycle):
        return [v for v in vertices if v != cycle], contract(edges, cycle)

    def reverse(cycles):
        return {v: min(
            (e for e in edges if e.head == v),
            key=lambda e: e.weight,
            default=None) for v in cycles}

    def duplicate(edges):
        return [Edge(e.tail, e.head, e.weight - weight) for e in edges for weight in (0, e.weight)]

    def expand(edges, cycle, node):
        return [Edge(e.tail if e.tail != node else cycle,
                     e.head if e.head != node else cycle,
                     e.weight) for e in edges]

