void solve() {
    int n, k;
    cin >> n >> k;

    if (k > n) {
        cout << -1 << endl;
        return;
    }

    vector<string> board(n, string(n, '.'));

    if (k == 1) {
        board[0][0] = 'R';
    } else {
        for (int i = 0; i < k; i++) {
            board[i][i] = 'R';
        }
        for (int i = 0; i < k - 1; i++) {
            if (board[i][i + 1] == 'R' || board[i + 1][i] == 'R') {
                cout << -1 << endl;
                return;
            }
        }
    }

    for (const auto& row : board) {
        cout << row << endl;
    }
}

