public class Main {
    static boolean testcase(int n) {
        int sum = 4; // Assuming the minimum sum is 4
        for (int i = 2; i < n; i++) {
            for (int j = i+1; j < n && j < i * j; j++) {
                int p = i;
                int q = j;
                // Verify if p and q are prime
                if (isPrime(p) && isPrime(q)) {
                    // Check if p * q is a nearly prime factor
                    if (p * q != n && (p*q <= n - sum)) {
                        // Subtract nearly prime sum and remaining from n
                        n -= p * q;
                        sum -= p * q;
                    }
                }
            }
        }
        // Check if the remaining value is 4 or less
        return (n <= 4);
    }

    static boolean isPrime(int num) {
        if (num <= 1) return false;
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        for (int i = 0; i < t; i++) {
            int n = sc.nextInt();
            if (testcase(n)) {
                System.out.println("YES");
//                Print the 4 numbers that make up the sum
                System.out.println(i + " " + (n - i * i - (i - 1)));
            } else {
                System.out.println("NO");
            }
        }
