class Solution:

	def removeOuter(self, S):
		if len(S) == 0 or S == '':
			return S
		count = 0
		ans = ''
		for ele in S:
			if ele == '(':
				if count != 0:
					ans += ele
				count += 1
			else:
				count -= 1
				if count != 0:
					ans += ele
		return ans

