MOD = 10**9 + 7

def count_results(A):
    n = len(A)
    dp = [0] * (n + 1)
    dp[1] = 1  # Dog 1 always starts the game

    for i in range(2, n + 1):
        if A[i-1] == 1:
            dp[i] = dp[i-1]
        else:
            dp[i] = (dp[i-1] + dp[i-2]) % MOD

    result = dp[n]
    for i in range(1, n + 1):
        if A[i-1] == 2 and i < n:
            result += dp[i-1] * dp[i+1] % MOD
            result %= MOD

    return result

def solve():
