class Solution {
public:
    vector<vector<int>> allCellsDistOrder(int R, int C, int r0, int c0) {
        int maxdis = r0 + c0;
        if (maxdis < r0+C-1-c0) {maxdis = r0+C-1-c0;}
        if (maxdis < R-1-r0+c0) {maxdis = R-1-r0+c0;}
        if (maxdis < R-1-r0+C-1-c0) {maxdis = R-1-r0+C-1-c0;}
        vector<vector<int>> output;
        for (int i=0;i<=maxdis;i++) {
            for (int j=0;j<=i;j++) {
                vector<int> temp(2);
                if (r0-j>= 0) {
                    temp[0]=r0-j;
                    if (c0-(i-j)>= 0) {
                        temp[1]=c0-(i-j);
                        output.push_back(temp);
                    }
                    if (c0-(i-j) != c0+(i-j) && c0+(i-j)<C) {
                        temp[1] = c0+(i-j);
                        output.push_back(temp);
                    }
                }
                if (r0-j != r0+j && r0+j < R) {
                    temp[0] = r0+j;
                    if (c0-(i-j)>= 0) {
                        temp[1]=c0-(i-j);
                        output.push_back(temp);
                    }
                    if (c0-(i-j) != c0+(i-j) && c0+(i-j)<C) {
                        temp[1] = c0+(i-j);
                        output.push_back(temp);
                    }
                }
            }
        }
        return output;
    }
