class Solution {
    private static final int MOD = 1_000_000_007;
    private int[][][] dp;
    private int[] digits;

    public int count(String num1, String num2, int min_sum, int max_sum) {
        int max = Math.max(max_sum, Math.max(num1.length(), num2.length()));
        dp = new int[num2.length() + 1][2][max * 9 + 1];
        digits = new int[num2.length() + 1];
        for (int i = 0; i < num2.length(); i++) {
            digits[i + 1] = num2.charAt(num2.length() - i - 1) - '0';
        }
        int res = solve(num2.length(), true, 0, min_sum, max_sum);
        if (!num1.equals("0")) {
            num1 = subtractOne(num1); // Subtract 1 from num1
            digits = new int[num1.length() + 1];
            for (int i = 0; i < num1.length(); i++) {
                digits[i + 1] = num1.charAt(num1.length() - i - 1) - '0';
            }
            res = (res - solve(num1.length(), true, 0, min_sum, max_sum) + MOD) % MOD;
        }
        return res;
    }

    private int solve(int index, boolean isEqual, int sum, int min_sum, int max_sum) {
        if (index == 0) {
            return sum >= min_sum && sum <= max_sum ? 1 : 0;
        }
        if (!isEqual && dp[index][isEqual ? 1 : 0][sum] != 0) {
            return dp[index][isEqual ? 1 : 0][sum] - 1;
        }
        int res = 0;
        for (int i = 0; i <= (isEqual ? digits[index] : 9); i++) {
            if (sum + i > max_sum) {
                break;
            }
            res = (res + solve(index - 1, isEqual && i == digits[index], sum + i, min_sum, max_sum)) % MOD;
        }
        if (!isEqual) {
            dp[index][isEqual ? 1 : 0][sum] = res + 1;
        }
        return res;
    }

    // Function to subtract 1 from a numeric string
    private String subtractOne(String num) {
        char[] arr = num.toCharArray();
        for (int i = arr.length - 1; i >= 0; i--) {
            if (arr[i] == '0') {
                arr[i] = '9';
            } else {
                arr[i]--;
                break;
            }
        }
        return arr[0] == '0' ? new String(arr, 1, arr.length - 1) : new String(arr);
    }
}

