class Solution:
    def distMoney(self, money: int, children: int) -> int:
        ans = -1
        for x in range(0, children+1):
            cur = x*8
            if cur > money:
                continue
            y = children - x
            if cur + y > money:
                continue
            if y == 1 and cur + 4 == money:
                continue
            if not y and cur != money:
                continue
            ans = x
        return ans

