class Solution(object):
    def ans(self, s, min_depth, max_depth):
        if s == '':
            return -1
        n = len(s)
        st = [-1]*n
        lft = 0
        for i in range(n):
            if s[i] == '(':
                lft += 1
            else:
                lft -= 1
            st[i] = lft
        st.append(0)
        mx = -10**9
        mn = 10**9
        res = -1
        for i in range(n+1):
            if st[i] < mn:
                mn = st[i]
                res = i
        for i in range(n):
            if st[i] == mn:
                if st[i+1] >= max_depth:
                    return [0]*n
                return self.ans(s[:i+1], mn+1, max_depth) + self.ans(s[i+1:], mn+1, max_depth)

    def generateSplit(self, seq):
        """
        :type seq: str
        :rtype: List[int]
        """
        lft = 0
        for i in range(len(seq)):
            if seq[i] == '(':
                lft += 1
            else:
                lft -= 1
            if lft == 0:
                return self.ans(seq[:i], 1, 1) + [0] + self.ans(seq[i+1:], 1, 1)

