public class StrangeHousingtimelimitpertest {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        BufferedOutputStream out = new BufferedOutputStream(System.out);
        for (int test = 1; test <= sc.nextInt(); test++) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            ArrayList<ArrayList<Integer>> adjacencyList = new ArrayList<ArrayList<Integer>>();
            for (int i = 0; i < n; i++) {
                adjacencyList.add(new ArrayList<Integer>());
            }
            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                adjacencyList.get(u).add(v);
                adjacencyList.get(v).add(u);
            }
            if (!canChoose(adjacencyList)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                System.out.println(n);
                for (int i = 0; i < n; i++) {
                    System.out.print(i + 1 + " ");
                }
                System.out.println();
            }
        }
    }

    private static boolean canChoose(ArrayList<ArrayList<Integer>> adjacencyList) {
        HashSet<Integer> houses = new HashSet<Integer>();
        for (int i = 0; i < adjacencyList.size(); i++) {
            if (adjacencyList.get(i).size() == 1) {
                return false;
            }
            if (adjacencyList.get(i).size() == 2) {
                houses.add(i);
            }
        }
        for (int i = 0; i < adjacencyList.size(); i++) {
            if (adjacencyList.get(i).size() == 2) {
                houses.add(adjacencyList.get(i).get(0));
                houses.add(adjacencyList.get(i).get(1));
            }
        }
        if (houses.size() == adjacencyList.size()) {
            return true;
        } else {
            return false;
        }
    }
}
