class Solution:
    def findMaxRow(self, mat, N):
        max_row = -1
        max_count = 0

        for i in range(N-1, -1, -1):
            count = 0
            for j in range(N):
                if mat[i][j] == 1:
                    count += 1
            if count > max_count:
                max_count = count
                max_row = i

        return [max_row, max_count]

