public class Education {



	public static void main(String[] args) {

		Kattio io = new Kattio();

		int t = io.nextInt();



		while (t --> 0) {

			int n = io.nextInt();

			int c = io.nextInt();



			int[] income = new int[n];

			for (int i = 0;i < n;i++) {

				income[i] = io.nextInt();

			}

			int[] upgrade = new int[n-1];

			for (int i = 0;i < n - 1;i++) {

				upgrade[i] = io.nextInt();

			}



			long minTime = (int) Math.ceil(1.0 * c / income[0]);

			long time = 0;

			long currCash = 0;

			for (int i = 1;i < n;i++) {

				time += (long) Math.ceil(1.0 * (upgrade[i-1]-currCash) / income[i-1]) + 1;

				currCash = (income[i-1] - (upgrade[i-1]-currCash) % income[i-1]) % income[i-1];

				long extraTime = (long) Math.ceil(1.0 * (c - currCash) / income[i]);

				minTime = Math.min(minTime, time + extraTime);

			}

			io.println(minTime);

		}

		io.close();

	}



	static class Kattio extends PrintWriter {

		private BufferedReader r;

		private StringTokenizer st;

		// standard input

		public Kattio() { this(System.in, System.out); }

		public Kattio(InputStream i, OutputStream o) {

			super(o);

			r = new BufferedReader(new InputStreamReader(i));

		}

		// USACO-style file input

		public Kattio(String problemName) throws IOException {

			super(problemName + ".out");

			r = new BufferedReader(new FileReader(problemName + ".in"));

		}

		// returns null if no more input

		public String next() {

			try {

				while (st == null || !st.hasMoreTokens())

					st = new StringTokenizer(r.readLine());

				return st.nextToken();

			} catch (Exception e) { }

			return null;

		}

		public int nextInt() { return Integer.parseInt(next()); }

		public double nextDouble() { return Double.parseDouble(next()); }

		public long nextLong() { return Long.parseLong(next()); }

	}



