class Solution {
public:
    vector<int> addNegabinary(vector<int>& arr1, vector<int>& arr2) {

        if (arr1.size() == 1 && arr2.size() == 1 && arr1[0] == 0 && arr2[0] == 0) {
            vector<int> res;
            res.push_back(0);
            return res;
        }

        int len = arr1.size();
        if (arr2.size() > len)
            len = arr2.size();

        vector<int> res, res2;

        int sign = 1;
        int cin = 0;

        for (int i = 0; i < len + 2; i++) {
            int p1 = arr1.size() - 1 - i;
            int p2 = arr2.size() - 1 - i;
            int n1 = 0;
            int n2 = 0;
            if (p1 >= 0)
                n1 = arr1[p1];
            if (p2 >= 0)
                n2 = arr2[p2];

            if (sign == 1) {
                int sum = n1 + n2 + cin;
                if (sum == -1) {
                    res.push_back(1);
                    cin = -1;
                }
                else {
                    res.push_back(sum % 2);
                    cin = (sum >= 2);
                }
            }
            else {
                int sum = cin - n1 - n2;
                if (sum == 1) {
                    res.push_back(1);
                    cin = 1;
                }
                else {
                    res.push_back((sum + 4) % 2);
                    if (sum <= -2) {
                        cin = -1;
                    }
                    else 
                        cin = 0;

                }   
            }
            sign = -sign;
        }

        bool leadingZero = true;

        for (int i = res.size() - 1; i >= 0; i--) {

            if (leadingZero && res[i] == 0)
                continue;
            else
                leadingZero = false;

            res2.push_back(res[i]);
        }

        if (res2.size() == 0)
            res2.push_back(0);

        return res2;

    }
