class Solution {
    public int numberWays(List<List<Integer>> hats) {

    	long ans=0;
    	int n=hats.size();
    	int mod=1000000007;
    	long[][] dp=new long[41][1<<n];

    	dp[0][0]=1;
    	for(int i=1;i<=40;i++) {
    		for(int k=0;k<(1<<n);k++)
    			dp[i][k]=dp[i-1][k];
    		for(int j=0;j<n;j++) {
    			if(hats.get(j).contains(i)) {
    				for(int k=0;k<(1<<n);k++) {
    					if(((k>>j)&1)!=0) continue;
    					dp[i][k|(1<<j)]=(dp[i][k|(1<<j)]+dp[i-1][k])%mod;
    				}
    			}
    		}
    	}

    	return (int)dp[40][(1<<n)-1];
    }
}

