def can_sort_by_operations(t, test_cases):
    results = []
    for arr in test_cases:
        sorted_arr = sorted(arr)
        if arr == sorted_arr:
            results.append("Yes")
            continue

        for i in range(len(arr) - 2):
            for j in range(i + 1, len(arr) - 1):
                for k in range(j + 1, len(arr)):
                    arr_copy = arr[:]
                    if arr_copy[i] > arr_copy[k]:
                        arr_copy[i] += arr_copy[j]
                    else:
                        arr_copy[j], arr_copy[k] = arr_copy[k], arr_copy[j]

                    if arr_copy == sorted_arr:
                        results.append("Yes")
                        break
                else:
                    continue
                break
            else:
                continue
            break
        else:
            results.append("No")

    return "\n".join(results)

