from typing import List, Tuple

def can_sort_array(arr: List[int]) -> str:
    positives, negatives = [], []
    for x in arr:
        (positives if x >= 0 else negatives).append(x)

    if len(positives) == 1 or len(negatives) == 1:
        return "YES"

    if positives[0] > -negatives[-1] or negatives[0] > positives[-1]:
        return "NO"

    return "YES"

def max_x_sortable(t, test_cases):
    def find_max_x(n, p):
        max_x = 0
        for x in range(n):
            visited = [False] * n
            for i in range(n):
                if not visited[p[i]]:
                    cycle = set()
                    j = p[i]
                    while not visited[p[j]]:
                        visited[p[j]] = True
                        cycle.add(p[j])
                        j = p.index(j & x)
                    if is_sortable(cycle):
                        max_x = x
        return max_x

    def is_sortable(cycle):
        return sorted(cycle) == list(cycle)

    results = []
    for n, p in test_cases:
        results.append(find_max_x(n, p))
    return results

