def find_divisible_pair(l, r):
    for y in range(l, r + 1):
        for x in range(1, y):
            if y % x == 0:  # Check if x divides y
                return x, y  # Found a suitable pair
    return None  # This line will never be reached given the problem statement guarantees a solution

def process_queries(T, queries):
    for l, r in queries:
        result = find_divisible_pair(l, r)
        if result:
            print(*result)

