class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long[] dp=new long[forget+1];
        dp[1]=1;
        long mod=1000000007;
        for(int i=2;i<=n;i++){
            long d=0;
            for(int j=forget;j>1;j--){

                dp[j]=dp[j-1]%mod;
                if(j>delay){
                    d+=dp[j];
                    d%=mod;
                }

            }
            dp[1]=d;
        }
        long sum=0;

        for(int i=1;i<=forget;i++){
            sum+=dp[i];
            sum%=mod;
        }
        sum%=mod;
        return (int)sum;

    }
}

