## Solution: def grasshopper_jump(n, directions, jumps):
    position = 0
    visited = set([0])
    while position >= 0 and position < n:
        jump_len = jumps[position]
        direction = directions[position]
        position += jump_len if direction == '>' else -jump_len
        if position in visited:
            return "FINITE"
        visited.add(position)
    return "INFINITE"

