class Solution:

	def getpath(self, root, val, path):
		if root == None:
			return False
		path.append(root.data)
		if root.data == val:
			return True
		if self.getpath(root.left, val, path) or self.getpath(root.right, val, path):
			return True
		path.pop()
		return False

	def findDist(self, root, a, b):
		path1 = []
		path2 = []
		self.getpath(root, a, path1)
		self.getpath(root, b, path2)
		while path1 and path2 and (path1[0] == path2[0]):
			path1.pop(0)
			path2.pop(0)
		return len(path1) + len(path2)

