def tm(n, t, k, d):
	when = False
	time = 0
	timed = 0
	while n > 0:
		if time >= d:
			when = True
		if when == True:
			if time % t == 0 and time != 0:
				n -= k
			if timed % t == 0 and timed != 0:
				n -= k
			timed += 1
		elif time % t == 0 and time != 0:
			n -= k
		if n <= 0:
			break
		time += 1
	return time

def tmn(n, t, k, d):
	when = False
	time = 0
	timed = 0
	while n > 0:
		if time >= d:
			when = True
		if time % t == 0 and time != 0:
			n -= k
		if n <= 0:
			break
		time += 1
	return time
if tm(n, t, k, d) < tmn(n, t, k, d):
