def find_smallest_period_string(t):
    n = len(t)
    # Check if the string t itself has a period of 1
    if t == '0' * n or t == '1' * n:
        return t

    # Check if the string t can be a subsequence of a string with period 2
    # Try to construct a string with period 2
    s = t[0]
    for i in range(1, n):
        if t[i] != t[i-1]:
            s += t[i]
        else:
            s += t[i-1]

    # If the constructed string s has a length greater than 2 * len(t), use the original t
    if len(s) > 2 * n:
        return t

    return s

