public class PekoraandTrampoline {



	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);



		int t = scan.nextInt();



		int n, nums[];

		long counter[];



		for (; t > 0; t--) {

			n = scan.nextInt();



			nums = new int[n];

			for (int i = 0; i < n; i ++) {

				nums[i] = scan.nextInt();

			}



			counter = new long[n];

			counter[0] = 0;



			for(int i = 0; i < n - 1; i++) {

				for(int j = 2; j <= nums[i] && (i + j) < n; j++) {

					counter[i + j] ++;

				}

				counter[i + 1] += Math.max(0, counter[i] - nums[i] + 1);

			}



			long res = 0;

			for (int i = 0; i < n; i++) {

				res += Math.max(0, nums[i] - counter[i] - 1);

			}



			System.out.println(res);

		}



		scan.close();

	}



