def maximizeTheCuts(self, n: int, x: int, y: int, z: int) -> int:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            if i >= x:
                dp[i] = max(dp[i], dp[i - x] + 1)
            if i >= y:
                dp[i] = max(dp[i], dp[i - y] + 1)
            if i >= z:
                dp[i] = max(dp[i], dp[i - z] + 1)
        return dp[n] if dp[n] > 0 else 0

