def fatorial(max):
	fatoriais = [1]
	for i in range(1, max):
		fatoriais.append(fatoriais[-1] * i)
	return fatoriais

def combinatoria(n, p):
	return fatoriais[n] // (fatoriais[n - p] * fatoriais[p])
