class Solution:

	def nextRight(self, root, key):
		q = collections.deque()
		q.append(root)
		while q:
			qLen = len(q)
			for i in range(qLen):
				cur = q.popleft()
				if not cur:
					continue
				if cur.data == key:
					return q[0] if i < qLen - 1 else Node(-1)
				if cur.left:
					q.append(cur.left)
				if cur.right:
					q.append(cur.right)
		return Node(-1)

