class Solution:

	def __init__(self):
		self.s = []
		self.g = []

	def insertHeaps(self, x):
		if len(self.s) == 0:
			heapq.heappush(self.s, -x)
			return
		if len(self.s) > len(self.g):
			if x < -self.s[0]:
				heapq.heappush(self.g, -heapq.heappop(self.s))
				heapq.heappush(self.s, -x)
			else:
				heapq.heappush(self.g, x)
		elif x < -self.s[0]:
			heapq.heappush(self.s, -x)
		else:
			heapq.heappush(self.g, x)
			heapq.heappush(self.s, -heapq.heappop(self.g))

	def getMedian(self):
		if len(self.s) == len(self.g):
			return float(-self.s[0] + self.g[0]) / 2
		else:
			return -float(self.s[0])

