def solve(n, s):
    counts = [0] * 26
    for i in range(n):
        counts[ord(s[i]) - ord('a')] += 1
        if i >= n // 2:
            counts[ord(s[i - n // 2]) - ord('a')] -= 1
        if max(counts) <= n // 2:
            return 'YES\n' + s[i - n // 2 + 1:i + 1]
    return 'NO'

