def is_t_prime(x):
    cnt = [0, 0]
    for i in range(1, int(x**(0.5)) + 1):
        if x % i == 0:
            if i*i != x:
                cnt[i%3]+=2
            else: cnt[0]+=1
            cnt[x//i%3]+=1
    return (cnt[0] == 3) and (cnt[1] == cnt[2] == 0)

