def check_berland_flag(field_dimensions, field):
    n, m = field_dimensions
    stripes_height = None

    # Check if all stripes have the same width and height
    for strip in field:
        if stripes_height is None:
            stripes_height = len(strip)
        elif len(strip) != stripes_height:
            return "NO"

    stripe_symbols = ['R', 'G', 'B']
    symbols_appearances = {symbol: [] for symbol in stripe_symbols}

    # Record appearances of symbols in consecutive stripes
    for i in range(n - 1):
        lower_strip, upper_strip = field[i], field[i + 1]
        for j in range(m):
            symbol_i, symbol_j = lower_strip[j], upper_strip[j]
            if j < m - 1:
                assert symbol_j == symbol_i  # Ensure the columns are parallel
            symbols_appearances[symbol_i].append(j)

    # Verify that each symbol appears exactly once in each column
    for column in range(m):
        column_values = [strip[column] for strip in field]
        if len(set(column_values)) != 1:
            return "NO"

    # No issues found, flag is a valid Berland flag
    return "YES"


