def matSearch(mat, N, M, X):
    # Start from the top-right corner of the matrix
    row = 0
    col = M - 1

    while row < N and col >= 0:
        if mat[row][col] == X:
            return 1
        elif mat[row][col] > X:
            col -= 1
        else:
            row += 1

    return 0

