class Solution:
    def calcPower(self, n: int) -> List[int]:
        ans = []
        while n > 0:
            m = n % 2
            n //= 2
            ans.append(m)
        return ans[::-1]

    def countPowers(self, n: int) -> List[int]:
        powcount = Counter(self.calcPower(n))
        ans = []
        for q in range(len(powcount) + 1):
            ans.append(powcount[0] if q == 0 else powcount[0] * powcount[
                1] * powcount[2])
            for i in range(3, q):
                ans[q - 1] = pow(ans[q - 1], 2)
                ans[q - 1] %= (10 ** 9 + 7)
        return ans

    def buildPowerSet(self, n: int) -> List[int]:
        ans = []
        binary = ''.join(str(i) for i in bin(n))[:1:-1]
        index = len(binary)
        cur = '0' * index
        while cur:
            ans.append(int(cur, 2))
            print(ans)
