        return ans


class Solution2:
    def countPowers(self, n: int) -> List[int]:
        # ans=1
        # for i in range(10):
        #     ans*=i%10
        #     ans%=10**9+7
        n=int(math.log(n,2))+1
        ans=[[x] for x in range(1<<n)]
        while ans:
            next=[]
            for i in ans:
                if(sum(i)>n):
                    next+=[j+i for j in i]
                else:
                    next+=[i]
            ans=next
        return [reduce(lambda x,y:(x*y)%(10**9+7),a) for a in ans]

