def rearrange(S, N):
    vowels = set('aeiou')
    vowels_list = []
    consonants_list = []

    # Separate vowels and consonants
    for char in S:
        if char in vowels:
            vowels_list.append(char)
        else:
            consonants_list.append(char)

    # Check if rearrangement is possible
    if len(vowels_list) != len(consonants_list):
        return "-1"

    # Create the arranged string
    arranged_string = ''
    for i in range(N):
        if i % 2 == 0:
            if vowels_list:
                arranged_string += vowels_list.pop(0)
            else:
                return "-1"
        else:
            if consonants_list:
                arranged_string += consonants_list.pop(0)

    return arranged_string

# Example usage:
S = "aeroplane"
N = len(S)
print(rearrange(S, N))  # Output: alanepero

S = "mississippi"
N = len(S)
print(rearrange(S, N))  # Output: -1

