import math

class Solution:

	def leastPrimeFactor(self, n):
		prime = [True] * (n + 1)
		for i in range(2, n + 1):
			if prime[i]:
				for j in range(i * i, n + 1, i):
					prime[j] = False
		res = []
		for i in range(1, n + 1):
			if prime[i]:
				res.append(i)
			elif i % 2 == 0:
				res.append(2)
			elif i % 3 == 0:
				res.append(3)
			else:
				for j in range(5, int(math.sqrt(i)) + 1, 6):
					if i % j == 0:
						res.append(j)
						break
					if i % (j + 2) == 0:
						res.append(j + 2)
						break
		res.append(0)
		return res

