// the number of good pairs
int Count(vector<int>& a, const int k) {
    int n = a.size();
    if (n == 0) return 0;
    auto cmp = [&k](const int& a, const int& b) -> bool {
        return abs(a - b) <= k; 
    };
    sort(a.begin(), a.end(), cmp);
    int res = 1;
    for (int i = 1; i < n; ++i) if (cmp(a[i - 1], a[i])) ++res;
    return res;
}
