class Solution:
  def minCapability(self, nums: List[int], k: int) -> int:
    def check(mi):
      @cache
      def dfs(i):
        if i >= n:
          return 0
        if nums[i] > mi:
          return dfs(i + 1)
        return max(dfs(i + 1), 1 + dfs(i + 2))

      return dfs(0) >= k

    n = len(nums)
    lo = -1
    hi = max(nums) + 1
    while lo + 1 < hi:
      mi = (lo + hi) // 2
      if check(mi):
        hi = mi
      else:
        lo = mi
    return hi

