class Solution:
    def lcaDeepestLeaves(self, root: TreeNode) -> TreeNode:
        def solve(node):
            if node is None:
                return node, 0
            lc, lh = solve(node.left)
            rc, rh = solve(node.right)
            if lh == rh:
                return node, lh + 1
            else:
                n = lc if lh > rh else rc
                return n, max(lh, rh) + 1
        n, h = solve(root)
        return n

def isdeadEnd(root):
	stack = [root]
	map1 = {}
	lnodes = []
	while stack:
		x = stack.pop(0)
		if x.data in map1:
			map1[x.data] += 1
		else:
			map1[x.data] = 1
		if x.right:
			stack.append(x.right)
		if x.left:
			stack.append(x.left)
		if x.left == None and x.right == None:
			lnodes += [x.data]
	lnodes.sort()
	for item in lnodes:
		if item == 1 and item + 1 in map1:
			return True
		elif item + 1 in map1 and item - 1 in map1:
			return True
	return False

from typing import Optional
from collections import deque

def tree(root, summ):
	if root == None:
		return 0
	l = tree(root.left, summ)
	r = tree(root.right, summ)
	if l + r + root.data > summ[0]:
		summ[0] = l + r + root.data
	return l + r + root.data

class Solution:

	def findLargestSubtreeSum(self, root: Optional['Node']) -> int:
		summ = [-1000000]
		tree(root, summ)
		return summ[0]

