function hasCycle(path: String): Boolean {
  var stack = []  // store the visited coordinates
  var x = 0, y = 0

  for each character c in path:
    if c == 'N': y++
    if c == 'S': y--
    if c == 'E': x++
    if c == 'W': x--
    location = (x, y)  // current location

    if location is in the stack:
      return true
    // add the location to the stack
    stack.push(location)
  return false
}

class Solution:
    def countBadPairs(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            nums[i]-=i
        dic = {}
        for x in nums:
            if x not in dic:
                dic[x] = 0
            dic[x]+=1
        res = 0
        for k in dic:
            v = dic[k]
            if v>1:
                neo = v*(v-1)//2
                res+=neo

        return n*(n-1)//2-res

