def candy_exchange(a, b):
    turn = 0
    while True:
        if turn % 2 == 0:
            if a >= turn // 2 + 1:
                a -= turn // 2 + 1
                b += turn // 2 + 1
            else:
                return "Vladik"
        else:
            if b >= turn // 2 + 1:
                b -= turn // 2 + 1
                a += turn // 2 + 1
            else:
                return "Valera"
        turn += 1

