using ModInt = MInt<MOD>;

template <typename CostType>
struct Edge {
  int src, dst; CostType cost;
  Edge(int src, int dst, CostType cost = 0) : src(src), dst(dst), cost(cost) {}
  inline bool operator<(const Edge &x) const {
    return cost != x.cost ? cost < x.cost : dst != x.dst ? dst < x.dst : src < x.src;
  }
  inline bool operator<=(const Edge &x) const { return !(x < *this); }
  inline bool operator>(const Edge &x) const { return x < *this; }
  inline bool operator>=(const Edge &x) const { return !(*this < x); }
};

class Solution {
public:
    int countPaths(int n, vector<vector<int>>& roads) {
        vector<vector<Edge<int>>> graph(n);
        for (const vector<int> &road : roads) {
          const int u = road[0], v = road[1], time = road[2];
          graph[u].emplace_back(u, v, time);
          graph[v].emplace_back(v, u, time);
        }
        vector<ll> dist(n, LINF);
        dist[0] = 0;
        vector<ModInt> dp(n, 0);
        dp[0] = 1;
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
        que.emplace(dist[0], 0);
        while (!que.empty()) {
          auto [cost, city] = que.top(); que.pop();
          if (cost > dist[city]) continue;
          for (const Edge<int> &e : graph[city]) {
            if (dist[e.dst] > cost + e.cost) {
              dist[e.dst] = cost + e.cost;
              que.emplace(dist[e.dst], e.dst);
              dp[e.dst] = dp[city];
            } else if (dist[e.dst] == cost + e.cost) {
              dp[e.dst] += dp[city];
            }
          }
        }
        return dp[n - 1].val;
    }
};

