using namespace std;

int countSets(int n, int maxDistance, vector<vector<int>>& roads) {
    vector<vector<pair<int, int>>> graph(n);
    for (const auto& road : roads) {
        graph[road[0]].emplace_back(road[1], road[2]);
        graph[road[1]].emplace_back(road[0], road[2]);
    }

    int result = 0;
    for (int bitmask = 0; bitmask < (1 << n); ++bitmask) {
        bool isValid = true;
        for (int i = 0; i < n && isValid; ++i) {
            if ((bitmask & (1 << i))!= 0) continue;
            vector<int> distances(n, -1);
            distances[i] = 0;
            queue<int> q;
            q.push(i);
            while (!q.empty()) {
                int node = q.front();
                q.pop();
                for (const auto& neighbor : graph[node]) {
                    if ((bitmask & (1 << neighbor.first)) == 0 && distances[neighbor.first] == -1 && distances[node] + neighbor.second <= maxDistance) {
                        distances[neighbor.first] = distances[node] + neighbor.second;
                        q.push(neighbor.first);
                    }
                }
            }
            for (int j = 0; j < n && isValid; ++j) {
                if ((bitmask & (1 << j)) == 0 && distances[j] == -1) {
                    isValid = false;
                    break;
                }
            }
        }
        if (isValid) ++result;
    }
    return result;
}
