def profit(n, m, l, s, c):
    cost = [0] * (m + 1)
    profit = [0] * (m + 1)
    for i in range(n):
        cost[l[i]] += s[i]
        profit[l[i]] += c[l[i]]
    profit_dict = {}
    current_profit = 0
    for i in range(1, m + 1):
        if i in profit_dict:
            current_profit -= cost[i]
        else:
            current_profit += profit[i] - cost[i]
            profit_dict[i] = profit[i] - cost[i]
    max_profit = current_profit
    for i in range(1, m):
        if profit[i] > profit[i + 1] and cost[i] < cost[i + 1]:
            max_profit = max(max_profit, profit_dict[i])
    return max_profit


