class PlasticBlocks:
    def __init__(self, maxRange=1000):
        self.size       = maxRange                     # maximum index to explore
        self.unpack()
        self.calculated = [0]*4*self.size
        self.result     = [0]*(self.size+1)

    def calc(self, blockA, blockB):
        # Read
        if self.calculated[blockA]  == 0:
            self.result[blockA] = self.calc(blockA-1, max(blockA-1,blockB))+1
        if self.calculated[blockB]  == 0:
            self.result[blockB] = self.calc(blockB-1, max(blockA-1,blockB))-1
        # Write
        self.calculated[self.result[blockA]-self.result[blockB]] = 1
        return self.result[self.result[blockA]-self.result[blockB]]

    def unpack(self):
        # Solving
        self.result[0] = 1
        for result in self.result[1:self.size+1]:
            self.result[result] = result
            for blockA, blockB in product(range(result),range(max(0,result-1))):
                # Check same number
                if blockA == blockB:
                    continue
                # Calculate results
                self.result[result] = min(
                    self.calc(blockA, blockB),
                    self.result[result]
                )

