class Solution:
    def numRescueBoats(self, people, limit):
        """
        :type people: List[int]
        :type limit: int
        :rtype: int
        """
        fat, thin = [], []
        for val in people:
            if val > limit/2:
                fat.append(val)
            else:
                thin.append(val)
        if len(thin) ==0:
            return len(fat)
        if len(fat) == 0:
            return len(thin)//2 + (1 if len(thin)%2 != 0 else 0)
        fat = sorted(fat, reverse=True)
        thin = sorted(thin)
        result, fi, ti = 0, 0, 0
        while fi < len(fat) and ti < len(thin):
            if fat[fi] + thin[ti] <= limit:
                fi, ti = fi +1 , ti+1
            else:
                fi+=1
            result += 1
        if fi < len(fat):
            result += len(fat) - fi
        if ti < len(thin):
            rest = len(thin) - ti
            result += rest//2 + (1 if rest%2 != 0 else 0)
        return result

