def findMaxLen(S):
    stack = []
    max_len = 0
    for i, c in enumerate(S):
        if c == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()
            if not stack:
                max_len = max(max_len, i - 0 + 1)
            else:
                max_len = max(max_len, i - stack[-1] + 1)
    return max_len

