def solve(s, c):
    """
    s: Jeff's product name
    c: Jeff's competitor's product name
    """
    # print(s, c)
    if s > c:
        return s

    if s == c:
        return "---"

    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] > s[j]:
                s = s[:i] + s[j] + s[i + 1:j] + s[i] + s[j + 1:]
                if s < c:
                    return s
                else:
                    s = s[:i] + s[j] + s[i + 1:j] + s[i] + s[j + 1:]

    return "---"


