def calculate_scores(serve_records):
    results = []
    for record in serve_records:
        score_a = 0
        score_b = 0
        for serve in record:
            if serve == 'A':
                score_a += 1
            else:
                score_b += 1
            if score_a >= 11 and score_a - score_b >= 2:
                break
            if score_b >= 11 and score_b - score_a >= 2:
                break
        results.append((score_a, score_b))
    return results

def main():
    import sys
    input = sys.stdin.read
    data = input().strip().split('\n')

    results = []
    for record in data:
        if record == '0':
            break
        results.append(calculate_scores([record])[0])

    for score_a, score_b in results:
        print(f"{score_a} {score_b}")

if __name__ == "__main__":
