class Solution {
public:
    int minimumDeletions(string s) {
        int a = 0, b = 0;
        int ans = INT_MAX;
        for (int i = 0; i < s.size(); i++) {
            if (s[i] == 'a')
                continue;
            else
                a++;
        }

        for (int j = 0; j < s.size(); j++) {
            if (s[j] != 'b')
                continue;

            while (a && s[b] != 'a')
                b++;

            if (b >= s.size())
                break;

            if (s[b] == 'a')
                a--;

            b++;
        }

        for (int i = b; i < s.size(); i++) {
            if (s[i] != 'b')
                continue;
            ans = min(ans, b);
            b++;
        }

        return min(ans, b);
    }
};
