class Solution {
public:
    int maxWidthRamp(vector<int>& nums) {
		vector<pair<int, int>> sortedIndexsPairs; // key: number, value: indx of this number
		int foundIndex = -1;
		int maxLenght = 0;
    	for(int i = 0; i < nums.size(); i++) {
			sortedIndexsPairs.push_back({ nums[i], i });
		}
		sort(begin(sortedIndexsPairs), end(sortedIndexsPairs));

		for(int i = 0; i < sortedIndexsPairs.size(); i++) {
			auto p = sortedIndexsPairs[i];
			if (foundIndex > p.second) continue;
			foundIndex = p.second; 
			auto delta = (long) (foundIndex - p.second);
			if (maxLenght < delta) maxLenght = delta;
		}

        return (int) maxLenght;
    }
};
