class Solution:
    def successfulPairs(self, spells: List[int], potions: List[int], success: int) -> List[int]:
        potions.sort()

        n = len(potions)
        ans = []

        for x in spells:
            left = 0
            right = n-1
            pos = -1
            while(left <= right):
                mid = (left + right) // 2
                if(x * potions[mid] >= success):
                    pos = mid
                    right = mid - 1
                else:
                    left = mid + 1
            if(pos == -1):
                ans.append(0)
            else:
                ans.append(n - pos)

        return ans

