class Solution:

	def shipWithinDays(self, weights: List[int], D: int) -> int:

		def days_taken(capacity, arr):
			days = 0
			i = 0
			while i < len(arr):
				j = i
				bucket = capacity
				days += 1
				while j < len(arr) and arr[j] <= bucket and (bucket > 0):
					bucket -= arr[j]
					j += 1
				i = j
			return days
		low = max(weights)
		high = sum(weights)
		while low < high:
			mid = (low + high) // 2
			days_by_mid = days_taken(mid, weights)
			if days_by_mid <= D:
				high = mid
			else:
				low = mid + 1
		return low

def flip(grid, N, D, u, v):
    for x in range(max(0, u - D), min(N, u + D + 1)):
        for y in range(max(0, v - D), min(N, v + D + 1)):
            if abs(x - u) + abs(y - v) <= D:
                grid[x][y] = 1 - grid[x][y]

def is_all_zero(grid, N):
    return all(grid[i][j] == 0 for i in range(N) for j in range(N))

def solve(grid, N, D):
    operations = []
    for u in range(N):
        for v in range(N):
            if grid[u][v] == 1:
                flip(grid, N, D, u, v)
                operations.append((u, v))
                if is_all_zero(grid, N):
                    return "Possible\n" + str(len(operations)) + "\n" + "\n".join(f"{u} {v}" for u, v in operations)
    return "Impossible"

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    N = int(input[index])
    D = int(input[index + 1])
    index += 2
    grid = []
    for i in range(N):
        row = list(map(int, input[index:index + N]))
        grid.append(row)
        index += N
    print(solve(grid, N, D))

