def solve(head1, head2):
	if head1.next == None:
		head1.next = head2
		return head1
	res = Node(-1)
	dummy = res
	while head1 and head2:
		if head1.data < head2.data:
			res.next = head1
			head1 = head1.next
		else:
			res.next = head2
			head2 = head2.next
		res = res.next
	while head1:
		res.next = head1
		head1 = head1.next
		res = res.next
	while head2:
		res.next = head2
		head2 = head2.next
		res = res.next
	return dummy.next

def sortedMerge(head1, head2):
	if head1 == None:
		return head2
	if head2 == None:
		return head1
	if head1.data <= head2.data:
		return solve(head1, head2)
	else:
		return solve(head2, head1)

