-----My Solution-----

def subseq(arr_a, arr_b):
    n, m = len(arr_a), len(arr_b)
    dp = [[0] * (m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            if arr_a[i-1] == arr_b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i][j-1], dp[i-1][j])

    index = dp[-1][-1]
    # print(dp)
    res = []
    i, j = n, m
    while i > 0 and j > 0:
        if dp[i][j] == dp[i-1][j] and dp[i][j] == dp[i][j-1]:
            i -= 1
            j -= 1
        elif dp[i][j] == dp[i-1][j-1] + 1:
            res.append(arr_a[i-1])
            i -= 1
            j -= 1
        elif dp[i][j] == dp[i-1][j]:
            i -= 1
        else:
            j -= 1

    return index, res[::-1]

if __name__ == '__main__':
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        arr_a = list(map(int, input().split()))
        arr_b = list(map(int, input().split()))

        print("YES" if subseq(arr_a, arr_b)[0] > 0 else "NO")
        if subseq(arr_a, arr_b)[0] > 0:
            index, res = subseq(arr_a, arr_b)
            print(index)
            print(*res)
