public class Codeforces2 {

    static PrintWriter out = new PrintWriter(System.out);

    static final int mod = 1_000_000_007;



    static class FastReader {

        BufferedReader br;

        StringTokenizer st;



        public FastReader() {

            br = new BufferedReader(new

                    InputStreamReader(System.in));

        }



        String next() {

            while (st == null || !st.hasMoreElements()) {

                try {

                    st = new StringTokenizer(br.readLine());

                } catch (IOException e) {

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }



        int nextInt() {

            return Integer.parseInt(next());

        }



        int[] readIntArray(int n) {

            int[] a = new int[n];

            for (int i = 0; i < n; i++)

                a[i] = nextInt();

            return a;

        }



        long[] readLongArray(int n) {

            long[] a = new long[n];

            for (int i = 0; i < n; i++)

                a[i] = nextLong();

            return a;

        }



        long nextLong() {

            return Long.parseLong(next());

        }



        double nextDouble() {

            return Double.parseDouble(next());

        }



        String nextLine() {

            String str = "";

            try {

                str = br.readLine();

            } catch (IOException e) {

                e.printStackTrace();

            }

            return str;

        }

    }



    //Try seeing general case

    public static void main(String[] args) {

        FastReader s = new FastReader();

        int n = s.nextInt();

        int m = s.nextInt();

        int start = s.nextInt();

        int finish = s.nextInt();



        StringBuilder sb = new StringBuilder();



        int step = 1;//Ongoing step

        if (start < finish) {

            for (int i = 0; i < m; i++) {

                int t = s.nextInt();

                int l = s.nextInt();

                int r = s.nextInt();

                while (step < t && start != finish)//I can pass note nobody is watching at this step

                {

                    sb.append("R");

                    start++;

                    step++;

                }



                if (start == finish)//If equal then return

                    break;



                //Now current step -> If I'm being looked  then X otherwise R

                if (start + 1 < l || start > r) {

                    sb.append("R");

                    start++;

                    step++;

                } else {

                    sb.append("X");

                    step++;

                }

            }

            while (start != finish) {

                sb.append("R");

                start++;

            }

        } else {

            for (int i = 0; i < m; i++) {

                int t = s.nextInt();

                int l = s.nextInt();

                int r = s.nextInt();

                while (step < t && start != finish)//I can pass note nobody is watching at this step

                {

                    sb.append("L");

                    start--;

                    step++;

                }



                if (start == finish)//If equal then return

                    break;



                //Now current step -> If I'm being looked  then X otherwise L

                if (start < l || start-1 > r) {

                    sb.append("L");

                    start--;

                    step++;

                } else {

                    sb.append("X");

                    step++;

                }

            }

            while (start != finish) {

                sb.append("L");

                start--;

            }

        }

        out.println(sb);









        out.close();

    }

























































































































































































































































































