class DataStream:

    def __init__(self, value: int, k: int):
        self.value = value
        self.k = k
        self.deque = collections.deque()
        self.cnt = 0

    def consec(self, num: int) -> bool:
        self.deque.append(num)
        if num == self.value:
            self.cnt += 1
        if (len(self.deque) > self.k):
            if self.deque[0] == self.value:
                self.cnt -= 1
            self.deque.popleft()
        return self.cnt == self.k



