int main()
{
	int N, X;
	cin >> N >> X;
	vector<int> V(N);
	for (int i = 0; i < N; i++)
		V[i] = i;

	while (V.size() > X)
	{
		int i, j, k;

		k = prr(N);
		switch (prr(4))
		{
			case 0: i = prr(N); j = prr(N); k = max(i, j); k = min(k, V.size()); break;
			case 1: i = prr(N); j = prr(N); k = max(i, j); k = MOD - k; break;
			case 2: i = prr(N); j = prr(N); k = max(i, j); k = MOD - k; break;
			case 3: i = prr(V.size() + 1); k = max(i, V.size() + 1); k = MOD - k; break;
		}
		replace(V.begin(), V.end(), k, V[V.size()]);
	}

	for (int i = 0; i < N; i++)
	{
		int c = prr(11);
		switch (c)
		{
			case 0: V.push_back(i);	break;
			case 1: V[prr(V.size())] = i; break;
		}
	}
}

