def min_possible_number(x):
    x_str = str(x)
    result = []
    for char in x_str:
        digit = int(char)
        inverted = 9 - digit
        if not result and inverted == 0:
            result.append(str(digit))
        else:
            result.append(str(min(digit, inverted)))
    return ''.join(result)

