import java.util.*;

public class CandyTesterTLE {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int t = scan.nextInt();

        while(t-- > 0) {
            int students = scan.nextInt();
            int time = scan.nextInt();

            int[] candyPreferences = new int[students];
            for (int i = 0; i < students; i++)
                candyPreferences[i] = scan.nextInt();

            Arrays.sort(candyPreferences);

            //First candy preference will be least and last will be most
            //Hence starting from 1st candy, if there would be a candy preference which is greater than that of current starting candy, then it is impossible
            for (int i = 1; i < students; i++) {
                    if (candyPreferences[i] <= candyPreferences[i - 1]) {
                        System.out.println("NO");
                        return;
                    }
            }

            //If time is less than favorite candy's time preference then it is impossible, otherwise it's possible
            if (time < candyPreferences[students - 1])
                System.out.println("NO");
            else
                System.out.println("YES");
        }
    }
