using namespace std;

// Function to find the smallest period for a string with 't' as subsequence
int findPeriod(const string &t) {
    int length = t.size();
    if (length == 1) return 1;

    // Start with the minimum period being the length of the non-repeating subsequence
    int period = length;

    for (int p = 1; p <= length / 2; ++p) {
        bool isSubsequence = true;
        int tIndex = 0;

        for (int sIndex = p; sIndex < length - 1; ++sIndex) {
            if (tIndex < length && t[tIndex] == t[sIndex]) {
                ++tIndex;
            }
            if (tIndex == length) {
                // Found a repeating subsequence with period p
                isSubsequence = false;
                break;
            }
        }
        if (isSubsequence) {
            period = p;
        }
    }
    return period;
}

// Function to construct the string 's' with 't' as subsequence and smallest period
string constructStringWithSubsequence(const string &t, int period) {
    string s(2 * t.size(), '0');
    for (char c : t) {
        for (int i = 0; i < period; ++i) {
            s[i * 2 + c - '0'] = c;
        }
    }
    return s;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        string t;
        cin >> t;
        int period = findPeriod(t);
        cout << constructStringWithSubsequence(t, period) << endl;
    }
    return 0;
}

