import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def count_primes(n):
    count = 0
    for i in range(2, n + 1):
        if is_prime(i):
            count += 1
    return count

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_selected_cells(n, m):
    max_sum = n + m
    dp = [0] * (max_sum + 1)
    for i in range(1, max_sum + 1):
        dp[i] = 1 if is_prime(i) else 0
        for j in range(2, i):
            if i % j == 0 and gcd(i // j, j) == 1:
                dp[i] = max(dp[i], dp[j] + dp[i // j])
    return dp[max_sum]

