class Solution {
public:
    long long minSpaceWastedKResizing(vector<int>& nums, int k) {
        ll len = nums.size();
        if(k == 0)
            return accumulate(nums.begin(),nums.end(),0ll);
        ll arr[len];  //find the minimum space maximum element such that minimum number of resizing happens
        memset(arr,0,sizeof(arr));  //notice here memset is not working for resetting all vals but they are zero initialized
        int temp_k = 0;
        arr[0] = 0;
        function<int(int,int,int)>h = [&](int idx, int limit, int wasted)
        {
            if(idx == -1)
            {
                if(temp_k <= k)
                    return wasted;
                return -1;   //infinite maximum space change to avoid
            }
            if(temp_k > k)
                return -1;
            temp_k++;
            for(int i = 0;i <= 1;i++)
            {
                int ls = limit ? nums[idx] : len+1;
                int ret = h(idx-1,i, wasted+ls-nums[idx]);
                if(ret != -1)
                {
                    return ret;
                }
            }
            temp_k--;
            return -1;
        };
        return h(len-1,0,0);
    }
};
