	def josephus(self, n, k):

		def Solve(nums, ind, k):
			if len(nums) == 1:
				return nums[0]
			ind = (ind + k - 1) % len(nums)
			nums.pop(ind)
			return Solve(nums, ind, k)
		nums = [x for x in range(1, n + 1)]
		return Solve(nums, 0, k)

