function input(t, i) {
  let r = [2 ];
  while (t != i) {
    let nkd = fs.readFileSync('fi' + t + '/' + i + '.txt', { encoding: 'utf-8' }).split(' ').map(w => w == 0? '': +w );
    let n = nkd[0], k = nkd[1], d = nkd[2]; r.push(solution(n, k, d));
    t = i; i += 1;
  }
  return r;
}

function solution(n, k, d) {
  let difference = [1];
  for (let j = 2; j <= n; j++) {
    difference.push(j - difference[j - 2]);
    if (difference[j - 2] > k) { break; }
  }
  let counter = 0;
  let available = k;

  for (let i = 1; i <= n; i++) {
    if (i <= d && available >= difference[i]) {
      available -= difference[i];
    } else {
      counter += 1;
      available = k - difference[i];
    }
  }
  return counter;
}

