class Solution:

	def eggDrop(self, n, k):
		dp = [[0 for x in range(k + 1)] for y in range(n + 1)]
		for i in range(n + 1):
			dp[i][0] = 0
			dp[i][1] = 1
		for j in range(1, k + 1):
			dp[1][j] = j
		for i in range(2, n + 1):
			for j in range(2, k + 1):
				dp[i][j] = float('inf')
				(lo, hi) = (1, j)
				while lo <= hi:
					mid = (lo + hi) // 2
					if dp[i - 1][mid - 1] < dp[i][j - mid]:
						lo = mid + 1
					else:
						hi = mid - 1
				dp[i][j] = 1 + max(dp[i - 1][lo - 1], dp[i][j - lo])
		return dp[n][k]

