namespace task {

const int N = 200000;

int t, n, m, p, b;

map<int, set<int>> g;

vector<bool> pp, bb, u;

vector<int> d;



namespace dsu {

vector<int> p;



int get(int x) {

  if (p[x] < 0) return x;

  return p[x] = get(p[x]);

}



bool same(int x, int y) {

  return get(x) == get(y);

}



int size(int x) {

  return -p[get(x)];

}



bool unite(int x, int y) {

  x = get(x);

  y = get(y);

  if (x == y) return false;

  if (p[x] > p[y]) swap(x, y);

  p[x] += p[y];

  p[y] = x;

  return true;

}

}



void bfs(int s) {

  queue<int> q;

  q.push(s);

  d[s] = 0;

  u[s] = true;



  while (!q.empty()) {

    int v = q.front();

    dsu::unite(s, v);

    q.pop();

    for (int to : g[v]) {

      if (bb[to] && !u[to]) {

        u[to] = true;

        q.push(to);

        d[to] = d[v] + 1;

      }

    }

  }

}



