class Solution {
public:
    int semiOrderedPermutation(vector<int>& nums) {
        int n = size(nums);
        vector<int> pos(n);
        for(int i=0;i<n;i++){
            pos[nums[i]-1] = i;
        }
        int ans = pos[0] + n-1-pos[n-1] - (pos[n-1] < pos[0]);
        return ans;
    }
