class Solution {
    public int countDistinctIntegers(int[] nums) {
         HashSet <Integer> set = new HashSet();
        for(int i : nums) {
            set.add(i);
            set.add(f(i));
        }
        return set.size();
    }
    int f(int x) {
        int res = 0;
        while(x != 0) {
            res *= 10;
            res += x % 10;
            x /= 10;
        }
        return res;
    }
}

