def solve(a, b, c, d):
    if a <= b*c:
        return -1
    else:
        return (a - b*c) // (b - a) + d

def seive(r):
	prime = [1 for i in range(r + 1)]
	prime[0] = 0
	prime[1] = 0
	for i in range(r + 1):
		if prime[i]:
			for j in range(2 * i, r + 1, i):
				prime[j] = 0
	return prime

