class Solution {
    public int[][] indexPairs(String text, String[] words) {
        List<int[]> ans=new ArrayList<>();
        for(String w:words){
            int i=0;
            while(i<text.length()){
                int cur=text.indexOf(w,i);
                if(cur!=-1){
                    ans.add(new int[]{cur,cur+w.length()-1});
                    i=cur+1;
                }
                else
                    break;
            }
        }
        int[][] res=new int[ans.size()][2];
        for(int i=0;i<res.length;i++){
            res[i]=ans.get(i);
        }
        Arrays.sort(res,new Comparator<int[]>(){
            public int compare(int[] a, int[] b){
                if(a[0]!=b[0])
                    return a[0]-b[0];
                else
                    return a[1]-b[1];
            }
        });
        return res;
    }
}

