def min_pockets(coins):
    # Create a dictionary to count the frequency of each value
    frequency = {}
    for coin in coins:
        if coin in frequency:
            frequency[coin] += 1
        else:
            frequency[coin] = 1

    # Count the number of pockets needed
    used_pockets = 0
    for value, count in frequency.items():
        if count > 1:
            used_pockets += 1

    return used_pockets

# Example usage:
