class Solution {
    public int findLengthOfShortestSubarray(int[] arr) {
        int s = 0, e = arr.length - 1;
        while (e >= 1 && arr[e - 1] <= arr[e]) e--;
        if (e == 0) return 0;
        int res = arr.length - e;
        while (s == 0 || arr[s - 1] <= arr[s]) {
            while (e < arr.length && arr[e] < arr[s]) e++;
            res = Math.max(res, arr.length - e + s + 1);
            s++;
        }
        return arr.length - res;
    }
}

