    if x > a:
        return "NO"

    # Dmitry can eat green and purple grapes, so we check if there are enough green and purple grapes for him
    if y > a + b:
        return "NO"

    # Michal can eat any grapes, so we check if there are enough grapes in total for him
    if z > a + b + c:
        return "NO"

    # If all conditions are met, it's possible to distribute the grapes
    return "YES"

