class Solution:
    def canVisitAllRooms(self, rooms):
        """
        :type rooms: List[List[int]]
        :rtype: bool
        """
        vis = {0}
        sta = [0]
        while len(sta)>0:
            rid = sta.pop()
            for k in rooms[rid]:
                if k not in vis:
                    vis.add(k)
                    sta.append(k)
        return len(vis)==len(rooms)

