from collections import deque

def solve():
	n = int(input())
	As = list(map(int, input().split()))
	edges = [[] for i in range(n + 1)]
	q = deque([])
	for i in range(1, n + 1):
		cnt = i * 2
		while cnt <= n:
			edges[i].append(cnt)
			cnt += i
	dp = [1] * (n + 1)
	s = 1
	for i in range(1, n + 1):
		if dp[i] != 1:
			continue
		q.append(i)
		while len(q) > 0:
			v = q.pop()
			x = dp[v]
			for u in edges[v]:
				if As[u - 1] > As[v - 1]:
					q.append(u)
					dp[u] = max(dp[u], x + 1)
	return max(dp)
