def maximize_bank_account(n):
    # Convert the balance to a string for easier manipulation
    s = str(n)

    # Check if the balance is positive
    if n >= 0:
        # If the last digit is less than the second last digit, remove it
        if len(s) > 1 and s[-1] < s[-2]:
            return int(s[:-1])  # Remove the last digit
        else:
            return n  # No need to remove anything
    else:
        # If the last digit is positive, remove it to get closer to zero
        if s[-1] != '-':
            return int(s[:-1])  # Remove the last digit
        else:
            # If removing the last digit still keeps it negative, remove the previous digit
            if len(s) > 2 and s[-2] != '-':
                return int(s[:-2])  # Remove the digit before last
            else:
                return int(s[:-1])  # Remove the last digit

