def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:

        # Initialize some counters to hold the number of valid triplets for types 1 and 2
        t1 = 0
        t2 = 0

        # Sort both input arrays
        nums1.sort()
        nums2.sort()

        # Function to check if a number is a perfect square
        def perfect(i):
            return int(i ** (0.5)) == i ** (0.5)

        # Iterate through the squared values of the first array and counts the number of valid
        # triplets involving these squared values in the second array
        for i in nums1:
            i = pow(i, 2)
            for j in range(len(nums2)-1):
                for k in range(j+1, len(nums2)):
                    if i == deepcopy(nums2[j]) * deepcopy(nums2[k]):
                        t1 += 1

        # Iterate through the squared values of the second array and counts the number of valid
        # triplets involving these squared values in the first array
        for i in nums2:
            i = pow(i, 2)
            for j in range(len(nums1)-1):
                for k in range(j+1, len(nums1)):
                    if i == deepcopy(nums1[j]) * deepcopy(nums1[k]):
                        t2 += 1

        # Returns the sum of the number of valid triplets for both types
        return t1 + t2

