	vt = defaultdict(list)
	for u in g:
		for val in g[u]:
			vt[val].append(u)
	return vt

def SCTarjansUtil(g, s, visited, stck, scc):
	visited[s] = True;
	stck.append(s);

	for val in g[s]:
		if visited[val] == False:
			SCTarjansUtil(g, val, visited, stck, scc)

	if s == scc[0]:
		while stck:
			temp = stck.pop()
			if temp in scc:
				scc.insert(0, temp)
			elif [True for v in range(len(scc)) if scc[v] == temp]:
				scc = scc[:scc.index(temp) + 1]
		return scc

def SCTarjansCalc(n, g, vt):
	visited =  n*[False]
	stck = []
	scc = []

	for i in range(0, n):
		if visited[i] == False:
			scc = SCTarjansUtil(g, i, visited, stck, scc)

	return scc

def tarjans(V, Edges):
	g = defaultdict(list)
	vt = defaultdict(list)

	for i in range(0, len(Edges)):
		g[Edges[i][0]].append(Edges[i][1])
		vt[Edges[i][1]].append(Edges[i][0])

	return sorted(SCTarjansCalc(V, g, getTranspose(V, vt)))
