class Solution:

	def countPairs(self, root1, root2, x):
		count = 0
		bst1Nodes = set()

		def findpairs(root):
			nonlocal count
			if x - root.data in bst1Nodes:
				count += 1
			if root.left:
				findpairs(root.left)
			if root.right:
				findpairs(root.right)

		def traverse(root):
			bst1Nodes.add(root.data)
			if root.left:
				traverse(root.left)
			if root.right:
				traverse(root.right)
		traverse(root1)
		findpairs(root2)
		return count

