def get_winner(bids):
	bids = [[j, i + 1] for (i, j) in enumerate(bids)]
	bids.sort()
	unique = True
	cur_winner = bids[0]
	for b in bids[1:]:
		if b[0] != cur_winner[0]:
			if unique:
				return cur_winner[1]
			else:
				cur_winner = b
				unique = True
		else:
			unique = False
	if unique:
		return cur_winner[1]
	return -1
