import sys

def solve(n, skills):
    skill_counts = {}
    for skill in skills:
        if skill not in skill_counts:
            skill_counts[skill] = 0
        skill_counts[skill] += 1

    sorted_skills = sorted(skill_counts.items(), key=lambda x: x[1], reverse=True)

    distinct_skills_count = len(skill_counts)
    max_team_size = 0

    for team_size in range(1, distinct_skills_count + 1):
        remaining_students = n - team_size
        if remaining_students < team_size:
            continue

        skills_for_first_team = set()
        for skill, _ in sorted_skills:
            if len(skills_for_first_team) < team_size:
                skills_for_first_team.add(skill)
            else:
                break

        skills_for_second_team = []
        for skill, count in sorted_skills:
            if skill not in skills_for_first_team:
                skills_for_second_team.append((skill, count))
            else:
                continue

        max_count = 0
        for skill, count in skills_for_second_team:
            max_count = max(max_count, count)

        if max_count >= team_size:
            max_team_size = max(max_team_size, team_size)

    return max_team_size

def main():
    input_lines = sys.stdin.readlines()
    input_index = 0
    def next_line():
        nonlocal input_index
        line = input_lines[input_index].strip()
        input_index += 1
        return line

    t = int(next_line())
    for _ in range(t):
        n = int(next_line())
        skills = list(map(int, next_line().split()))
        result = solve(n, skills)
        print(result)

if __name__ == "__main__":
    main()

