public int garbageCollection(String[] garbage, int[] travel) {
    int n = garbage.length;
    int[] metal = new int[n], paper = new int[n], glass = new int[n];
    for (int i = 0; i < n; i++) {
        for (char c : garbage[i].toCharArray()) {
            if (c == 'M') metal[i]++;
            else if (c == 'P') paper[i]++;
            else glass[i]++;
        }
    }

    int res = 0;
    res += collectGarbage(metal, travel);
    res += collectGarbage(paper, travel);
    res += collectGarbage(glass, travel);
    return res;
}

private int collectGarbage(int[] counts, int[] travel) {
    int i = 0;
    while (i < counts.length && counts[i] == 0) i++;
    if (i == counts.length) return 0;

    int res = 0;
    while (i < counts.length) {
        res += counts[i];
        i++;
        while (i < counts.length && counts[i] == 0) {
            res += travel[i - 1];
            i++;
        }
    }
    return res;
}

