class Solution:

	def isPrefect(self, num):
		x = int(math.sqrt(num))
		return x * x == num

	def checkFib(self, arr, N):
		count = 0
		for i in range(0, N):
			if self.isPrefect(5 * arr[i] * arr[i] + 4) or self.isPrefect(5 * arr[i] * arr[i] - 4):
				count += 1
		return count

