class Solution:

	def binTreeSortedLevels(self, arr, n):
		output = []
		i = 0
		while 2 ** i <= n:
			j = 2 ** i
			k = 2 ** (i + 1)
			i += 1
			output.append(sorted(arr[j - 1:k - 1]))
		return output

class Solution:

	def transform(self, s):
		ans = ''
		ans += chr(ord(s[0]) - 32)
		for i in range(0, len(s) - 1):
			if s[i] == ' ':
				ans += chr(ord(s[i + 1]) - 32)
			else:
				ans += s[i + 1]
		return ans

(h, w) = list(map(int, input().split()))
sss = ['x' * (w + 2)] + list(('x' + input() + 'x' for _ in range(h))) + ['x' * (w + 2)]
checked = [[False] * (w + 2) for _ in range(h + 2)]
ans = 0
move = [(1, 0), (-1, 0), (0, 1), (0, -1)]

def dfs(i, j):
	(w_cnt, b_cnt) = (0, 0)
	q = [(i, j, sss[i][j] == '.')]
	while q:
		(y, x, is_white) = q.pop()
		if checked[y][x]:
			continue
		checked[y][x] = True
		if is_white:
			w_cnt += 1
		else:
			b_cnt += 1
		for (di, dj) in move:
			ni = y + di
			nj = x + dj
			if checked[ni][nj]:
				continue
			nc = sss[ni][nj]
			if nc == 'x':
				continue
			elif (nc == '.') == is_white:
				continue
			else:
				q.append((ni, nj, nc == '.'))
	return w_cnt * b_cnt
for i in range(1, h + 1):
	for j in range(1, w + 1):
		if checked[i][j]:
			continue
		ans += dfs(i, j)
print(ans)

