def spaceString(S):
	lis = []
	if len(S) == 0:
		return lis
	if len(S) == 1:
		lis.append(S)
		return lis
	tempstr = spaceString(S[1:])
	for x in range(len(tempstr)):
		lis.append(S[0] + tempstr[x])
		lis.append(S[0] + ' ' + tempstr[x])
	lis.sort()
	return lis[::-1]

