class Solution {
public:
    int getMaxRepetitions(string s1, int n1, string s2, int n2) {
        // same logic like solution 1, but with dp table
        // dp store current number of matched chars and stored char
        int dp[101][101] = {0};  // state store right matched chars and stored right matched char
        int accumulate[101][101] = {0}; // accumulate matched chars
        // O(max(s1.length, s2.length)) from time
        int i = 0; // index of current s1 match
        int j = 0; // index of current s2 match
        for (int k = 0; k < n1 * n2; k++){
            // match current state if same state, we get maximum k
            // if different state, we have new state to match and update k
            if (dp[i][j] != 0){
                int mul = accumulate[i][j] / dp[i][j];  // multiply k count with mul to get k
                int number = mul * k;  // max number of k
                dp[i][j] = accumulate[i][j] - k * accumulate[i][j] % dp[i][j]; // update k with subtract current k left
                k += number;  // update k
                number = k / n2;  // get max争取 to reduce number to k
                dp[i][j] = accumulate[i][j] - k * accumulate[i][j] % dp[i][j]; // update k with subtract current k left
                k -= number * n2; // update k
            }

            // generate match, if we multiple current state
            if (accumulate[i][j] != 0) {
                dp[i][j] = accumulate[i][j] % n2; // we will generate multiple state
                accumulate[i][j] = accumulate[i][j] % n2 + 1; // we will get 1 more way to convert string
            }

            // if this state is the ending state match, return k
            if (accumulate[i][j] == n2){
                return k / n2;
            }

            // generate next state (match) if stirng matched
            // if stirng unmatched, carry one finger
            if (i != s1.length()){
                i++;
                accumulate[i][j] = accumulate[i - 1][j]; // update -1 previous state
                if (accumulate[i][j] == n2){
                    return k / n2;
                } // if match, return
            } else{
                i = 0; // string matched once, go back to first char
                accumulate[i][j] = accumulate[i][j] + 1; // update +1 current state
            }
            // if this current state is the ending state: match
            if (accumulate[i][j] == n2){
                return k / n2;
            }
        }
        return 0;
    }
};

