class Solution {
public:
    int largestPerimeter(vector<int>& A) {
        sort(A.begin(), A.end());
        int ans = 0;
        int n = A.size();
        for (int i = 1, j = i + 1; i + 1 < n; i++) {
            int sum = A[i] + A[i - 1];
            for (; j < n && A[j] < sum; j++);
            if (i < j - 1) {
                sum += A[j - 1];
                if (sum > ans) ans = sum;
            }
        }
        return ans;        
    }
};

