public int maximumLength(String s) {
    int n = s.length();
    int[][] count = new int[n + 1][26];
    int maxLen = -1;

    for (int i = 1; i <= n; i++) {
        if (s.charAt(i - 1) == s.charAt(i - 2)) {
            count[i][s.charAt(i - 1) - 'a'] = count[i - 1][s.charAt(i - 1) - 'a'] + 1;
        } else {
            count[i][s.charAt(i - 1) - 'a'] = 1;
        }

        for (int j = 0; j < 26; j++) {
            if (count[i][j] >= 3) {
                maxLen = Math.max(maxLen, 1);
            }
            for (int k = 2; k <= count[i][j]; k++) {
                if (count[i - k + 1][j] >= k) {
                    maxLen = Math.max(maxLen, k);
                }
            }
        }
    }

    return maxLen;
}

