public Map<String, Double> predict(List<String> candidates, List<List<Object>> polls) {
    Map<String, Double> projection = new HashMap<>();
    for (String candidate : candidates) {
        double sumWeightedPolls = 0;
        double sumWeights = 0;

        for (List<Object> poll : polls) {
            double pollResult = ((Number)poll.get(0)).doubleValue();
            double weight = ((Number)poll.get(1)).doubleValue();

            sumWeightedPolls += (pollResult * weight);
            sumWeights += weight;
        }

        double weightedAverage = sumWeightedPolls / sumWeights;
        projection.put(candidate, Math.round(weightedAverage * 10) / 10.0);
    }

    return projection;
}

