def flippingMatrix(matrix):
    n = len(matrix) // 2
    for i in range(n):
        for j in range(n):
            max_val = float('-inf')
            for r in range(2):
                for c in range(2):
                    val = matrix[i + r][j + c]
                    max_val = max(max_val, val)
            matrix[i][j] = max_val
    return sum(matrix[i][j] for i in range(n) for j in range(n))

