def isWoodall(N) :
    i = lowbit(N + 1)
    if i & (i - 1) :
        return False
    m = (N + 1) / i - 1
    m = int(log(m) / log(2))
    return 2 ** m == i

def isWoodall(N) :
	if(int(math.log(N+1, 3)) == math.log(N+1, 3)) :
		return 1
	elif(int(math.log(N+1, 2)) == math.log(N+1, 2)) :
		return 0
	a = math.sqrt(N + 1) + 1
	while(a >= 1) :
		if(int(math.log(N - a + 1, 2)) == math.log(N - a + 1, 2)) :
			return 1
		a = a - 1
	return 0
