def solve(s, x):
    n = len(s)
    w = [0] * n
    stack = []
    for i in range(n):
        while stack and (stack[-1] == '1' or i - stack[-1] > x):
            stack.pop()
        if stack and stack[-1] == '0':
            w[i] = '1'
            stack.append(i)
        else:
            w[i] = '0'
            stack.append(i)
    return ''.join(w) if stack else -1

