  seg_tree diff_tree(n, INF, min_merge);
  seg_tree index_tree(m, -1, max_merge);
  index_tree.update(lower_index(a[0]), 0, max_update);
  vector<int> ans(q);
  for (int i = 1; i < n; ++i) {
    {
      int lower = -INF, upper = a[i];
      while (true) {
        if (lower_index(lower) == upper_index(upper)) {
          break;
        }
        int pos = index_tree.get(lower_index(lower), upper_index(upper));
        if (pos == -1) {
          break;
        }
        diff_tree.update(pos, a[i] - a[pos], min_update);
        lower = (a[pos] + a[i]) / 2 + 1;
      }
    }
    {
      int lower = a[i], upper = INF;
      while (true) {
        if (lower_index(lower) == upper_index(upper)) {
          break;
        }
        int pos = index_tree.get(lower_index(lower), upper_index(upper));
        if (pos == -1) {
          break;
        }
        diff_tree.update(pos, a[pos] - a[i], min_update);
        upper = (a[pos] + a[i] + 1) / 2 - 1;
      }
    }
    index_tree.update(lower_index(a[i]), i, max_update);
    for (int j : events[i]) {
      ans[j] = diff_tree.get(l[j], r[j] + 1);
    }
  }
  for (int x : ans) {
    cout << x << '\n';
  }
#ifdef TYLER
  std::cerr << "Duration: "
            << std::chrono::duration_cast<std::chrono::milliseconds>(
                   std::chrono::steady_clock::now() - start_time)
                   .count()
            << "ms\n";
#endif
  return 0;
}

