import sys
input = sys.stdin.readline

def solve():
    n = int(input())
    P = list(map(int, input().split()))
    P = [0] + P

    now = p = 1
    cnt, ans = 0, 0
    for i in range(2, n + 1):
        if P[i] > P[now]:
            if P[i] > p:
                p = P[i]
                cnt += 1
            else:
                ans += 1 - cnt % 2
        else:
            if now != i:
                ans += 1 - cnt % 2
                now = i

    print(ans + cnt + 1 - cnt % 2)

t = 1
for _ in range(t):
    solve()

class Solution:

	def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
		m = 10 ** 9 + 7

		@lru_cache(None)
		def dfs(s, e, f):
			if f < 0:
				return 0
			res = 1 if s == e else 0
			for l in locations:
				if l != s:
					res += dfs(l, e, f - abs(l - s))
			return res % m
		return dfs(locations[start], locations[finish], fuel)

